@import url("https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Noto+Sans+SC:wght@300;400;500&display=swap");

:root {
  --pink: #fcbec3;
  --cream: #fff2e9;
  --blue: #cfdee3;
  --brown: #8e656f;
  --dark: #30282c;
  --soft-dark: #51464b;
  --white: rgba(255, 255, 255, 0.72);
  --glass: rgba(255, 255, 255, 0.25);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
}

body {
  background: #ded9d5;
  color: var(--dark);
  font-family:
    "Noto Sans SC",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}

button {
  font: inherit;
}

.site {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 30px;
}

/* PHONE */

.phone-shell {
  position: relative;
  width: min(390px, 92vw);
  height: min(844px, 88vh);
  min-height: 650px;

  border-radius: 46px;
  padding: 9px;

  background: #181518;

  box-shadow:
    0 40px 90px rgba(50, 35, 40, 0.25),
    0 10px 30px rgba(50, 35, 40, 0.18);

  overflow: hidden;
}


.phone-camera {
  position: absolute;
  z-index: 30;

  top: 17px;
  left: 50%;
  transform: translateX(-50%);

  width: 90px;
  height: 25px;

  background: #111;
  border-radius: 20px;
}

.phone-screen {
  position: relative;

  width: 100%;
  height: 100%;

  border-radius: 38px;

  overflow: hidden;

  transition:
    background 0.7s ease,
    opacity 0.3s ease;
}

.phone-screen::after {
  content: "";
  position: absolute;
  inset: 0;

  pointer-events: none;

  background:
    linear-gradient(
      115deg,
      rgba(255, 255, 255, 0.14),
      transparent 25%,
      transparent 70%,
      rgba(255, 255, 255, 0.05)
    );

  z-index: 20;
}

/* STATUS BAR */

.status-bar {
  position: absolute;
  z-index: 25;

  top: 0;
  left: 0;
  right: 0;

  height: 58px;

  padding: 13px 24px 0;

  display: flex;
  align-items: center;
  justify-content: space-between;

  font-size: 12px;
  font-weight: 500;
}

.status-right {
  display: flex;
  align-items: center;
  gap: 7px;
}

.signal {
  font-size: 7px;
  letter-spacing: 1px;
}

/* LOCK SCREEN */

.lock-screen {
  background:
    radial-gradient(
      circle at 20% 25%,
      rgba(255, 255, 255, 0.65),
      transparent 30%
    ),
    radial-gradient(
      circle at 80% 75%,
      rgba(207, 222, 227, 0.8),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      #fcbec3,
      #fff2e9 50%,
      #cfdee3
    );

  display: flex;
  flex-direction: column;
  align-items: center;
}

.lock-content {
  text-align: center;
}

.lock-time {
  font-family: "Cormorant Garamond", serif;
  font-size: 82px;
  line-height: 0.9;
  letter-spacing: -3px;
  font-weight: 500;
}

.lock-date {
  margin-top: 12px;
  font-size: 12px;
  letter-spacing: 2px;
  text-transform: uppercase;
  opacity: 0.65;
}

.lock-symbol {
  margin-top: 100px;

  font-family: "Cormorant Garamond", serif;
  font-size: 48px;
}

.lock-title {
  margin-top: 4px;

  font-family: "Cormorant Garamond", serif;
  font-size: 34px;
  letter-spacing: 1px;
}

.lock-subtitle {
  margin-top: 6px;

  font-family: "Cormorant Garamond", serif;
  font-size: 16px;
  font-style: italic;
  opacity: 0.7;
}

.unlock-button {
  position: absolute;
  bottom: 55px;

  border: none;
  background: rgba(255, 255, 255, 0.32);

  padding: 11px 20px;
  border-radius: 30px;

  color: var(--dark);

  display: flex;
  align-items: center;
  gap: 13px;

  cursor: pointer;

  backdrop-filter: blur(12px);

  transition:
    transform 0.2s ease,
    background 0.2s ease;
}

.unlock-button:hover {
  transform: translateY(-2px);
  background: rgba(255, 255, 255, 0.52);
}

.unlock-arrow {
  font-size: 18px;
}

/* HOME */

.home-screen {
  position: relative;
  padding: 0 20px;
}

.home-top {
  position: absolute;
  z-index: 25;

  top: 61px;
  left: 20px;
  right: 20px;

  display: flex;
  justify-content: space-between;
  align-items: center;
}

.home-location {
  font-size: 9px;
  letter-spacing: 3px;
  opacity: 0.65;
}

.mini-button {
  width: 30px;
  height: 30px;

  border: none;
  border-radius: 50%;

  background: rgba(255, 255, 255, 0.35);

  cursor: pointer;

  backdrop-filter: blur(10px);
}

.home-widget {
  position: absolute;

  top: 125px;
  left: 22px;
  right: 22px;

  padding: 20px;

  border-radius: 24px;

  background: rgba(255, 255, 255, 0.3);

  border: 1px solid rgba(255, 255, 255, 0.3);

  backdrop-filter: blur(14px);

  box-shadow:
    0 10px 25px rgba(90, 60, 65, 0.08);
}

.widget-small-date {
  font-size: 9px;
  letter-spacing: 2px;
  opacity: 0.55;
}

.widget-main-text {
  margin-top: 12px;

  font-family: "Cormorant Garamond", serif;
  font-size: 31px;
}

.widget-sub-text {
  margin-top: 2px;

  font-family: "Cormorant Garamond", serif;
  font-size: 15px;
  font-style: italic;

  opacity: 0.65;
}

.home-app-grid {
  position: absolute;

  top: 310px;
  left: 28px;
  right: 28px;

  display: grid;
  grid-template-columns: repeat(4, 1fr);

  gap: 26px 12px;
}

.app-item {
  border: none;
  background: none;

  display: flex;
  flex-direction: column;
  align-items: center;

  cursor: pointer;

  color: var(--dark);
}

.app-icon {
  width: 58px;
  height: 58px;

  border-radius: 17px;

  display: flex;
  justify-content: center;
  align-items: center;

  font-family: "Cormorant Garamond", serif;
  font-size: 28px;

  box-shadow:
    0 8px 15px rgba(60, 40, 45, 0.1);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.app-item:hover .app-icon {
  transform: translateY(-4px) scale(1.03);

  box-shadow:
    0 12px 22px rgba(60, 40, 45, 0.14);
}

.app-pink {
  background: rgba(252, 190, 195, 0.88);
}

.app-cream {
  background: rgba(255, 242, 233, 0.9);
}

.app-blue {
  background: rgba(207, 222, 227, 0.92);
}

.app-brown {
  background: rgba(142, 101, 111, 0.88);
  color: white;
}

.app-name {
  margin-top: 7px;

  font-size: 10px;
  letter-spacing: 0.5px;

  opacity: 0.75;
}

.memory-widget {
  position: absolute;

  left: 22px;
  right: 22px;
  bottom: 105px;

  padding: 15px 17px;

  border-radius: 19px;

  background: rgba(255, 255, 255, 0.22);

  backdrop-filter: blur(12px);
}

.memory-label {
  font-size: 8px;
  letter-spacing: 2px;
  opacity: 0.5;
}

.memory-text {
  margin-top: 7px;

  font-family: "Cormorant Garamond", serif;
  font-size: 16px;
  line-height: 1.25;
}

.dock {
  position: absolute;

  left: 22px;
  right: 22px;
  bottom: 25px;

  height: 67px;

  display: flex;
  justify-content: space-around;
  align-items: center;

  border-radius: 24px;

  background: rgba(255, 255, 255, 0.25);

  backdrop-filter: blur(16px);

  border: 1px solid rgba(255, 255, 255, 0.3);
}

.dock-icon {
  width: 43px;
  height: 43px;

  border: none;
  border-radius: 14px;

  background: rgba(255, 255, 255, 0.32);

  color: var(--dark);

  cursor: pointer;

  font-size: 19px;
}

/* APP WINDOW */

.app-screen {
  background:
    radial-gradient(
      circle at 20% 10%,
      rgba(252, 190, 195, 0.35),
      transparent 35%
    ),
    #fff8f3;
}

.app-header {
  height: 78px;

  padding: 28px 18px 0;

  display: grid;
  grid-template-columns: 50px 1fr 50px;

  align-items: center;

  border-bottom: 1px solid rgba(90, 60, 65, 0.08);
}

.back-button,
.header-more {
  border: none;
  background: none;

  cursor: pointer;

  font-size: 27px;
  color: var(--dark);
}

.header-more {
  font-size: 15px;
}

.app-header-title {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  font-size: 13px;
  letter-spacing: 1px;
}

.header-app-icon {
  width: 26px;
  height: 26px;

  border-radius: 8px;

  display: flex;
  justify-content: center;
  align-items: center;

  font-family: "Cormorant Garamond", serif;
  font-size: 17px;
}

.app-content {
  height: calc(100% - 78px);

  overflow-y: auto;

  padding: 25px 20px 70px;
}

/* CHAT */

.chat-preview {
  background:
    radial-gradient(
      circle at 80% 15%,
      rgba(252, 190, 195, 0.28),
      transparent 30%
    );
}

.chat-date {
  text-align: center;

  font-size: 8px;
  letter-spacing: 2px;

  opacity: 0.4;

  margin-bottom: 30px;
}

.message {
  margin-bottom: 22px;
}

.message-name {
  margin-bottom: 5px;

  font-size: 9px;
  letter-spacing: 1px;

  opacity: 0.5;
}

.message-you {
  text-align: right;
}

.message-you .message-name {
  margin-right: 6px;
}

.message-levi,
.message-erwin {
  text-align: left;
}

.bubble {
  display: inline-block;

  padding: 10px 14px;

  max-width: 75%;

  border-radius: 17px;

  font-size: 13px;
  line-height: 1.55;
}

.message-you .bubble {
  background: var(--pink);
  border-bottom-right-radius: 5px;
}

.message-levi .bubble {
  background: #e7e1dc;
  border-bottom-left-radius: 5px;
}

.message-erwin .bubble {
  background: var(--blue);
  border-bottom-left-radius: 5px;
}

.chat-input-preview {
  position: absolute;

  left: 20px;
  right: 20px;
  bottom: 48px;

  height: 45px;

  border-radius: 23px;

  padding: 0 8px 0 16px;

  background: white;

  box-shadow:
    0 5px 20px rgba(60, 40, 45, 0.08);

  display: flex;
  justify-content: space-between;
  align-items: center;

  font-size: 11px;
  color: #aaa;
}

.chat-input-preview button {
  width: 32px;
  height: 32px;

  border: none;
  border-radius: 50%;

  background: var(--brown);
  color: white;
}

/* MUSIC */

.music-preview {
  text-align: center;

  padding-top: 50px;
}

.album-cover {
  width: 230px;
  height: 230px;

  margin: 0 auto;

  border-radius: 24px;

  background:
    radial-gradient(
      circle at 35% 30%,
      rgba(255, 255, 255, 0.8),
      transparent 25%
    ),
    linear-gradient(
      145deg,
      #fcbec3,
      #8e656f
    );

  display: flex;
  justify-content: center;
  align-items: center;

  font-family: "Cormorant Garamond", serif;
  font-size: 70px;

  color: rgba(255, 255, 255, 0.75);

  box-shadow:
    0 20px 40px rgba(70, 45, 50, 0.18);
}

.song-title {
  margin-top: 28px;

  font-family: "Cormorant Garamond", serif;
  font-size: 25px;
}

.song-artist {
  margin-top: 3px;

  font-size: 10px;
  letter-spacing: 2px;
  opacity: 0.5;
}

.music-progress {
  height: 3px;

  margin-top: 35px;

  background: #e3dcda;

  border-radius: 4px;
}

.music-progress-fill {
  width: 42%;
  height: 100%;

  background: var(--brown);

  border-radius: inherit;
}

.music-time {
  display: flex;
  justify-content: space-between;

  margin-top: 7px;

  font-size: 8px;
  opacity: 0.5;
}

.music-controls {
  margin-top: 30px;

  display: flex;
  justify-content: center;
  align-items: center;

  gap: 22px;
}

.music-controls button {
  border: none;
  background: none;

  font-size: 17px;

  cursor: pointer;
}

.music-controls .play-button {
  width: 54px;
  height: 54px;

  border-radius: 50%;

  background: var(--brown);
  color: white;

  font-size: 15px;
}

/* PHOTOS */

.photos-preview {
  padding-top: 25px;
}

.photos-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 18px;

  font-family: "Cormorant Garamond", serif;
  font-size: 22px;
}

.photos-heading span:last-child {
  font-family: "Noto Sans SC", sans-serif;

  font-size: 9px;
  letter-spacing: 1px;

  opacity: 0.45;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
}

.photo-placeholder {
  aspect-ratio: 1;

  background:
    radial-gradient(
      circle at 30% 30%,
      rgba(255, 255, 255, 0.8),
      transparent 20%
    ),
    linear-gradient(
      145deg,
      #cfdee3,
      #fcbec3
    );

  display: flex;
  justify-content: center;
  align-items: center;

  color: rgba(255, 255, 255, 0.65);

  font-family: "Cormorant Garamond", serif;
  font-size: 25px;
}

/* ICITY */

.icity-preview {
  text-align: center;

  padding-top: 50px;
}

.icity-logo {
  width: 54px;
  height: 54px;

  margin: 0 auto;

  border-radius: 18px;

  background: var(--brown);
  color: white;

  display: flex;
  align-items: center;
  justify-content: center;

  font-family: "Cormorant Garamond", serif;
  font-size: 32px;
}

.icity-intro h1 {
  margin: 15px 0 5px;

  font-family: "Cormorant Garamond", serif;
  font-size: 37px;
  font-weight: 500;
}

.icity-intro p {
  margin: 0;

  font-family: "Cormorant Garamond", serif;
  font-style: italic;

  font-size: 15px;
  line-height: 1.5;

  opacity: 0.55;
}

.icity-entry {
  margin-top: 45px;

  padding: 20px;

  text-align: left;

  background: rgba(255, 255, 255, 0.7);

  border-radius: var(--rw-radius-xl);

  box-shadow:
    0 8px 25px rgba(70, 45, 50, 0.06);
}

.icity-date {
  font-size: 8px;
  letter-spacing: 2px;

  opacity: 0.4;
}

.icity-placeholder {
  margin-top: 18px;

  color: #aaa;

  font-family: "Cormorant Garamond", serif;
  font-size: 20px;
  font-style: italic;
}

.icity-button {
  margin-top: 18px;

  padding: 12px 20px;

  border: none;
  border-radius: 20px;

  background: var(--brown);
  color: white;

  font-size: 10px;
  letter-spacing: 1px;

  cursor: pointer;
}

/* HOME INDICATOR */

.home-indicator {
  position: absolute;
  z-index: 50;

  bottom: 14px;
  left: 50%;

  transform: translateX(-50%);

  width: 105px;
  height: 4px;

  border-radius: 10px;

  background: rgba(0, 0, 0, 0.6);

  pointer-events: none;
}

/* MOBILE */

@media (max-width: 600px) {
  .site {
    padding: 0;
    min-height: 100vh;
  }

  .phone-shell {
    width: 100vw;
    height: 100vh;
    min-height: 0;

    border-radius: 0;
    padding: 0;

    box-shadow: none;
  }

  .phone-shell::before {
    display: none;
  }

  .phone-camera {
    top: 12px;
  }

  .phone-screen {
    border-radius: 0;
  }
}

@media (max-height: 750px) and (min-width: 601px) {
  .phone-shell {
    height: 92vh;
  }

  .lock-content {
    margin-top: 100px;
  }

  .lock-symbol {
    margin-top: 60px;
  }

  .home-widget {
    top: 105px;
  }

  .home-app-grid {
    top: 275px;
  }
}

/* =========================
   RUNWITHME STUDIO
   ========================= */

.studio-page {
  min-height: 100vh;
  padding: 42px 34px 70px;

  background:
    radial-gradient(
      circle at 10% 10%,
      rgba(252, 190, 195, 0.3),
      transparent 28%
    ),
    radial-gradient(
      circle at 90% 80%,
      rgba(207, 222, 227, 0.5),
      transparent 32%
    ),
    #fff8f3;

  color: var(--dark);
}

.studio-header {
  max-width: 900px;
  margin: 0 auto 30px;

  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.studio-eyebrow {
  font-size: 9px;
  letter-spacing: 4px;
  color: var(--brown);
  opacity: 0.6;
}

.studio-header h1 {
  margin: 5px 0 2px;

  font-family:
    "Cormorant Garamond",
    serif;

  font-size: 42px;
  font-weight: 500;
}

.studio-header p {
  margin: 0;

  font-size: 12px;
  color: var(--brown);
  opacity: 0.55;
}

.studio-count {
  font-family:
    "Cormorant Garamond",
    serif;

  font-size: 17px;
  color: var(--brown);
  opacity: 0.7;
}

.studio-toolbar,
.studio-actions,
.studio-batch-bar,
.studio-add-panel,
.studio-card-list {
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}

.studio-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 12px;
}

.studio-filter-group {
  display: flex;
  gap: 6px;
}

.studio-filter,
.studio-select-button {
  border: 1px solid
    rgba(142, 101, 111, 0.14);

  border-radius: var(--rw-radius-pill);

  padding: 7px 13px;

  background: rgba(255, 255, 255, 0.48);

  color: var(--brown);

  cursor: pointer;

  font-size: 11px;

  transition:
    background 0.2s ease,
    transform 0.2s ease;
}

.studio-filter:hover,
.studio-select-button:hover {
  transform: translateY(-1px);
}

.studio-filter.active {
  background: var(--pink);
  border-color: transparent;
}

.studio-select {
  border: 1px solid
    rgba(142, 101, 111, 0.14);

  border-radius: var(--rw-radius-pill);

  padding: 7px 12px;

  background: rgba(255, 255, 255, 0.6);

  color: var(--brown);

  font-size: 11px;

  outline: none;
}

.studio-actions {
  display: flex;
  justify-content: space-between;
  gap: 10px;

  margin-bottom: 14px;
}

.studio-add-button {
  border: 0;
  border-radius: var(--rw-radius-pill);

  padding: 9px 16px;

  background: var(--brown);
  color: white;

  cursor: pointer;

  font-size: 11px;

  box-shadow:
    0 7px 18px
      rgba(142, 101, 111, 0.16);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.studio-add-button:hover {
  transform: translateY(-1px);

  box-shadow:
    0 10px 22px
      rgba(142, 101, 111, 0.2);
}

.studio-add-panel {
  margin-bottom: 14px;

  padding: 18px;

  border-radius: var(--rw-radius-xl);

  background:
    rgba(255, 255, 255, 0.64);

  border: 1px solid
    rgba(255, 255, 255, 0.75);

  box-shadow:
    0 12px 35px
      rgba(90, 60, 65, 0.07);

  backdrop-filter: blur(15px);
}

.studio-panel-title {
  margin-bottom: 13px;

  font-family:
    "Cormorant Garamond",
    serif;

  font-size: 21px;
}

.studio-form-row {
  display: flex;
  gap: 10px;

  margin-bottom: 12px;
}

.studio-form-row label {
  flex: 1;

  display: flex;
  flex-direction: column;

  gap: 5px;

  font-size: 9px;

  color: var(--brown);

  letter-spacing: 1px;
}

.studio-form-row select {
  border: 1px solid
    rgba(142, 101, 111, 0.12);

  border-radius: 11px;

  padding: 8px 10px;

  background: white;

  color: var(--dark);

  outline: none;

  font-size: 11px;
}

.studio-add-panel textarea {
  width: 100%;
  min-height: 130px;

  resize: vertical;

  border: 1px solid
    rgba(142, 101, 111, 0.12);

  border-radius: 14px;

  padding: 12px;

  background: rgba(255, 255, 255, 0.76);

  color: var(--dark);

  outline: none;

  font: inherit;
  font-size: 12px;
  line-height: 1.7;
}

.studio-add-panel textarea:focus {
  border-color: rgba(142, 101, 111, 0.3);
}

.studio-add-panel textarea::placeholder {
  color: #bca8ad;
}

.studio-add-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-top: 10px;

  font-size: 10px;

  color: var(--brown);
  opacity: 0.7;
}

.studio-add-footer button {
  border: 0;
  border-radius: var(--rw-radius-pill);

  padding: 8px 15px;

  background: var(--pink);
  color: var(--brown);

  cursor: pointer;

  font-size: 10px;
}

.studio-add-footer button:disabled {
  opacity: 0.4;
  cursor: default;
}

.studio-batch-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;

  margin-bottom: 14px;

  padding: 10px 12px;

  border-radius: 17px;

  background: rgba(252, 190, 195, 0.22);

  border: 1px solid
    rgba(252, 190, 195, 0.3);
}

.studio-batch-bar span {
  margin-right: auto;

  font-size: 10px;

  color: var(--brown);
}

.studio-batch-bar button,
.studio-batch-bar select {
  border: 1px solid
    rgba(142, 101, 111, 0.12);

  border-radius: var(--rw-radius-pill);

  padding: 6px 9px;

  background: rgba(255, 255, 255, 0.65);

  color: var(--brown);

  cursor: pointer;

  font-size: 9px;
}

.studio-batch-bar .danger {
  background: rgba(142, 101, 111, 0.88);
  color: white;
  border-color: transparent;
}

.studio-card-list {
  display: flex;
  flex-direction: column;

  gap: 8px;
}

.studio-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;

  padding: 15px 16px;

  border-radius: 18px;

  background:
    rgba(255, 255, 255, 0.62);

  border: 1px solid
    rgba(255, 255, 255, 0.7);

  box-shadow:
    0 7px 20px
      rgba(90, 60, 65, 0.045);

  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease;
}

.studio-card:hover {
  transform: translateY(-1px);

  background:
    rgba(255, 255, 255, 0.78);
}

.studio-card.selected {
  border-color:
    rgba(252, 190, 195, 0.7);

  background:
    rgba(252, 190, 195, 0.14);
}

.studio-checkbox {
  position: relative;

  flex-shrink: 0;

  width: 20px;
  height: 20px;

  margin-top: 1px;

  cursor: pointer;
}

.studio-checkbox input {
  position: absolute;

  opacity: 0;

  width: 0;
  height: 0;
}

.studio-checkbox span {
  position: absolute;

  inset: 0;

  border-radius: 7px;

  border: 1px solid
    rgba(142, 101, 111, 0.25);

  background:
    rgba(255, 255, 255, 0.65);

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.studio-checkbox input:checked + span {
  background: var(--pink);

  border-color: transparent;
}

.studio-checkbox input:checked + span::after {
  content: "✓";

  position: absolute;

  left: 4px;
  top: 0px;

  color: var(--brown);

  font-size: 12px;
  font-weight: 700;
}

.studio-card-main {
  min-width: 0;
  flex: 1;
}

.studio-card-meta {
  display: flex;
  align-items: center;
  gap: 6px;

  margin-bottom: 7px;
}

.studio-character,
.studio-category,
.studio-disabled {
  display: inline-flex;
  align-items: center;

  padding: 3px 7px;

  border-radius: var(--rw-radius-pill);

  font-size: 8px;
}

.studio-levi {
  background: var(--blue);
  color: #536a72;
}

.studio-erwin {
  background: var(--brown);
  color: white;
}

.studio-category {
  background: rgba(255, 242, 233, 0.95);

  color: var(--brown);
}

.studio-disabled {
  background: rgba(142, 101, 111, 0.1);

  color: var(--brown);

  opacity: 0.65;
}

.studio-card-text {
  font-size: 13px;

  line-height: 1.6;

  word-break: break-word;
}

.studio-card-id {
  margin-top: 7px;

  font-family: monospace;

  font-size: 8px;

  color: var(--brown);

  opacity: 0.25;
}

.studio-empty {
  padding: 70px 20px;

  text-align: center;

  color: var(--brown);

  opacity: 0.45;
}

.studio-empty div {
  font-family:
    "Cormorant Garamond",
    serif;

  font-size: 42px;
}

.studio-empty p {
  font-size: 11px;
}

@media (max-width: 700px) {
  .studio-page {
    padding: 28px 16px 50px;
  }

  .studio-header {
    align-items: flex-start;
  }

  .studio-header h1 {
    font-size: 35px;
  }

  .studio-toolbar {
    align-items: stretch;
    flex-direction: column;
    gap: 9px;
  }

  .studio-select {
    width: 100%;
  }

  .studio-form-row {
    flex-direction: column;
  }

  .studio-batch-bar {
    align-items: stretch;
  }

  .studio-batch-bar span {
    width: 100%;
    margin-bottom: 3px;
  }

  .studio-batch-bar button,
  .studio-batch-bar select {
    flex: 1;
  }
}
/* =========================
   STUDIO CARD EDITOR
   ========================= */

.studio-card-actions {
  flex-shrink: 0;

  display: flex;
  align-items: center;
  gap: 5px;
}

.studio-card-actions button {
  border: 0;
  border-radius: var(--rw-radius-pill);

  padding: 6px 9px;

  font-size: 9px;

  cursor: pointer;

  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.studio-card-actions button:hover {
  transform: translateY(-1px);
}

.card-toggle {
  background: rgba(142, 101, 111, 0.1);
  color: var(--brown);
}

.card-toggle.active {
  background: rgba(207, 222, 227, 0.7);
  color: #536a72;
}

.card-edit {
  background: rgba(252, 190, 195, 0.45);
  color: var(--brown);
}

.card-delete {
  background: rgba(142, 101, 111, 0.08);
  color: var(--brown);
}

.studio-modal-backdrop {
  position: fixed;
  z-index: 100;

  inset: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 20px;

  background: rgba(48, 40, 44, 0.24);

  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.studio-edit-modal {
  width: min(520px, 100%);

  max-height: 90vh;

  overflow-y: auto;

  padding: 23px;

  border-radius: 27px;

  background:
    rgba(255, 248, 243, 0.96);

  border: 1px solid
    rgba(255, 255, 255, 0.8);

  box-shadow:
    0 25px 70px
      rgba(50, 35, 40, 0.2);
}

.studio-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  margin-bottom: 22px;
}

.studio-modal-header h2 {
  margin: 4px 0 0;

  font-family:
    "Cormorant Garamond",
    serif;

  font-size: 30px;
  font-weight: 500;
}

.studio-modal-close {
  width: 34px;
  height: 34px;

  border: 0;
  border-radius: 50%;

  background: rgba(142, 101, 111, 0.08);

  color: var(--brown);

  font-size: 22px;

  cursor: pointer;
}

.studio-edit-form {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.studio-edit-form > label {
  display: flex;
  flex-direction: column;
  gap: 6px;

  color: var(--brown);

  font-size: 9px;
  letter-spacing: 1px;
}

.studio-edit-form select,
.studio-edit-form textarea {
  width: 100%;

  border: 1px solid
    rgba(142, 101, 111, 0.12);

  border-radius: 13px;

  background:
    rgba(255, 255, 255, 0.75);

  color: var(--dark);

  outline: none;

  font: inherit;
  font-size: 12px;
}

.studio-edit-form select {
  padding: 10px;
}

.studio-edit-form textarea {
  min-height: 120px;

  resize: vertical;

  padding: 11px;

  line-height: 1.65;
}

.studio-edit-form select:focus,
.studio-edit-form textarea:focus {
  border-color:
    rgba(142, 101, 111, 0.3);
}

.studio-enabled-row {
  flex-direction: row !important;

  align-items: center;

  gap: 9px !important;
}

.studio-enabled-row span:first-child {
  margin-right: auto;
}

.studio-enabled-row small {
  font-size: 9px;
  letter-spacing: 0;
  opacity: 0.65;
}

.studio-switch {
  position: relative;

  width: 39px;
  height: 22px;

  padding: 0;

  border: 0;
  border-radius: var(--rw-radius-pill);

  background:
    rgba(142, 101, 111, 0.18);

  cursor: pointer;

  transition:
    background 0.2s ease;
}

.studio-switch span {
  position: absolute;

  top: 3px;
  left: 3px;

  width: 16px;
  height: 16px;

  border-radius: 50%;

  background: white;

  box-shadow:
    0 2px 5px
      rgba(50, 35, 40, 0.15);

  transition:
    transform 0.2s ease;
}

.studio-switch.on {
  background: var(--pink);
}

.studio-switch.on span {
  transform: translateX(17px);
}

.studio-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;

  margin-top: 23px;
}

.studio-cancel,
.studio-save {
  border: 0;
  border-radius: var(--rw-radius-pill);

  padding: 9px 17px;

  cursor: pointer;

  font-size: 10px;
}

.studio-cancel {
  background:
    rgba(142, 101, 111, 0.08);

  color: var(--brown);
}

.studio-save {
  background: var(--brown);
  color: white;
}

.studio-save:disabled {
  opacity: 0.4;
  cursor: default;
}

@media (max-width: 700px) {
  .studio-card {
    position: relative;

    padding-bottom: 49px;
  }

  .studio-card-actions {
    position: absolute;

    left: 48px;
    right: 15px;
    bottom: 12px;

    justify-content: flex-end;
  }

  .studio-card-actions button {
    flex: 0 0 auto;
  }

  .studio-edit-modal {
    padding: 19px;

    border-radius: 23px;
  }
}
/* =========================
   STUDIO MUSIC
   ========================= */

.studio-music-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.studio-music-card {
  display: flex;
  align-items: center;
  gap: 12px;

  padding: 13px 14px;

  border-radius: 19px;

  background:
    rgba(255, 255, 255, 0.58);

  border: 1px solid
    rgba(255, 255, 255, 0.65);

  box-shadow:
    0 5px 20px
      rgba(80, 55, 65, 0.045);

  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.studio-music-card:hover {
  transform: translateY(-1px);

  background:
    rgba(255, 255, 255, 0.75);
}

.studio-music-card.selected {
  background:
    rgba(252, 190, 195, 0.18);

  border-color:
    rgba(252, 190, 195, 0.5);
}

.music-cover {
  width: 46px;
  height: 46px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      rgba(252, 190, 195, 0.85),
      rgba(207, 222, 227, 0.85)
    );

  color: var(--rw-text-muted);

  font-size: 19px;
}

.studio-music-main {
  min-width: 0;
  flex: 1;
}

.studio-music-title {
  color: var(--rw-text-muted);

  font-size: 13px;
  font-weight: 700;
}

.studio-music-artist {
  margin-top: 3px;

  color: #a98790;

  font-size: 10px;
}

.studio-music-url {
  margin-top: 5px;

  overflow: hidden;

  color: #bda4aa;

  font-size: 8px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.studio-edit-form input {
  width: 100%;

  padding: 10px;

  border: 1px solid
    rgba(142, 101, 111, 0.12);

  border-radius: 13px;

  outline: none;

  background:
    rgba(255, 255, 255, 0.75);

  color: #604951;

  font-size: 12px;

  box-sizing: border-box;
}

.studio-edit-form input:focus {
  border-color:
    rgba(142, 101, 111, 0.3);
}

@media (max-width: 700px) {
  .studio-music-card {
    align-items: flex-start;

    position: relative;

    padding-bottom: 55px;
  }

  .studio-music-card
    .studio-card-actions {
    left: 60px;
    right: 10px;
    bottom: 11px;
  }
}
/* =========================
   STUDIO HOME
   ========================= */

.studio-home {
  min-height: 100vh;

  box-sizing: border-box;

  padding: 48px 34px 30px;

  background:
    radial-gradient(
      circle at 15% 10%,
      rgba(252, 190, 195, 0.32),
      transparent 32%
    ),
    radial-gradient(
      circle at 90% 20%,
      rgba(207, 222, 227, 0.4),
      transparent 30%
    ),
    #fff2e9;

  color: var(--rw-text-muted);
}

.studio-home-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  max-width: 900px;

  margin: 0 auto 34px;
}

.studio-home-header h1 {
  margin: 5px 0 7px;

  font-family:
    "Cormorant Garamond",
    Georgia,
    serif;

  font-size: 48px;
  line-height: 1;

  font-weight: 500;

  letter-spacing: -1px;
}

.studio-home-header p {
  margin: 0;

  font-size: 11px;

  color: var(--rw-text-faint);

  letter-spacing: 0.3px;
}

.studio-home-mark {
  width: 55px;
  height: 55px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 18px;

  background:
    rgba(255, 255, 255, 0.55);

  border:
    1px solid
    rgba(255, 255, 255, 0.75);

  box-shadow:
    0 8px 25px
    rgba(80, 50, 60, 0.06);

  font-size: 9px;
  letter-spacing: 2px;
}

.studio-nav-grid {
  max-width: 900px;

  margin: 0 auto;

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 12px;
}

.studio-nav-card {
  position: relative;

  min-height: 118px;

  display: flex;
  align-items: center;

  padding: 19px;

  box-sizing: border-box;

  border-radius: 24px;

  text-decoration: none;

  color: var(--rw-text-muted);

  background:
    rgba(255, 255, 255, 0.55);

  border:
    1px solid
    rgba(255, 255, 255, 0.78);

  box-shadow:
    0 10px 30px
    rgba(80, 50, 60, 0.055);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.studio-nav-card:hover {
  transform: translateY(-3px);

  background:
    rgba(255, 255, 255, 0.75);

  box-shadow:
    0 16px 35px
    rgba(80, 50, 60, 0.09);
}

.studio-nav-icon {
  width: 53px;
  height: 53px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 18px;

  font-size: 23px;
}

.studio-nav-chat
  .studio-nav-icon {
  background:
    rgba(252, 190, 195, 0.5);
}

.studio-nav-music
  .studio-nav-icon {
  background:
    rgba(207, 222, 227, 0.65);
}

.studio-nav-photos
  .studio-nav-icon {
  background:
    rgba(255, 242, 233, 0.95);
}

.studio-nav-home
  .studio-nav-icon {
  background:
    rgba(252, 190, 195, 0.3);
}

.studio-nav-settings
  .studio-nav-icon {
  background:
    rgba(142, 101, 111, 0.1);
}

.studio-nav-content {
  min-width: 0;

  margin-left: 14px;

  flex: 1;
}

.studio-nav-content h2 {
  margin: 0 0 5px;

  font-family:
    "Cormorant Garamond",
    Georgia,
    serif;

  font-size: 23px;

  font-weight: 500;
}

.studio-nav-content p {
  margin: 0;

  font-size: 9px;

  line-height: 1.5;

  color: var(--rw-text-faint);
}

.studio-nav-arrow {
  margin-left: 8px;

  color: var(--rw-text-faint);

  font-size: 25px;

  font-weight: 300;

  transition:
    transform 0.2s ease;
}

.studio-nav-card:hover
  .studio-nav-arrow {
  transform: translateX(3px);
}

.studio-home-footer {
  max-width: 900px;

  margin: 32px auto 0;

  display: flex;
  justify-content: space-between;

  color: #bda4aa;

  font-size: 8px;

  letter-spacing: 1.5px;
}

@media (max-width: 650px) {
  .studio-home {
    padding:
      30px 17px 24px;
  }

  .studio-home-header {
    margin-bottom: 24px;
  }

  .studio-home-header h1 {
    font-size: 40px;
  }

  .studio-home-mark {
    width: 46px;
    height: 46px;

    border-radius: 15px;
  }

  .studio-nav-grid {
    grid-template-columns: 1fr;
  }

  .studio-nav-card {
    min-height: 100px;

    padding: 16px;
  }

  .studio-nav-icon {
    width: 47px;
    height: 47px;

    border-radius: 16px;
  }

  .studio-nav-content h2 {
    font-size: 21px;
  }

  .studio-home-footer {
    flex-direction: column;

    gap: 6px;
  }
}
/* RUNWITHME SETTINGS */

.studio-settings-page {
  min-height: 100%;
  box-sizing: border-box;
  padding-bottom: 50px;
  transition:
    background-color .25s ease,
    color .25s ease;
}

.studio-settings-page.studio-light {
  --settings-bg: #fff2e9;
  --settings-card: rgba(255,255,255,.72);
  --settings-card-strong: rgba(255,255,255,.9);
  --settings-text: #8e656f;
  --settings-muted: #b8949c;
  --settings-border: rgba(142,101,111,.12);
  --settings-accent: #fcbec3;
  --settings-accent-text: #8e656f;
}

.studio-settings-page.studio-dark {
  --settings-bg: #29242a;
  --settings-card: rgba(58,50,58,.82);
  --settings-card-strong: rgba(65,55,64,.95);
  --settings-text: #fff2e9;
  --settings-muted: #c8aeb5;
  --settings-border: rgba(255,242,233,.1);
  --settings-accent: #70525b;
  --settings-accent-text: #fff2e9;
}

.studio-settings-page {
  background:
    radial-gradient(
      circle at 10% 5%,
      rgba(252,190,195,.25),
      transparent 28%
    ),
    var(--settings-bg);
  color: var(--settings-text);
}

.studio-settings-page .studio-header {
  position: relative;
}

.studio-back-link {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  color: var(--settings-text);
  font-size: 13px;
  padding: 9px 13px;
  border: 1px solid var(--settings-border);
  border-radius: 14px;
  background: var(--settings-card);
  transition:
    transform .15s ease,
    background-color .15s ease;
}

.studio-back-link:hover {
  transform: translateY(-1px);
}

.studio-toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  z-index: 100;
  padding: 10px 16px;
  border-radius: 15px;
  background: #8e656f;
  color: #fff2e9;
  font-size: 12px;
  box-shadow: 0 8px 30px rgba(60,40,50,.2);
  animation: settings-toast-in .2s ease;
}

@keyframes settings-toast-in {
  from {
    opacity: 0;
    transform: translate(-50%, 8px);
  }

  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.settings-sections {
  display: flex;
  flex-direction: column;
  gap: 28px;
  max-width: 900px;
}

.settings-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.settings-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 5px;
}

.settings-section-label {
  display: block;
  margin-bottom: 3px;
  color: var(--settings-muted);
  font-size: 9px;
  letter-spacing: .16em;
}

.settings-section-heading h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.settings-section-icon {
  width: 35px;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: var(--settings-card);
  border: 1px solid var(--settings-border);
  font-size: 17px;
}

.settings-card {
  overflow: hidden;
  border: 1px solid var(--settings-border);
  border-radius: 20px;
  background: var(--settings-card);
  box-shadow: 0 8px 30px rgba(90,55,65,.05);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.settings-row {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 17px 19px;
  box-sizing: border-box;
}

.settings-row > div:first-child {
  min-width: 0;
}

.settings-row strong,
.settings-data-summary strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
}

.settings-row span,
.settings-data-summary span {
  display: block;
  margin-top: 4px;
  color: var(--settings-muted);
  font-size: 10px;
  line-height: 1.5;
}

.settings-segment {
  flex-shrink: 0;
  display: flex;
  gap: 3px;
  padding: 3px;
  border-radius: 13px;
  background: rgba(142,101,111,.08);
}

.settings-segment button {
  border: 0;
  border-radius: 10px;
  padding: 8px 10px;
  background: transparent;
  color: var(--settings-muted);
  font-size: 10px;
  cursor: pointer;
}

.settings-segment button.active {
  background: var(--settings-accent);
  color: var(--settings-accent-text);
  font-weight: 700;
}

.settings-data-summary {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 19px;
  border-bottom: 1px solid var(--settings-border);
}

.settings-data-number {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: var(--settings-accent);
  color: var(--settings-accent-text);
  font-size: 19px;
  font-weight: 700;
}

.settings-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.settings-action {
  min-height: 78px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 19px;
  box-sizing: border-box;
  border: 0;
  background: transparent;
  color: var(--settings-text);
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: background-color .15s ease;
}

.settings-action + .settings-action {
  border-left: 1px solid var(--settings-border);
}

.settings-action:hover {
  background: var(--settings-card-strong);
}

.settings-action-icon {
  width: 35px;
  height: 35px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: rgba(252,190,195,.45);
  color: var(--settings-text);
  font-size: 16px;
}

.settings-action strong {
  display: block;
  font-size: 12px;
}

.settings-action small {
  display: block;
  margin-top: 3px;
  color: var(--settings-muted);
  font-size: 9px;
}

.settings-divider {
  height: 1px;
  background: var(--settings-border);
}

.settings-danger-row {
  min-height: 78px;
}

.settings-danger-button {
  flex-shrink: 0;
  border: 1px solid rgba(142,101,111,.16);
  border-radius: 11px;
  padding: 8px 12px;
  background: transparent;
  color: var(--settings-text);
  font-size: 10px;
  cursor: pointer;
  transition:
    background-color .15s ease,
    transform .15s ease;
}

.settings-danger-button:hover {
  background: rgba(252,190,195,.35);
  transform: translateY(-1px);
}

.settings-about {
  display: flex;
  align-items: center;
  gap: 13px;
  max-width: 900px;
  margin-top: 3px;
  padding: 16px 18px;
  border: 1px solid var(--settings-border);
  border-radius: 18px;
  background: var(--settings-card);
