/* =========================================================
   RUNWITHME APP
   全屏自适应 App 框架
   ========================================================= */
/* ---------- 基础 ---------- */
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
}
body {
  min-width: 0;
  min-height: 0;
}
* {
  box-sizing: border-box;
}
/* ---------- 最外层 ---------- */
.site {
  position: fixed;
  inset: 0;
  width: 100vw;
  width: 100dvw;
  height: 100vh;
  height: 100vh;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
}
/* ---------- RunWithme 本体 ---------- */
.runwithme-app {
  position: relative;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;
  border-radius: 0;
  box-shadow: none;
}
/* =========================================================
   彻底关闭旧的“手机模型”
   ========================================================= */
/* 旧手机壳不再拥有任何手机外观 */
.phone-shell,
.phone-shell.chat-shell {
  position: relative;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
  overflow: hidden;
}
/* 如果旧 CSS 仍然生成这些元素，直接隐藏 */
.phone-camera,
.home-indicator,
.status-bar {
  display: none !important;
}
/* =========================================================
   所有页面统一成为全屏 App 页面
   ========================================================= */
.phone-screen,
.app-screen,
.app-screen.phone-screen,
.chat-page,
.chat-page.phone-screen {
  position: relative;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
  overflow: hidden;
}
/* App 页面自身也不要再继承“手机屏幕”限制 */
.app-screen {
  display: flex;
  flex-direction: column;
}
/* =========================================================
   Lock Screen
   ========================================================= */
.lock-screen {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100%;
  overflow: hidden;
  border-radius: 0;
}
/* =========================================================
   Home Screen
   ========================================================= */
.home-screen {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100%;
  overflow: hidden;
  border-radius: 0;
  background-size: cover;
  background-position: center;
}
/* Home 顶部区域 */
.home-top {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding:
    clamp(18px, 3vw, 32px)
    clamp(18px, 4vw, 48px)
    0;
  flex-shrink: 0;
}
/* Home Widget */
.home-widget {
  width: min(90%, 760px);
  margin:
    clamp(24px, 6vh, 72px)
    auto
    0;
}
/* App Grid */
.home-app-grid {
  width: min(92%, 900px);
  margin:
    clamp(28px, 6vh, 70px)
    auto
    0;
  display: grid;
  grid-template-columns:
    repeat(auto-fit, minmax(82px, 1fr));
  gap:
    clamp(18px, 3vw, 36px);
  justify-items: center;
}
/* Memory */
.memory-widget {
  width: min(90%, 700px);
  margin:
    clamp(30px, 6vh, 70px)
    auto
    0;
}
/* Dock */
.dock {
  position: absolute;
  left: 50%;
  bottom: clamp(18px, 4vh, 40px);
  transform: translateX(-50%);
  width: min(92%, 520px);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: clamp(12px, 3vw, 28px);
  padding: clamp(10px, 1.5vw, 16px);
  border-radius: 28px;
  /* 保留原来的透明玻璃感 */
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}
/* =========================================================
   App Header
   ========================================================= */
.app-header {
  width: 100%;
  min-height: 58px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  padding:
    10px
    clamp(14px, 3vw, 32px);
  gap: 12px;
  z-index: 10;
}
.app-header-title {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}
/* =========================================================
   App Content
   ========================================================= */
.app-content {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  -webkit-overflow-scrolling: touch;
}
/* =========================================================
   Chat
   ========================================================= */
/*
   Chat 现在不是“手机里的页面”，
   而是 RunWithme 本身的一个全屏 App。
*/
.chat-page {
  position: relative !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
}
/* Chat 顶栏 */
.chat-page .telegram-header {
  width: 100%;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  min-height: 58px;
  padding:
    8px
    clamp(12px, 3vw, 32px);
  gap: 12px;
}
/* 不再使用 Chat 顶栏头像 */
.chat-page .telegram-avatar-group {
  display: none !important;
}
.chat-page .telegram-contact {
  flex: 1;
  min-width: 0;
  margin-left: 0 !important;
}
.chat-page .telegram-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Chat 消息区 */
.chat-page .chat-messages {
  width: 100%;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding:
    12px
    clamp(12px, 4vw, 60px)
    18px;
  -webkit-overflow-scrolling: touch;
}
/* Chat 输入区 */
.chat-page .chat-composer {
  width: 100%;
  flex-shrink: 0;
  padding:
    8px
    clamp(10px, 3vw, 32px)
    max(10px, env(safe-area-inset-bottom));
  box-sizing: border-box;
}
/* =========================================================
   横屏
   ========================================================= */
@media (orientation: landscape) {
  .home-app-grid {
    width: min(82%, 900px);
    margin-top: clamp(18px, 4vh, 42px);
    grid-template-columns:
      repeat(4, minmax(90px, 150px));
    justify-content: center;
  }
  .home-widget {
    margin-top: clamp(16px, 4vh, 42px);
  }
  .memory-widget {
    margin-top: clamp(18px, 4vh, 42px);
  }
  .dock {
    bottom: clamp(12px, 3vh, 28px);
  }
  .chat-page .chat-messages {
    padding-left: clamp(24px, 10vw, 180px);
    padding-right: clamp(24px, 10vw, 180px);
  }
}
/* =========================================================
   手机竖屏
   ========================================================= */
@media (orientation: portrait) and (max-width: 600px) {
  .home-top {
    padding:
      16px
      18px
      0;
  }
  .home-widget {
    width: calc(100% - 36px);
    margin-top: 32px;
  }
  .home-app-grid {
    width: calc(100% - 42px);
    grid-template-columns:
      repeat(4, 1fr);
    gap: 22px 10px;
    margin-top: 34px;
  }
  .memory-widget {
    width: calc(100% - 42px);
    margin-top: 30px;
  }
  .dock {
    width: calc(100% - 36px);
    bottom:
      max(12px, env(safe-area-inset-bottom));
    border-radius: 24px;
  }
  .chat-page .chat-messages {
    padding-left: 12px;
    padding-right: 12px;
  }
  .chat-page .chat-composer {
    padding-left: 8px;
    padding-right: 8px;
  }
}
/* =========================================================
   手机横屏
   ========================================================= */
@media (orientation: landscape) and (max-height: 600px) {
  .home-top {
    padding-top: 10px;
  }
  .home-widget {
    margin-top: 12px;
  }
  .home-app-grid {
    margin-top: 18px;
  }
  .memory-widget {
    margin-top: 18px;
  }
  .dock {
    padding: 7px 12px;
  }
}
/* =========================================================
   平板 / 大屏
   ========================================================= */
@media (min-width: 768px) {
  .home-widget {
    width: min(80%, 850px);
  }
  .home-app-grid {
    width: min(80%, 900px);
  }
  .memory-widget {
    width: min(75%, 760px);
  }
  .chat-page .chat-messages {
    padding-left: clamp(30px, 12vw, 220px);
    padding-right: clamp(30px, 12vw, 220px);
  }
}
/* =========================================================
   桌面浏览器
   ========================================================= */
@media (min-width: 1200px) {
  .home-app-grid {
    grid-template-columns:
      repeat(4, 120px);
    justify-content: center;
    gap: 42px;
  }
  .chat-page .chat-messages {
    padding-left: max(32px, calc((100vw - 1000px) / 2));
    padding-right: max(32px, calc((100vw - 1000px) / 2));
  }
}
/* =========================================================
   iPhone / iPad Safe Area
   ========================================================= */
.runwithme-app {
  padding-top: env(safe-area-inset-top);
  padding-right: env(safe-area-inset-right);
  padding-left: env(safe-area-inset-left);
  padding-bottom: env(safe-area-inset-bottom);
}
/*
   Chat 的底部输入框自己处理 safe-area，
   因此这里不要额外再增加底部空间。
*/
.runwithme-app:has(.chat-page) {
  padding-bottom: 0;
}
/* =========================================================
   Chat 长按消息
   ========================================================= */
.chat-message-longpress-target {
  touch-action: manipulation;
  -webkit-user-select: none;
  user-select: none;
  /* 不要 -webkit-touch-callout: none */
}
.message-selected
  .chat-message-longpress-target
  .message-bubble,
.message-selected
  .chat-message-longpress-target
  .chat-call-bubble {
  transform: scale(0.98);
  transition: transform 0.12s ease;
}
.chat-message-context {
  position: relative;
  z-index: 30;
}
.chat-message-context
  .chat-message-actions {
  position: absolute;
  top: calc(100% + 8px);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow:
    0 8px 30px
      rgba(80, 50, 60, 0.16);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  white-space: nowrap;
}
.chat-dark
  .chat-message-context
  .chat-message-actions {
  background: rgba(45, 40, 44, 0.96);
}
.chat-message-context
  .chat-message-actions
  button {
  min-width: 48px;
  height: 34px;
  padding: 0 10px;
  border: none;
  border-radius: 10px;
  background: transparent;
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}
.chat-message-context
  .chat-message-actions
  button:hover {
  background: rgba(252, 190, 195, 0.3);
}
.chat-message-context
  .chat-message-actions
  button:active {
  transform: scale(0.94);
}
/* 自己的消息，菜单靠右 */
.message-you
  .chat-message-context
  .chat-message-actions {
  right: 0;
}
/* 对方消息，菜单靠左 */
.message-other
  .chat-message-context
  .chat-message-actions {
  left: 0;
}
/* 引用后输入框里的内容 */
.chat-input {
  white-space: pre-wrap;
}
/* 手机端防止操作菜单超出屏幕 */
@media (max-width: 600px) {
  .chat-message-context
    .chat-message-actions {
    max-width: calc(100vw - 32px);
    overflow-x: auto;
    scrollbar-width: none;
  }
  .chat-message-context
    .chat-message-actions::-webkit-scrollbar {
    display: none;
  }
  .chat-message-context
    .chat-message-actions
    button {
    flex-shrink: 0;
  }
}
/* =========================================================
   Chat：名字在气泡上方
   ========================================================= */

.message-content {
