  font-size: 10px;
  font-weight: 700;
  opacity: 0.7;
}

.chat-quote-preview-text {
  font-size: 11px;
  line-height: 1.4;
  opacity: 0.62;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chat-quote-preview-close {
  flex-shrink: 0;

  width: 26px;
  height: 26px;

  padding: 0;
  border: none;
  border-radius: 50%;

  background: rgba(142, 101, 111, 0.08);

  font-size: 18px;
