/* =========================================================
   Chat：消息头像与名字的布局微调
   ========================================================= */

.message-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.message-other .message-avatar {
  flex-shrink: 0;
  margin-top: 16px;
}

.message-you .message-avatar {
  flex-shrink: 0;
  margin-top: 16px;
}

.message-other .message-content,
.message-you .message-content {
  min-width: 0;
}
/* =========================================================
   RunWithme Chat
   iMessage-inspired bubble system
   ========================================================= */


/* ---------- Chat page ---------- */

.chat-page {
  --chat-bubble-other: rgba(255, 255, 255, 0.88);
  --chat-bubble-you: #fcbec3;
  --chat-text: #4f3940;
  --chat-muted: #8e656f;
  --chat-border: rgba(142, 101, 111, 0.10);

  background:
    linear-gradient(
      180deg,
      rgba(255, 242, 233, 0.96),
      rgba(252, 190, 195, 0.22)
    );

  color: var(--chat-text);
}

.chat-dark {
  --chat-bubble-other: rgba(58, 48, 53, 0.94);
  --chat-bubble-you: #8e656f;
  --chat-text: #fff2e9;
  --chat-muted: #cfdee3;
  --chat-border: rgba(255, 255, 255, 0.08);

  background:
    linear-gradient(
      180deg,
      #211c20,
      #30252a
    );
}


/* ---------- Message list ---------- */

.chat-messages {
  display: flex;
  flex-direction: column;

  overflow-y: auto;

  padding: 12px 12px 100px;

  scroll-behavior: smooth;

  -webkit-overflow-scrolling: touch;
}

.chat-date {
  align-self: center;

  margin: 4px 0 18px;

  font-size: 9px;
  font-weight: 600;
  letter-spacing: 1.4px;

  color: var(--chat-muted);

  opacity: 0.7;
}


/* ---------- Message row ---------- */

.message-row {
  display: flex;

  width: 100%;

  align-items: flex-end;

  gap: 6px;

  margin: 0;
}

.message-other {
  justify-content: flex-start;
}

.message-you {
  justify-content: flex-end;
}


/* ---------- Message grouping ---------- */

/*
   一组消息：

   第一条
   第二条
   第三条 ← 最后一条有头像 + 尖角
*/

.message-group-start {
  margin-top: 8px;
}

.message-group-middle {
  margin-top: 2px;
}

.message-group-end {
  margin-bottom: 7px;
}


/* ---------- Avatar column ---------- */

.message-avatar-column {
  width: 30px;
  min-width: 30px;

  height: 30px;

  display: flex;

  align-items: flex-end;
  justify-content: center;

  flex: 0 0 30px;
}

.message-avatar-placeholder {
  width: 30px;
  height: 30px;
}


/* ---------- Avatar ---------- */

.message-avatar {
  width: 30px;
  height: 30px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  font-size: 10px;
  font-weight: 700;

  color: white;

  box-shadow:
    0 2px 7px rgba(80, 50, 60, 0.10);
}

.avatar-levi {
  background: var(--brown);
}

.avatar-erwin {
  background: #9b7f86;
}

.avatar-you {
  background: var(--pink);
  color: var(--brown);
}


/* ---------- Message content ---------- */

.message-content {
  max-width: 76%;

  min-width: 0;

  display: flex;
  flex-direction: column;
}

.message-you .message-content {
  align-items: flex-end;
}


/* ---------- Sender name ---------- */

.message-name {
  margin: 0 8px 4px;

  font-size: 9px;
  line-height: 1;

  letter-spacing: 0.5px;

  color: var(--chat-muted);

  opacity: 0.78;
}


/* =========================================================
   iMessage-style bubbles
   ========================================================= */

.message-text-wrapper {
  display: flex;
  flex-direction: column;

  width: fit-content;
  max-width: 100%;
}


/* ---------- Main bubble ---------- */

.message-bubble {
  position: relative;

  width: fit-content;
  max-width: 100%;

  padding: 8px 12px;

  font-size: 12px;
  line-height: 1.55;

  word-break: break-word;

  border-radius: 18px;

  border: 1px solid var(--chat-border);

  box-shadow:
    0 2px 7px rgba(80, 50, 60, 0.045);

  background: var(--chat-bubble-other);

  color: var(--chat-text);

  transition:
    border-radius 0.15s ease,
    transform 0.15s ease;
}


/* ---------- You ---------- */

.message-you .message-bubble {
  background: var(--chat-bubble-you);

  color: var(--rw-text);

  border-color: rgba(255, 255, 255, 0.18);
}


/* =========================================================
   Group shape

   Middle messages:
   完整圆角，不要尖角

   End messages:
   最后一条恢复 iMessage 式尖角
   ========================================================= */


/* ---------- Other person ---------- */

/* 连续组中间 */

.message-other.message-group-middle
.message-bubble {
  border-bottom-left-radius: 18px;
}


/* 连续组最后一条 */

.message-other.message-group-end
.message-bubble {
  border-bottom-left-radius: 6px;
}


/*
   用伪元素制造非常小的圆润尖角。
   它不是传统三角形，所以边缘不会太生硬。
*/

.message-other.message-group-end
.message-bubble::after {
  content: "";

  position: absolute;

  left: -1px;
  bottom: -1px;

  width: 11px;
  height: 11px;

  background: var(--chat-bubble-other);

  clip-path: path(
    "M 0 11 C 3 10 7 7 11 0 L 11 11 Z"
  );
}


/* ---------- You ---------- */

.message-you.message-group-middle
.message-bubble {
  border-bottom-right-radius: 18px;
}

.message-you.message-group-end
.message-bubble {
  border-bottom-right-radius: 6px;
}

.message-you.message-group-end
.message-bubble::after {
  content: "";

  position: absolute;

  right: -1px;
  bottom: -1px;

  width: 11px;
  height: 11px;

  background: var(--chat-bubble-you);

  clip-path: path(
    "M 11 11 C 8 10 4 7 0 0 L 0 11 Z"
  );
}


/* ---------- Dark mode bubble tail ---------- */

.chat-dark
.message-other.message-group-end
.message-bubble::after {
  background: var(--chat-bubble-other);
}

.chat-dark
.message-you.message-group-end
.message-bubble::after {
  background: var(--chat-bubble-you);
}


/* =========================================================
   Quote
   ========================================================= */

.message-quote {
  margin-bottom: 5px;

  padding: 6px 9px;

  border-radius: 11px;

  background: rgba(255, 255, 255, 0.45);

  border-left: 3px solid var(--brown);

  color: var(--chat-text);

  max-width: 100%;
}

.message-quote-sender {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 2px;
  font-size: 8px;
  font-weight: 700;
  opacity: 0.7;
}

.message-quote-text {
  font-size: 9px;
  line-height: 1.4;

  opacity: 0.8;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-you .message-quote {
  border-left: none;
  border-right: 3px solid var(--brown);

  background: rgba(255, 255, 255, 0.32);

  text-align: right;
}


/* =========================================================
   Time
   ========================================================= */

.message-meta {
  margin-top: 3px;

  min-height: 11px;
}

.message-time {
  font-size: 8px;

  color: var(--chat-muted);

  opacity: 0.52;
}

.message-you .message-meta {
  text-align: right;
}


/* =========================================================
   Deleted / recalled
   ========================================================= */

.message-deleted,
.message-recalled {
  padding: 7px 10px;

  font-size: 10px;

  color: var(--chat-muted);

  opacity: 0.7;

  font-style: italic;
}


/* =========================================================
   Call bubble
   ========================================================= */

.chat-call-bubble {
  display: flex;

  align-items: center;

  gap: 8px;

  min-width: 150px;

  padding: 9px 11px;

  border-radius: 17px;

  background: var(--chat-bubble-other);

  border: 1px solid var(--chat-border);

  box-shadow:
    0 2px 7px rgba(80, 50, 60, 0.045);
}

.message-you .chat-call-bubble {
  background: var(--chat-bubble-you);
}

.chat-call-icon {
  width: 28px;
  height: 28px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255, 255, 255, 0.45);

  font-size: 12px;
}

.chat-call-info {
  display: flex;
  flex-direction: column;

  gap: 2px;
}

.chat-call-info strong {
  font-size: 10px;
}

.chat-call-info span {
  font-size: 8px;

  opacity: 0.65;
}


/* =========================================================
   Selected message
   ========================================================= */

.message-selected .message-bubble,
.message-selected .chat-call-bubble {
  transform: scale(0.98);

  box-shadow:
    0 0 0 2px rgba(142, 101, 111, 0.16),
    0 4px 12px rgba(80, 50, 60, 0.08);
}


/* =========================================================
   System message
   ========================================================= */

.chat-system-message {
  align-self: center;

  margin: 7px 0 10px;

  padding: 5px 10px;

  border-radius: var(--rw-radius-pill);

  background: rgba(255, 255, 255, 0.42);

  color: var(--chat-muted);

  font-size: 8px;

  backdrop-filter: blur(8px);
}


/* =========================================================
   Typing
   ========================================================= */

.typing-row {
  display: flex;

  align-items: flex-end;

  gap: 6px;

  margin: 3px 0 10px;
}

.typing-avatar {
  width: 30px;
  height: 30px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #9b7f86;

  color: white;

  font-size: 8px;

  letter-spacing: 1px;
}

.typing-bubble {
  display: flex;

  align-items: center;

  gap: 3px;

  padding: 9px 11px;

  border-radius: 18px;

  background: var(--chat-bubble-other);

  border: 1px solid var(--chat-border);
}

.typing-bubble span {
  width: 4px;
  height: 4px;

  border-radius: 50%;

  background: var(--chat-muted);

  animation: chatTyping 1.2s infinite ease-in-out;
}

.typing-bubble span:nth-child(2) {
  animation-delay: 0.15s;
}

.typing-bubble span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes chatTyping {
  0%,
  60%,
  100% {
    transform: translateY(0);
    opacity: 0.45;
  }

  30% {
    transform: translateY(-3px);
    opacity: 1;
  }
}


/* =========================================================
   Responsive
   ========================================================= */

@media (max-width: 430px) {
  .chat-messages {
    padding-left: 9px;
    padding-right: 9px;
  }

  .message-content {
    max-width: 78%;
  }

  .message-bubble {
    font-size: 12px;
    padding: 8px 11px;
  }
}
/* =========================================================
   CHAT 布局与组件补丁
   （配合 css.txt 的气泡样式，把顶栏/底栏/引用/长按菜单补回来）
   ========================================================= */

/* ---------- 根容器：三段式 flex 布局 ---------- */
.chat-page {
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  overflow: hidden !important;
}

/* ---------- 顶栏 ---------- */
.chat-page .telegram-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 60px;
  padding: 0 clamp(12px, 3vw, 28px);
  box-sizing: border-box;
  background: rgba(255, 255, 255, 0.82);
  border-bottom: 1px solid rgba(142, 101, 111, 0.10);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  z-index: 10;
}

.chat-dark .telegram-header {
  background: rgba(48, 41, 48, 0.92);
  border-bottom-color: rgba(255, 255, 255, 0.08);
}

.chat-page .telegram-back {
  width: 38px;
