/* ---------- 消息区 ---------- */
.chat-page .chat-messages {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 14px clamp(12px, 3vw, 32px) 18px !important;
