.chat-page .chat-input-container {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 46px;
  padding: 5px 6px;
  box-sizing: border-box;
  border-radius: 23px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(142, 101, 111, 0.10);
}

.chat-dark .chat-input-container {
  background: rgba(52, 44, 51, 0.95);
  border-color: rgba(255, 255, 255, 0.08);
}

.chat-page .chat-input {
  flex: 1;
  min-width: 0;
  padding: 8px 8px;
  border: 0;
  outline: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13px;
}

.chat-page .chat-input::placeholder {
  color: rgba(142, 101, 111, 0.6);
}

.chat-dark .chat-input::placeholder {
  color: rgba(200, 174, 181, 0.7);
}

.chat-page .composer-plus,
.chat-page .composer-card,
.chat-page .composer-send {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.chat-page .composer-plus {
  background: transparent;
  color: rgba(142, 101, 111, 0.75);
  font-size: 22px;
}

.chat-page .composer-card {
  background: transparent;
  color: var(--rw-text-muted);
  font-size: 18px;
}

.composer-sticker {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 0;
  border: none;
  background: transparent;

  font-size: 17px;
  line-height: 1;

  cursor: pointer;
  -webkit-tap-highlight-color: transparent;

  transition:
    transform 0.15s ease,
