  font-weight: 700;
}

.chat-page .composer-plus:hover,
.chat-page .composer-card:hover,
.chat-page .composer-send:hover {
  transform: scale(1.06);
}

.chat-page .composer-plus:active,
.chat-page .composer-card:active,
.chat-page .composer-send:active {
  transform: scale(0.94);
}

/* ---------- 输入框上方的引用预览 ---------- */
