  gap: 10px;
  width: 100%;
  box-sizing: border-box;
  padding: 9px 12px;
  background: rgba(255, 255, 255, 0.72);
  border-top: 1px solid rgba(142, 101, 111, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.chat-dark .chat-quote-preview {
  background: rgba(35, 31, 34, 0.78);
}

.chat-quote-preview-content {
  flex: 1;
  min-width: 0;
  padding-left: 9px;
  border-left: 3px solid rgba(142, 101, 111, 0.45);
}

.chat-quote-preview-header {
  margin-bottom: 2px;
  font-size: 10px;
  font-weight: 700;
  opacity: 0.7;
}

.chat-quote-preview-text {
  font-size: 11px;
  line-height: 1.4;
