/* ---------- 长按消息操作菜单 ---------- */
.chat-message-longpress-target {
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}

.chat-message-context {
  position: relative;
  z-index: 30;
}

.chat-message-context .chat-message-actions {
  position: absolute;
  top: calc(100% + 8px);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 8px 30px rgba(80, 50, 60, 0.16);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  white-space: nowrap;
}

.chat-dark .chat-message-context .chat-message-actions {
  background: rgba(45, 40, 44, 0.96);
}

.chat-message-context .chat-message-actions button {
  min-width: 48px;
  height: 34px;
  padding: 0 10px;
  border: none;
  border-radius: 10px;
  background: transparent;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}

.chat-message-context .chat-message-actions button:hover {
  background: rgba(252, 190, 195, 0.3);
}

.chat-message-context .chat-message-actions button:active {
  transform: scale(0.94);
}

.message-you .chat-message-context .chat-message-actions {
  right: 0;
}

.message-other .chat-message-context .chat-message-actions {
  left: 0;
}

@media (max-width: 600px) {
  .chat-message-context .chat-message-actions {
    max-width: calc(100vw - 32px);
    overflow-x: auto;
    scrollbar-width: none;
  }
  .chat-message-context .chat-message-actions::-webkit-scrollbar {
    display: none;
  }
  .chat-message-context .chat-message-actions button {
    flex-shrink: 0;
  }
}
/* =========================================================
   CHAT 加号展开面板
   ========================================================= */

.chat-plus-menu {
  position: absolute;
  left: clamp(10px, 2.5vw, 28px);
  bottom: calc(
    100% + 10px
  ); /* 相对 .chat-composer 向上弹出 */

  z-index: 40;

  display: grid;
  grid-template-columns: repeat(4, minmax(58px, 1fr));
  gap: 8px;

  padding: 12px;

  border-radius: 20px;

  background: rgba(255, 248, 245, 0.94);
  border: 1px solid rgba(142, 101, 111, 0.10);

  box-shadow:
    0 14px 40px rgba(60, 40, 45, 0.16),
    0 2px 8px rgba(60, 40, 45, 0.06);

  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);

  animation: chat-plus-in 0.18s ease;
}

.chat-dark .chat-plus-menu {
  background: rgba(48, 42, 47, 0.96);
  border-color: rgba(255, 255, 255, 0.08);
}

.chat-plus-menu button {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;

  padding: 8px 4px 6px;

  border: 0;
  border-radius: 14px;

  background: transparent;
  color: inherit;

  cursor: pointer;

  transition:
    background-color 0.15s ease,
    transform 0.15s ease;
}

.chat-plus-menu button:hover {
  background: rgba(252, 190, 195, 0.22);
}

.chat-plus-menu button:active {
  transform: scale(0.94);
}

.chat-plus-menu span {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background: #ffffff;
  color: var(--rw-text-muted);

  font-size: 20px;

  box-shadow:
    0 4px 12px rgba(142, 101, 111, 0.10);
}

.chat-dark .chat-plus-menu span {
  background: #393238;
  color: #f3dfe4;
  box-shadow: none;
}

.chat-plus-menu small {
  font-size: 10px;
  line-height: 1;
  color: var(--rw-text-muted);
  opacity: 0.85;
}

.chat-dark .chat-plus-menu small {
  color: #d9bcc4;
}

/* 让面板有参考“锚点” */
.chat-composer {
  position: relative;
}

/* 打开动画 */
@keyframes chat-plus-in {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ---------- 窄屏：两列布局，更符合手机 ---------- */
@media (max-width: 480px) {
  .chat-plus-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 6px;
    padding: 10px;
    border-radius: 18px;
  }

  .chat-plus-menu span {
    width: 46px;
    height: 46px;
    font-size: 21px;
  }
}

/* ---------- 大屏：居中一点，别贴着左边 ---------- */
@media (min-width: 900px) {
  .chat-plus-menu {
    left: max(
      clamp(16px, 2.5vw, 40px),
      calc((100vw - 1000px) / 2)
    );
  }
}
