  font-size: 12px;
  line-height: 1.6;
  color: var(--rw-text-muted);
  opacity: 0.65;
}

/* 上传按钮 */

.studio-sticker-upload {
  position: relative;
  flex-shrink: 0;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 42px;
  padding: 0 17px;

  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;

  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;

  cursor: pointer;
  user-select: none;

  box-shadow:
    0 7px 18px rgba(142, 101, 111, 0.18);

  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    opacity 0.16s ease;
}

.studio-sticker-upload:hover {
  transform: translateY(-1px);
  box-shadow:
    0 10px 22px rgba(142, 101, 111, 0.22);
}

.studio-sticker-upload:active {
  transform: scale(0.96);
  opacity: 0.86;
}

.studio-sticker-upload input {
  display: none;
}

/* 空状态 */

.studio-sticker-empty {
  min-height: 190px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  border-radius: var(--rw-radius-xl);

  background: rgba(255, 255, 255, 0.42);
  border: 1px dashed rgba(142, 101, 111, 0.16);

  text-align: center;
}

.studio-sticker-empty > div {
  margin-bottom: 9px;
  font-size: 30px;
  opacity: 0.75;
}

.studio-sticker-empty p {
  margin: 0;
  color: var(--rw-text-muted);
  font-size: 13px;
  font-weight: 600;
}

.studio-sticker-empty span {
  margin-top: 5px;
  color: var(--rw-text-muted);
  font-size: 11px;
  opacity: 0.52;
}

/* 表情包网格 */

.studio-sticker-grid {
  display: grid;
  grid-template-columns:
    repeat(auto-fill, minmax(145px, 1fr));
  gap: 12px;
}

/* 单张表情包 */

.studio-sticker-card {
  position: relative;

  overflow: hidden;

  border-radius: 20px;

  background: rgba(255, 255, 255, 0.62);
  border: 1px solid rgba(142, 101, 111, 0.08);

  box-shadow:
    0 6px 18px rgba(80, 50, 60, 0.045);

  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    opacity 0.16s ease;
}

.studio-sticker-card:hover {
  transform: translateY(-2px);

  box-shadow:
    0 12px 26px rgba(80, 50, 60, 0.08);
}

.studio-sticker-card.disabled {
  opacity: 0.48;
}

/* 图片区域 */

.studio-sticker-preview {
  width: 100%;
  aspect-ratio: 1 / 1;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 15px;

  background:
    radial-gradient(
      circle at center,
      rgba(255, 255, 255, 0.78),
      rgba(255, 242, 233, 0.32)
    );
}

.studio-sticker-preview img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: contain;

  border-radius: 10px;
}

.studio-sticker-preview > span {
  font-size: 30px;
  opacity: 0.45;
}

/* 操作区域 */

.studio-sticker-actions {
  display: flex;
  align-items: center;
  gap: 7px;

  padding: 10px;
  background: rgba(255, 255, 255, 0.42);

  border-top: 1px solid rgba(142, 101, 111, 0.06);
}

.studio-sticker-actions button {
  flex: 1;
  min-width: 0;

  height: 31px;

  border: none;
  border-radius: 10px;

  font-size: 10px;
  font-weight: 600;

  cursor: pointer;

  transition:
    transform 0.12s ease,
    opacity 0.12s ease;
}

.studio-sticker-actions button:active {
  transform: scale(0.94);
}

/* 启用 / 停用 */

.studio-sticker-actions .card-toggle {
  background: rgba(207, 222, 227, 0.42);
  color: var(--rw-text-muted);
}

.studio-sticker-actions .card-toggle.active {
  background: rgba(252, 190, 195, 0.55);
  color: var(--rw-text-muted);
}

/* 删除 */

.studio-sticker-actions .card-delete {
  background: rgba(142, 101, 111, 0.08);
  color: var(--rw-text-muted);
}

.studio-sticker-actions .card-delete:hover {
  background: rgba(142, 101, 111, 0.14);
}

/* =========================================================
   STICKERS · RESPONSIVE
   ========================================================= */

@media (max-width: 650px) {
  .studio-sticker-section {
    padding: 18px;
    border-radius: var(--rw-radius-xl);
  }

  .studio-sticker-header {
    align-items: stretch;
    flex-direction: column;
    gap: 13px;
  }

  .studio-sticker-upload {
    width: 100%;
  }

  .studio-sticker-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
    gap: 8px;
  }

  .studio-sticker-actions {
    padding: 7px;
    gap: 5px;
  }

  .studio-sticker-actions button {
    height: 28px;
    font-size: 9px;
  }
}
/* RUNWITHME MUSIC STUDIO */

.music-studio-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 22px;
}

.music-studio-item {
  position: relative;
  display: grid;
  grid-template-columns: 22px 62px minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 15px 18px;
  border: 1px solid rgba(142, 101, 111, 0.12);
  border-radius: 24px;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.78),
    rgba(255, 242, 233, 0.66)
  );
  box-shadow:
    0 10px 28px rgba(142, 101, 111, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    opacity 0.18s ease;
}

.music-studio-item:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 34px rgba(142, 101, 111, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.music-item-disabled {
  opacity: 0.5;
}

.music-select {
  width: 17px;
  height: 17px;
  margin: 0;
  accent-color: var(--rw-text-muted);
  cursor: pointer;
}

.music-studio-cover {
  width: 62px;
  height: 62px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 19px;
  background: linear-gradient(
    145deg,
    #fcbec3,
    #fff2e9 58%,
    #cfdee3
  );
  color: var(--rw-text-muted);
  font-size: 25px;
  font-weight: 600;
  box-shadow:
    0 8px 18px rgba(142, 101, 111, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.music-studio-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.music-studio-info strong {
  overflow: hidden;
  color: #5f444b;
  font-size: 15px;
  font-weight: 650;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.music-studio-info > span {
  overflow: hidden;
  color: rgba(95, 68, 75, 0.62);
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.music-source-row {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  margin-top: 4px;
}

.music-source-tag {
  flex-shrink: 0;
  padding: 3px 8px;
  border-radius: var(--rw-radius-pill);
  background: rgba(252, 190, 195, 0.35);
  color: var(--rw-text-muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.music-file-name {
  overflow: hidden;
  color: rgba(95, 68, 75, 0.42);
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.music-studio-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  flex-shrink: 0;
}

.music-status-button,
.music-edit-button,
.music-delete-button {
  min-width: 48px;
  height: 34px;
  padding: 0 11px;
  border: 1px solid transparent;
  border-radius: var(--rw-radius-pill);
  font-size: 11px;
  font-weight: 650;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.music-status-button:hover,
.music-edit-button:hover,
.music-delete-button:hover {
  transform: translateY(-1px);
}

.music-status-button.enabled {
  background: rgba(252, 190, 195, 0.42);
  color: var(--rw-text-muted);
}

.music-status-button.disabled {
  background: rgba(207, 222, 227, 0.45);
  color: rgba(95, 68, 75, 0.55);
}

.music-edit-button {
  background: rgba(255, 255, 255, 0.65);
  border-color: rgba(142, 101, 111, 0.12);
  color: var(--rw-text-muted);
}

.music-edit-button:hover {
  background: rgba(255, 242, 233, 0.9);
}

.music-delete-button {
  background: rgba(142, 101, 111, 0.07);
  color: var(--rw-text-muted);
}

.music-delete-button:hover {
  background: rgba(252, 190, 195, 0.3);
}

.music-batch-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding: 10px 14px;
  border: 1px solid rgba(142, 101, 111, 0.1);
  border-radius: 18px;
  background: rgba(255, 242, 233, 0.6);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7);
  color: var(--rw-text-muted);
}

.music-batch-toolbar > span {
  margin-right: auto;
  font-size: 12px;
  font-weight: 650;
}

.music-batch-toolbar button {
  padding: 7px 12px;
  border: 1px solid rgba(142, 101, 111, 0.1);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.7);
  color: var(--rw-text-muted);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.music-batch-toolbar button:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.95);
}

.music-batch-toolbar button.danger {
  background: rgba(252, 190, 195, 0.28);
}

.music-upload-box {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 15px;
  border: 1px dashed rgba(142, 101, 111, 0.2);
  border-radius: 18px;
  background: rgba(255, 242, 233, 0.5);
}

.music-form-label {
  color: var(--rw-text-muted);
  font-size: 12px;
  font-weight: 650;
}

.music-upload-box input[type="file"] {
  width: 100%;
  padding: 8px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: rgba(95, 68, 75, 0.7);
  font-size: 12px;
}

.music-selected-file,
.music-existing-file {
  overflow: hidden;
  padding: 7px 9px;
  border-radius: 10px;
  background: rgba(207, 222, 227, 0.3);
  color: var(--rw-text-muted);
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.music-or {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 2px 0;
  color: rgba(142, 101, 111, 0.38);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.music-or::before,
.music-or::after {
  content: "";
  height: 1px;
  flex: 1;
  background: rgba(142, 101, 111, 0.12);
}

.music-or span {
  flex-shrink: 0;
}

@media (max-width: 760px) {
  .music-studio-item {
    grid-template-columns: 20px 54px minmax(0, 1fr);
    gap: 12px;
    padding: 13px;
    border-radius: 21px;
  }

  .music-studio-cover {
    width: 54px;
    height: 54px;
    border-radius: 16px;
    font-size: 21px;
  }

  .music-studio-actions {
    grid-column: 3;
    justify-content: flex-start;
    margin-top: 4px;
  }

  .music-status-button,
  .music-edit-button,
  .music-delete-button {
    height: 31px;
    min-width: 44px;
    padding: 0 10px;
    font-size: 10px;
  }

  .music-batch-toolbar {
    flex-wrap: wrap;
  }

  .music-batch-toolbar > span {
    width: 100%;
    margin-right: 0;
    margin-bottom: 2px;
  }
}

@media (max-width: 480px) {
  .music-studio-item {
    grid-template-columns: 18px 48px minmax(0, 1fr);
    gap: 10px;
  }

  .music-studio-cover {
    width: 48px;
    height: 48px;
    border-radius: 14px;
  }

  .music-source-row {
    max-width: 100%;
  }

  .music-studio-actions {
    gap: 5px;
  }
}

