.home-studio-shell {
  width: min(100%, 980px);
  margin: 0 auto;
  padding: 34px 28px 48px;
}

/* ---------- Header ---------- */

.home-studio-header {
  display: grid;
  grid-template-columns: 120px 1fr 120px;
  align-items: center;
  gap: 20px;
  margin-bottom: 34px;
}

.home-studio-header-center {
  text-align: center;
}

.home-studio-eyebrow {
  margin-bottom: 7px;
  color: var(--rw-text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.home-studio-header-center h1 {
  margin: 0;
  color: #5e4650;
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.home-studio-header-center p {
  margin: 9px 0 0;
  color: rgba(94, 70, 80, 0.62);
  font-size: 12px;
  line-height: 1.6;
}

.home-studio-back {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;

  width: fit-content;
  padding: 9px 12px;

  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 14px;

  background: rgba(255, 255, 255, 0.46);
  color: var(--rw-text-muted);

  font-size: 12px;
  cursor: pointer;

  box-shadow:
    0 5px 18px rgba(100, 70, 80, 0.06);

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  transition:
    transform 0.16s ease,
    background 0.16s ease,
    box-shadow 0.16s ease;
}

.home-studio-back:hover {
  background: rgba(255, 255, 255, 0.7);
  transform: translateY(-1px);
  box-shadow:
    0 8px 22px rgba(100, 70, 80, 0.1);
