.home-studio-back:active {
  transform: scale(0.96);
}

.home-studio-back-arrow {
  font-size: 21px;
  line-height: 12px;
}

.home-studio-header-mark {
  justify-self: end;

  display: flex;
  align-items: center;
  justify-content: center;

