  letter-spacing: 0.12em;
}

.home-studio-preview-home {
  color: rgba(255, 255, 255, 0.95);

  font-family: Georgia, serif;

  font-size: 22px;
  letter-spacing: 0.08em;

  text-shadow:
    0 3px 20px rgba(70, 50, 60, 0.12);
