.home-studio-preview-text {
  margin-top: 7px;

  color: rgba(255, 255, 255, 0.92);

  font-size: 18px;
  font-weight: 500;
}

.home-studio-preview-small {
  margin-top: 5px;

  color: rgba(255, 255, 255, 0.68);

  font-size: 9px;
}

.home-studio-preview-apps {
  display: flex;
  gap: 12px;

