/* ---------- Wallpaper options ---------- */

.home-studio-option-title {
  padding: 18px 18px 9px;

  color: var(--rw-text-muted);

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.home-studio-wallpaper-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;

  padding: 0 18px 18px;
