  padding: 9px;

  border: 1px solid rgba(142, 101, 111, 0.1);
  border-radius: 13px;

  background: rgba(255, 255, 255, 0.32);

  color: #6f5660;

  font-size: 11px;

  cursor: pointer;

  transition:
    transform 0.15s ease,
    border-color 0.15s ease,
    background 0.15s ease;
}

.home-studio-wallpaper-option:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.55);
}

.home-studio-wallpaper-option.active {
  border-color: rgba(142, 101, 111, 0.32);
  background: rgba(252, 190, 195, 0.2);
}

.home-studio-wallpaper-thumb {
