.home-studio-check {
  margin-left: auto;

  color: var(--rw-text-muted);

  font-size: 12px;
  font-weight: 700;
}

/* ---------- Avatar section ---------- */

.home-studio-avatar-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;

  padding: 18px;
}

.home-studio-avatar-item {
  display: flex;
  flex-direction: column;
  align-items: center;

  min-width: 0;
  padding: 18px 12px 15px;

  border: 1px solid rgba(142, 101, 111, 0.08);
  border-radius: 19px;

  background: rgba(255, 255, 255, 0.3);

  transition:
    transform 0.16s ease,
    background 0.16s ease;
}

.home-studio-avatar-item:hover {
  transform: translateY(-2px);
  background: rgba(255, 255, 255, 0.48);
}

.home-studio-avatar-preview {
  position: relative;

  width: 96px;
  height: 96px;

  overflow: hidden;

  border: 2px solid rgba(255, 255, 255, 0.65);
  border-radius: 50%;

  background:
    linear-gradient(
      145deg,
      rgba(252, 190, 195, 0.65),
      rgba(207, 222, 227, 0.65)
    );

  box-shadow:
    0 8px 25px rgba(100, 70, 80, 0.1);
}

.home-studio-avatar-preview img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: cover;
}

.home-studio-avatar-preview > span {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;

  color: var(--rw-text-muted);

  font-family: Georgia, serif;

  font-size: 30px;
}

.home-studio-avatar-overlay {
  position: absolute;
  right: 2px;
  bottom: 2px;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 23px;
  height: 23px;

  border: 2px solid rgba(255, 255, 255, 0.8);
  border-radius: 50%;

  background: rgba(142, 101, 111, 0.82);

  color: white;

  font-size: 8px;
  font-weight: 700;
}

.home-studio-avatar-name {
  display: flex;
  flex-direction: column;
  align-items: center;

  margin-top: 12px;

  text-align: center;
}

.home-studio-avatar-name strong {
  color: #5e4650;

  font-size: 13px;
  font-weight: 600;
}

.home-studio-avatar-name span {
  margin-top: 3px;

  color: rgba(94, 70, 80, 0.42);

  font-size: 9px;
}

.home-studio-upload-button {
  margin-top: 13px;

  width: 100%;
  justify-content: center;
}

.home-studio-remove-button {
  margin-top: 7px;

  border: none;

  background: transparent;

  color: rgba(142, 101, 111, 0.6);

  font-size: 9px;

  cursor: pointer;
}

.home-studio-remove-button:hover {
  color: var(--rw-text-muted);
  text-decoration: underline;
}

.home-studio-avatar-note {
  display: flex;
  align-items: center;
  gap: 9px;

  margin: 0 18px 18px;
  padding: 11px 13px;

  border-radius: 13px;

  background: rgba(252, 190, 195, 0.12);

  color: rgba(94, 70, 80, 0.58);

  font-size: 10px;
  line-height: 1.5;
}

.home-studio-avatar-note span {
  flex: 0 0 auto;

  color: #c9818c;

  font-size: 14px;
}

.home-studio-avatar-note p {
  margin: 0;
}

/* ---------- Footer ---------- */

.home-studio-footer {
  display: flex;
  justify-content: space-between;

  margin-top: 35px;
  padding: 0 5px;

  color: rgba(94, 70, 80, 0.35);

  font-size: 8px;
  letter-spacing: 0.1em;
}

.home-studio-footer span:last-child {
  letter-spacing: 0.03em;
}

/* ---------- Loading ---------- */

.studio-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  min-height: 70vh;

  color: var(--rw-text-muted);

  text-align: center;
}

.studio-loading > span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.studio-loading p {
  margin-top: 8px;

  color: rgba(94, 70, 80, 0.45);

  font-size: 10px;
}

