  color: #5e4650;
}

html[data-runwithme-theme="dark"] .hs-title {
  color: #fff2e9;
}

.hs-subtitle {
  margin: 6px 0 0;
  font-size: 12px;
  color: rgba(94, 70, 80, 0.55);
}

html[data-runwithme-theme="dark"] .hs-subtitle {
  color: rgba(255, 244, 239, 0.55);
}

.hs-back {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 14px;

  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.5);
  color: var(--rw-text-muted);
  font-size: 12px;
  cursor: pointer;

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  transition:
    transform 0.16s ease,
    background 0.16s ease;
}

.hs-back:hover {
  background: rgba(255, 255, 255, 0.78);
  transform: translateY(-1px);
}

html[data-runwithme-theme="dark"] .hs-back {
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(45, 40, 44, 0.6);
  color: rgba(252, 190, 195, 0.9);
}

html[data-runwithme-theme="dark"] .hs-back:hover {
  background: rgba(60, 52, 58, 0.8);
}

/* ---------- Section ---------- */

.hs-section {
  margin-bottom: 30px;
}

.hs-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
  padding: 0 4px;
}

.hs-section-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: rgba(142, 101, 111, 0.6);
}

html[data-runwithme-theme="dark"] .hs-section-label {
  color: rgba(252, 190, 195, 0.7);
}

.hs-section-title {
  margin: 3px 0 0;
  font-size: 17px;
  font-weight: 600;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .hs-section-title {
  color: #fff2e9;
}

/* ---------- Card ---------- */

.hs-card {
  padding: 20px;
  border-radius: var(--rw-radius-xl);
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow:
    0 10px 30px rgba(90, 60, 65, 0.06);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

html[data-runwithme-theme="dark"] .hs-card {
  background: rgba(45, 40, 44, 0.6);
  border-color: rgba(255, 255, 255, 0.07);
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.2);
}

/* ---------- Home Preview ---------- */

.hs-preview {
  position: relative;
  aspect-ratio: 9 / 16;
  max-width: 260px;
  margin: 0 auto 12px;
  border-radius: 26px;
  overflow: hidden;

  box-shadow:
    0 14px 40px rgba(70, 45, 50, 0.18),
    inset 0 0 0 1px rgba(255, 255, 255, 0.35);
}

.hs-preview-top {
  position: absolute;
  top: 16px;
  left: 18px;
  right: 18px;
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.85);
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
}

.hs-preview-center {
  position: absolute;
  top: 22%;
  left: 0;
  right: 0;
  text-align: center;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 3px 12px rgba(0, 0, 0, 0.2);
}

.hs-preview-time {
  font-family: var(--rw-font-serif);
  font-size: 40px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.hs-preview-date {
  margin-top: 6px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  opacity: 0.8;
}

.hs-preview-grid {
  position: absolute;
  bottom: 22%;
  left: 18px;
  right: 18px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px 8px;
  justify-items: center;
}

.hs-preview-app {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.9);
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.28);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  overflow: hidden;
}

.hs-preview-app img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hs-preview-dock {
  position: absolute;
  bottom: 12px;
  left: 18px;
  right: 18px;
  height: 42px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* ---------- Wallpaper grid ---------- */

.hs-wallpaper-group {
  margin-top: 16px;
}

.hs-wallpaper-group-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  font-size: 12px;
  font-weight: 600;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .hs-wallpaper-group-title {
  color: #fff2e9;
}

.hs-wallpaper-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.hs-wallpaper-option {
  position: relative;
  aspect-ratio: 9 / 16;
  border-radius: 14px;
  overflow: hidden;
  cursor: pointer;
  border: 2px solid transparent;
  background: rgba(255, 255, 255, 0.4);

  transition:
    transform 0.16s ease,
    border-color 0.16s ease,
    box-shadow 0.16s ease;
}

.hs-wallpaper-option:hover {
  transform: translateY(-2px);
  box-shadow:
    0 8px 20px rgba(80, 50, 60, 0.12);
}

.hs-wallpaper-option.active {
  border-color: var(--rw-text-muted);
  box-shadow:
    0 0 0 3px rgba(142, 101, 111, 0.15);
}

.hs-wallpaper-option-label {
  position: absolute;
  left: 8px;
  bottom: 6px;
  right: 8px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.35);
}

.hs-wallpaper-option.hs-upload-option {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  background:
    linear-gradient(145deg, #ffe3e6, #cfdee3);
  color: var(--rw-text-muted);
  border-color: rgba(142, 101, 111, 0.16);
}

.hs-wallpaper-option.hs-upload-option span:first-child {
  font-size: 22px;
  font-weight: 700;
}

.hs-wallpaper-option.hs-upload-option span:last-child {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
}

/* ---------- Avatars ---------- */

.hs-avatar-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  padding: 4px 0;
}

.hs-avatar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 16px 10px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(142, 101, 111, 0.08);
}

html[data-runwithme-theme="dark"] .hs-avatar-item {
  background: rgba(45, 40, 44, 0.5);
  border-color: rgba(255, 255, 255, 0.06);
}

.hs-avatar-preview {
  position: relative;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.75);
  background:
    linear-gradient(
      145deg,
      rgba(252, 190, 195, 0.7),
      rgba(207, 222, 227, 0.7)
    );
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 8px 20px rgba(80, 50, 60, 0.1);
}

.hs-avatar-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hs-avatar-preview > span {
  font-family: Georgia, serif;
  font-size: 28px;
  color: var(--rw-text-muted);
}

.hs-avatar-name {
  font-size: 12px;
  font-weight: 600;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .hs-avatar-name {
  color: #fff2e9;
}

.hs-avatar-actions {
  display: flex;
  gap: 6px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.hs-small-button {
  padding: 6px 10px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.55);
  color: var(--rw-text-muted);
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.hs-small-button:hover {
  background: rgba(255, 255, 255, 0.85);
  transform: translateY(-1px);
}

.hs-small-button.hs-remove {
  color: rgba(142, 101, 111, 0.65);
}

.hs-small-button.hs-remove:hover {
  color: var(--rw-text-muted);
  text-decoration: underline;
  background: transparent;
}

/* ---------- App Icons ---------- */

.hs-icon-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.hs-icon-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(142, 101, 111, 0.08);
}

html[data-runwithme-theme="dark"] .hs-icon-item {
  background: rgba(45, 40, 44, 0.5);
  border-color: rgba(255, 255, 255, 0.06);
}

.hs-icon-preview {
  position: relative;
  width: 54px;
  height: 54px;
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-family: var(--rw-font-serif);
  font-size: 26px;
  color: var(--rw-text-muted);
  box-shadow:
    0 4px 10px rgba(80, 50, 60, 0.08),
    inset 0 0 0 1px rgba(255, 255, 255, 0.35);
}

.hs-icon-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hs-icon-preview.hs-icon-chat {
  background: linear-gradient(145deg, #ffd4d8, #fcbec3);
}

.hs-icon-preview.hs-icon-music {
  background: linear-gradient(145deg, #fffaf3, #fff2e9);
}

.hs-icon-preview.hs-icon-fridge {
  background: linear-gradient(145deg, #e3f1f8, #c5e0ee);
  color: #3b5e6e;
}

.hs-icon-preview.hs-icon-photos {
  background: linear-gradient(145deg, #e2edf1, #cfdee3);
  color: #536a72;
}

.hs-icon-preview.hs-icon-icity {
  background: linear-gradient(145deg, #a67b85, #8e656f);
  color: #fff2e9;
}

.hs-icon-preview.hs-icon-notes {
  background: linear-gradient(145deg, #fff6d9, #ffe9b3);
  color: var(--rw-text-muted);
}

.hs-icon-preview.hs-icon-calendar {
  background: linear-gradient(145deg, #ffd9d9, #ffbaba);
  color: var(--rw-text-muted);
}

.hs-icon-info {
  flex: 1;
  min-width: 0;
}

.hs-icon-info strong {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .hs-icon-info strong {
  color: #fff2e9;
}

.hs-icon-info small {
  display: block;
  margin-top: 3px;
  font-size: 10px;
  color: rgba(94, 70, 80, 0.5);
}

html[data-runwithme-theme="dark"] .hs-icon-info small {
  color: rgba(255, 244, 239, 0.5);
}

.hs-icon-actions {
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: flex-end;
}

/* ---------- File Input（隐藏） ---------- */

.hs-hidden-input {
  display: none;
}

/* ---------- 响应式 ---------- */

@media (max-width: 600px) {
  .hs-page {
    padding: 22px 16px 50px;
  }

  .hs-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .hs-title {
    font-size: 30px;
  }

  .hs-wallpaper-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .hs-avatar-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .hs-icon-grid {
    grid-template-columns: 1fr;
  }
}
.dock-icon {
  position: relative;
  overflow: hidden;
  padding: 0;
}

.dock-icon > span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-size: 19px;
}

.dock-icon > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.dock-icon.dock-icon-custom {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.32);
}

html[data-runwithme-theme="dark"] .dock-icon.dock-icon-custom {
  border-color: rgba(255, 255, 255, 0.1);
}

/* Home Studio 里 dock 图标的默认预览底色 */
.hs-icon-preview.hs-icon-dock {
  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.75),
      rgba(207, 222, 227, 0.6)
    );
  color: var(--rw-text-muted);
}
.hs-preview-dock {
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding: 0 8px;
}

.hs-preview-dock-icon {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.9);
  font-size: 13px;
  overflow: hidden;
  flex-shrink: 0;
}

.hs-preview-dock-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
