/* ---------- 全屏通话界面 ---------- */

.call-float-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(252, 190, 195, 0.32);
  font-family: var(--rw-font-serif);
  font-size: 15px;
  color: #fff2e9;
  flex-shrink: 0;
}

.call-float-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.call-float-name {
  font-size: 12px;
  font-weight: 600;
}

.call-float-timer {
  font-size: 11px;
  letter-spacing: 0.08em;
  opacity: 0.75;
  font-variant-numeric: tabular-nums;
}

.call-float-hangup {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border: none;
  border-radius: 50%;
  background: #e05d5d;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s ease;
}

.call-float-hangup:hover {
  transform: scale(1.08);
}
.call-float-hangup:active {
  transform: scale(0.94);
}
/* =========================================================================
   RUNWITHME · CALL SYSTEM v2
   ========================================================================= */

/* ---------- 全屏通话 ---------- */

.call-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 80px 30px 60px;
  background:
    radial-gradient(
      circle at 50% 30%,
      rgba(252, 190, 195, 0.35),
      transparent 55%
    ),
    linear-gradient(180deg, #2a2226, #181418);
  color: #fff2e9;
  animation: callOverlayIn 0.3s ease;
}

@keyframes callOverlayIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.call-overlay-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
}

.call-avatar {
  width: 130px;
  height: 130px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--rw-font-serif);
  font-size: 44px;
  background: rgba(252, 190, 195, 0.28);
  border: 2px solid rgba(255, 255, 255, 0.18);
  color: #fff2e9;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  animation: callAvatarPulse 2.4s ease-in-out infinite;
}

@keyframes callAvatarPulse {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  }
  50% {
    transform: scale(1.04);
    box-shadow: 0 26px 60px rgba(0, 0, 0, 0.45);
  }
}

.call-name {
  font-family: var(--rw-font-serif);
  font-size: 36px;
  letter-spacing: 0.02em;
}

.call-status {
  font-size: 14px;
  letter-spacing: 0.16em;
  opacity: 0.72;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
}

.call-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 30px;
  padding-bottom: 20px;
}

.call-btn {
  min-width: 100px;
  height: 56px;
  padding: 0 22px;
  border: none;
  border-radius: var(--rw-radius-pill);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, background 0.15s ease;
}

.call-btn:hover { transform: translateY(-2px); }
.call-btn:active { transform: scale(0.96); }

.call-btn.accept {
  background: #7ed17e;
  color: #143c14;
}

.call-btn.decline,
.call-btn.hangup {
  background: #e05d5d;
  color: #fff2e9;
}

.call-btn.minimize {
  background: rgba(255, 255, 255, 0.18);
  color: #fff2e9;
}

