  background: rgba(252, 190, 195, 0.32);
  font-family: var(--rw-font-serif);
  font-size: 15px;
  color: #fff2e9;
  flex-shrink: 0;
}

.call-float-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.call-float-name {
  font-size: 12px;
