}

.call-float-timer {
  font-size: 11px;
  letter-spacing: 0.08em;
  opacity: 0.75;
  font-variant-numeric: tabular-nums;
}

.call-float-hangup {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border: none;
  border-radius: 50%;
  background: #e05d5d;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s ease;
}

.call-float-hangup:hover  { transform: scale(1.08); }
.call-float-hangup:active { transform: scale(0.94); }

/* ---------- 拨号对象选择器 ---------- */

.chat-call-picker {
  margin: 0 10px 8px;
  padding: 14px;
  border-radius: 20px;
  background: rgba(255, 248, 245, 0.96);
  border: 1px solid rgba(142, 101, 111, 0.1);
  box-shadow:
    0 14px 40px rgba(60, 40, 45, 0.16),
    0 2px 8px rgba(60, 40, 45, 0.06);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  animation: chat-plus-in 0.18s ease;
}

.chat-dark .chat-call-picker {
  background: rgba(48, 42, 47, 0.96);
  border-color: rgba(255, 255, 255, 0.08);
}

.chat-call-picker-title {
  margin-bottom: 12px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(142, 101, 111, 0.65);
  text-align: center;
}

.chat-dark .chat-call-picker-title {
  color: rgba(252, 190, 195, 0.7);
}

.chat-call-picker-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.chat-call-picker-options button {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 4px 8px;
  border: 0;
  border-radius: 14px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}

.chat-call-picker-options button:hover {
  background: rgba(252, 190, 195, 0.22);
}

.chat-call-picker-options button:active {
  transform: scale(0.94);
}

.chat-call-picker-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--rw-font-serif);
  font-size: 16px;
  font-weight: 700;
  color: #fff2e9;
}

.chat-call-picker-avatar.avatar-levi {
  background: #8e656f;
}

.chat-call-picker-avatar.avatar-erwin {
  background: #9b7f86;
}

.chat-call-picker-avatar.avatar-both {
  background: linear-gradient(135deg, #8e656f 50%, #9b7f86 50%);
  font-size: 11px;
}

.chat-call-picker-options small {
  font-size: 11px;
  font-weight: 600;
