  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease;
}

.music-v2-drawer-item:hover {
  background: rgba(142, 101, 111, 0.08);
}

.music-v2-drawer-item.active {
  background: rgba(252, 190, 195, 0.28);
}

.music-v2-drawer-item-cover {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(145deg, #fcbec3, #cfdee3);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--rw-text-muted);
  font-size: 16px;
  flex-shrink: 0;
}

.music-v2-drawer-item-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.music-v2-drawer-item-info strong {
  font-size: 13px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-v2-drawer-item-info small {
  font-size: 11px;
  opacity: 0.6;
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-v2-drawer-item-source {
  font-size: 9px;
  padding: 3px 7px;
  border-radius: 6px;
  background: rgba(142, 101, 111, 0.1);
  opacity: 0.7;
  flex-shrink: 0;
}

/* ---------- 上传 / 管理面板 ---------- */

.music-v2-panel-backdrop {
  position: fixed;
  inset: 0;
  z-index: 210;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: musicDrawerFade 0.2s ease;
}

.music-v2-panel {
  width: min(500px, 100%);
  max-height: 90vh;
  overflow: hidden;
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg);
  display: flex;
  flex-direction: column;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.3);
}

html[data-runwithme-theme="dark"] .music-v2-panel {
  background: #211c20;
  color: #fff2e9;
}

.music-v2-panel-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px 12px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.08);
}

.music-v2-panel-header h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.music-v2-panel-header button {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 18px;
  cursor: pointer;
}

.music-v2-panel-tabs {
  display: flex;
  gap: 6px;
  padding: 12px 20px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.08);
}

.music-v2-panel-tabs button {
  flex: 1;
  padding: 8px 12px;
  border: 0;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.08);
  color: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.music-v2-panel-tabs button.active {
  background: #fcbec3;
  color: var(--rw-text-muted);
}

.music-v2-panel-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 20px;
  overflow-y: auto;
}

.music-v2-panel-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  opacity: 0.8;
}

.music-v2-panel-form input,
.music-v2-panel-form select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(142, 101, 111, 0.16);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.6);
  color: inherit;
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"]
  .music-v2-panel-form input,
html[data-runwithme-theme="dark"]
  .music-v2-panel-form select {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.music-v2-panel-form input:focus,
.music-v2-panel-form select:focus {
  border-color: var(--rw-text-muted);
}

.music-v2-panel-primary {
  margin-top: 8px;
  padding: 12px;
  border: 0;
  border-radius: 14px;
  background: #8e656f;
  color: #fff2e9;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s ease;
}

.music-v2-panel-primary:hover {
  transform: translateY(-1px);
}

.music-v2-panel-manage {
  overflow-y: auto;
  padding: 12px 14px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.music-v2-panel-empty {
  padding: 40px 20px;
  text-align: center;
  opacity: 0.5;
  font-size: 13px;
}

.music-v2-panel-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.06);
}

.music-v2-panel-item-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.music-v2-panel-item-info strong {
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-v2-panel-item-info small {
  font-size: 10px;
  opacity: 0.55;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-v2-panel-item-toggle {
  padding: 6px 10px;
  border: 0;
  border-radius: 10px;
  background: rgba(142, 101, 111, 0.12);
  color: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}

.music-v2-panel-item-delete {
  padding: 6px 10px;
  border: 0;
  border-radius: 10px;
  background: rgba(224, 93, 93, 0.15);
  color: #e05d5d;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}

/* ---------- 邀请选择器 ---------- */

.music-v2-picker-backdrop {
  position: fixed;
  inset: 0;
  z-index: 220;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 20px;
  animation: musicDrawerFade 0.2s ease;
}

.music-v2-picker {
  width: min(420px, 100%);
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg);
  padding: 20px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.3);
}

html[data-runwithme-theme="dark"] .music-v2-picker {
  background: #211c20;
  color: #fff2e9;
}

.music-v2-picker-title {
  margin-bottom: 16px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-align: center;
  opacity: 0.6;
}

.music-v2-picker-options {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.music-v2-picker-options button {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 4px 8px;
  border: 0;
  border-radius: 14px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background 0.15s ease;
}

.music-v2-picker-options button:hover {
  background: rgba(142, 101, 111, 0.1);
}

.music-v2-picker-options button.active {
  background: rgba(252, 190, 195, 0.3);
}

.music-v2-picker-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 16px;
  font-weight: 700;
}

.music-v2-picker-avatar.avatar-you {
  background: #fcbec3;
  color: var(--rw-text-muted);
}

.music-v2-picker-avatar.avatar-levi {
  background: #8e656f;
}

.music-v2-picker-avatar.avatar-erwin {
  background: #9b7f86;
}

.music-v2-picker-avatar.avatar-both {
  background: linear-gradient(
    135deg,
    #8e656f 50%,
    #9b7f86 50%
  );
  font-size: 11px;
}

.music-v2-picker-options small {
  font-size: 10px;
  font-weight: 600;
}

.music-v2-picker-cancel {
  width: 100%;
  margin-top: 16px;
  padding: 12px;
  border: 0;
  border-radius: 14px;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
/* =========================================================================
   PHOTOS APP
   ========================================================================= */

.photos-app {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--rw-bg);
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"] .photos-app {
  background: #17131a;
  color: #fff2e9;
}

/* ---------- Header ---------- */

.photos-app-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 64px;
  padding: 0 14px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"]
  .photos-app-header {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.photos-app-back {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
  flex-shrink: 0;
}

.photos-app-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.photos-app-title {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.photos-app-title-main {
  font-size: 16px;
  font-weight: 700;
}

.photos-app-title-sub {
  font-size: 10px;
  opacity: 0.55;
  margin-top: 1px;
}

.photos-app-upload {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 22px;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s ease, transform 0.15s ease;
}

.photos-app-upload:hover {
  background: rgba(142, 101, 111, 0.18);
}

.photos-app-upload:active {
  transform: scale(0.94);
}

.photos-app-upload:disabled {
  opacity: 0.5;
  cursor: default;
}

/* ---------- Content ---------- */

.photos-app-content {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

/* ---------- Empty ---------- */

.photos-app-empty {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 40px 20px;
  text-align: center;
  opacity: 0.7;
}

.photos-app-empty-icon {
  font-size: 44px;
  opacity: 0.5;
  margin-bottom: 4px;
}

.photos-app-empty-title {
  font-size: 15px;
  font-weight: 700;
}

.photos-app-empty-desc {
  font-size: 12px;
  opacity: 0.65;
}

.photos-app-empty-btn {
  margin-top: 16px;
  padding: 10px 20px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

/* ---------- Grid（3 列，与 iOS 相册一致） ---------- */

.photos-app-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  padding: 2px;
}

.photos-app-cell {
  position: relative;
  aspect-ratio: 1 / 1;
  padding: 0;
  border: 0;
  background: rgba(142, 101, 111, 0.06);
  overflow: hidden;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.photos-app-cell:hover img {
  transform: scale(1.04);
}

.photos-app-cell img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.25s ease;
}

.photos-app-cell-loading {
  font-size: 18px;
  opacity: 0.4;
}

/* 有描述的小圆点 */
.photos-app-cell-dot {
  position: absolute;
  right: 6px;
  bottom: 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.35);
}

/* =========================================================================
   PHOTO VIEWER（全屏查看器）
   ========================================================================= */

.photo-viewer {
  position: fixed;
  inset: 0;
  z-index: 9500;
  display: flex;
  flex-direction: column;
  background: #000;
  color: #fff;
  animation: photoViewerIn 0.2s ease;
}

@keyframes photoViewerIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ---------- Top bar ---------- */

.photo-viewer-top {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.photo-viewer-top.is-hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px);
}

.photo-viewer-date {
  font-size: 12px;
  opacity: 0.75;
  text-align: center;
  flex: 1;
  padding: 0 12px;
  font-variant-numeric: tabular-nums;
}

.photo-viewer-btn {
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
  flex-shrink: 0;
}

.photo-viewer-btn:hover {
  background: rgba(255, 255, 255, 0.22);
}

.photo-viewer-btn:active {
  transform: scale(0.94);
}

.photo-viewer-btn-danger:hover {
  background: rgba(224, 93, 93, 0.7);
}

/* ---------- Image area ---------- */

.photo-viewer-image {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 0 8px;
}

.photo-viewer-image img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
  user-select: none;
  -webkit-user-drag: none;
}

.photo-viewer-loading {
  font-size: 14px;
  opacity: 0.6;
}

/* 左右导航按钮（桌面） */
.photo-viewer-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 28px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.photo-viewer-nav:hover {
  background: rgba(255, 255, 255, 0.22);
}

.photo-viewer-nav.prev {
  left: 12px;
}

.photo-viewer-nav.next {
  right: 12px;
}

/* 手机上隐藏 nav 按钮，用滑动切换 */
@media (hover: none) and (pointer: coarse) {
  .photo-viewer-nav {
    display: none;
  }
}

/* ---------- Bottom description ---------- */

.photo-viewer-bottom {
  flex-shrink: 0;
  padding: 12px 16px
    calc(16px + env(safe-area-inset-bottom));
  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.9),
    rgba(0, 0, 0, 0.5) 80%,
    rgba(0, 0, 0, 0)
  );
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.photo-viewer-bottom.is-hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateY(8px);
}

.photo-viewer-textarea {
  width: 100%;
  min-height: 56px;
  max-height: 120px;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font: inherit;
  font-size: 14px;
  line-height: 1.6;
  outline: none;
  resize: none;
  box-sizing: border-box;
  transition: border-color 0.15s ease,
    background 0.15s ease;
}

.photo-viewer-textarea:focus {
  border-color: rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.1);
}

.photo-viewer-textarea::placeholder {
  color: rgba(255, 255, 255, 0.35);
}

.photo-viewer-count {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 10px;
  letter-spacing: 0.04em;
  opacity: 0.55;
  font-variant-numeric: tabular-nums;
}
/* =========================================================================
   PHOTOS · v2 分类 / 多选 / 分类管理
   ========================================================================= */

/* ---------- 顶栏文字按钮 ---------- */

.photos-app-upload-text {
  width: auto !important;
  min-width: 44px;
  padding: 0 12px;
  border-radius: 999px !important;
  font-size: 12px !important;
  font-weight: 600;
  height: 36px;
}

/* ---------- 分类 tabs ---------- */

.photos-app-tabs {
  flex-shrink: 0;
  display: flex;
  gap: 6px;
  padding: 8px 12px 10px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .photos-app-tabs {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.photos-app-tabs::-webkit-scrollbar {
  display: none;
}

.photos-app-tab {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.08);
  color: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease;
}

.photos-app-tab:hover {
  background: rgba(142, 101, 111, 0.14);
}

.photos-app-tab.active {
  background: #8e656f;
  color: #fff2e9;
}

.photos-app-tab-count {
  font-size: 10px;
  opacity: 0.65;
  font-variant-numeric: tabular-nums;
}

.photos-app-tab.active .photos-app-tab-count {
  opacity: 0.9;
}

/* ---------- 选择模式 ---------- */

.photos-app-cell.is-selecting {
  cursor: pointer;
}

.photos-app-cell.is-selected img {
  opacity: 0.55;
}

.photos-app-cell-check {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.9);
  background: rgba(0, 0, 0, 0.3);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.photos-app-cell.is-selected .photos-app-cell-check {
  background: #8e656f;
  border-color: var(--rw-text-muted);
  transform: scale(1.05);
}

/* 底部工具条 */

.photos-app-content.has-selection-bar {
  padding-bottom: 80px;
}

.photos-app-selection-bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  gap: 10px;
  padding: 12px 16px
    calc(12px + env(safe-area-inset-bottom));
  background: rgba(255, 242, 233, 0.96);
  border-top: 1px solid rgba(142, 101, 111, 0.1);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  animation: photosSelectionBarIn 0.2s ease;
}

html[data-runwithme-theme="dark"]
  .photos-app-selection-bar {
  background: rgba(33, 28, 32, 0.96);
  border-top-color: rgba(255, 255, 255, 0.08);
}

@keyframes photosSelectionBarIn {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}

.photos-app-selection-btn {
  flex: 1;
  height: 48px;
  border: 0;
  border-radius: 14px;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.photos-app-selection-btn:hover:not(:disabled) {
  background: rgba(142, 101, 111, 0.2);
}

.photos-app-selection-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.photos-app-selection-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.photos-app-selection-delete {
  background: #e05d5d;
  color: #fff2e9;
}

.photos-app-selection-delete:hover:not(:disabled) {
  background: #c94d4d;
}

/* =========================================================================
   分类管理弹窗
   ========================================================================= */

.photo-cat-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9600;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: musicDrawerFade 0.2s ease;
}

