/* ---------- 拍一拍消息 ---------- */

.chat-pat-row {
  width: 100%;
  display: flex;
  justify-content: center;
  margin: 6px 0;
}

.chat-pat-message {
  padding: 6px 14px;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.1);
  color: var(--rw-text-muted);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.02em;
  opacity: 0.9;
  max-width: 80%;
  text-align: center;
  word-break: break-word;
}

html[data-runwithme-theme="dark"] .chat-pat-message {
  background: rgba(255, 255, 255, 0.06);
  color: #d9bcc4;
}

.chat-dark .chat-pat-message {
  background: rgba(255, 255, 255, 0.08);
  color: #d9bcc4;
}

/* ---------- 表情包（sticker）---------- */

.chat-sticker-message {
  display: inline-flex;
  align-items: flex-start;
  justify-content: flex-start;
  max-width: 130px;
  max-height: 130px;
  width: fit-content;
  height: auto;
}

.chat-sticker-message img {
  display: block;
  width: auto;
  height: auto;
  max-width: 130px;
  max-height: 130px;
  object-fit: contain;
  border-radius: 12px;
  user-select: none;
  -webkit-user-drag: none;
}

/* ---------- 图片 ---------- */

.chat-image-message {
  display: inline-block;
  width: fit-content;
  max-width: 220px;
  max-height: 300px;
  overflow: hidden;
  border-radius: 16px;
  box-shadow: 0 4px 14px rgba(80, 50, 60, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.25);
}

.chat-image-message img {
  display: block;
  width: auto;
  height: auto;
  max-width: 220px;
  max-height: 300px;
  object-fit: cover;
  user-select: none;
  -webkit-user-drag: none;
}

html[data-runwithme-theme="dark"] .chat-image-message,
.chat-dark .chat-image-message {
  border-color: rgba(255, 255, 255, 0.06);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
}

