  background: rgba(255, 255, 255, 0.03);
  color: rgba(255, 244, 239, 0.5);
}

.chat-settings-stickers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.chat-settings-sticker {
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(142, 101, 111, 0.06);
