html[data-runwithme-theme="dark"] .icity-app {
  background: #17131a;
  color: #fff2e9;
}


/* =========================================================================
   2. Header
   ========================================================================= */

.icity-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 64px;
  padding: 0 14px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .icity-header {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.icity-back {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
}

.icity-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.icity-title {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.icity-title-main {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 600;
  line-height: 1;
}

.icity-title-sub {
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
  margin-top: 3px;
}

/* 右上角「我的头像」 */
.icity-my-avatar {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: #fcbec3;
  color: var(--rw-text-muted);
  font-family: var(--rw-font-serif);
  font-size: 17px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.5),
    0 2px 6px rgba(0, 0, 0, 0.06);
  transition: transform 0.15s ease;
}

.icity-my-avatar.has-image {
  background: none;
  padding: 0;
}

.icity-my-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.icity-my-avatar:hover {
  transform: scale(1.05);
}


/* =========================================================================
   3. Feed
   ========================================================================= */

.icity-feed {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding:
    10px 14px
    calc(140px + env(safe-area-inset-bottom));
}

.icity-feed-empty {
  padding: 80px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  opacity: 0.7;
}

.icity-feed-empty-icon {
  font-size: 40px;
  opacity: 0.4;
}

.icity-feed-empty-title {
  font-size: 15px;
  font-weight: 700;
}

.icity-feed-empty-desc {
  font-size: 12px;
  opacity: 0.65;
  max-width: 240px;
  line-height: 1.6;
}


/* =========================================================================
   4. Avatar（通用圆形头像）
   ========================================================================= */

.icity-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--rw-font-serif);
  font-size: 17px;
  font-weight: 700;
  color: #fff2e9;
  flex-shrink: 0;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4),
    0 2px 6px rgba(0, 0, 0, 0.06);
  border: 0;
  padding: 0;
}

button.icity-avatar {
  cursor: pointer;
  transition: transform 0.15s ease;
}

button.icity-avatar:hover {
  transform: scale(1.05);
}

.icity-avatar-you {
  background: linear-gradient(135deg, #ffd4d8, #fcbec3);
  color: var(--rw-text-muted);
}

.icity-avatar-levi {
  background: linear-gradient(135deg, #a37b84, #8e656f);
}

.icity-avatar-erwin {
  background: linear-gradient(135deg, #ad8f95, #9b7f86);
}

.icity-avatar-small {
  width: 30px;
  height: 30px;
  font-size: 13px;
}

.icity-avatar-tiny {
  width: 26px;
  height: 26px;
  font-size: 11px;
}

/* 有自定义图片 */
.icity-avatar.icity-avatar-has-image,
.icity-avatar-small.icity-avatar-has-image,
.icity-avatar-tiny.icity-avatar-has-image {
  padding: 0;
  overflow: hidden;
  background: none;
}

.icity-avatar.icity-avatar-has-image img,
.icity-avatar-small.icity-avatar-has-image img,
.icity-avatar-tiny.icity-avatar-has-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}


/* =========================================================================
   5. Post Card（Feed 里的帖子）
   ========================================================================= */

.icity-post {
  padding: 16px;
  margin-bottom: 12px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow: 0 6px 20px rgba(90, 60, 65, 0.05);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

html[data-runwithme-theme="dark"] .icity-post {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
}

.icity-post-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.icity-post-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.icity-post-meta strong {
  font-size: 14px;
  font-weight: 700;
}

.icity-post-meta span {
  font-size: 10px;
  opacity: 0.55;
  letter-spacing: 0.02em;
}

.icity-post-text {
  font-size: 14px;
  line-height: 1.65;
  margin-bottom: 12px;
  cursor: pointer;
  word-break: break-word;
  white-space: pre-wrap;
}

.icity-post-actions {
  display: flex;
  align-items: center;
  gap: 18px;
}

.icity-action {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 10px;
  opacity: 0.7;
  transition:
    opacity 0.15s ease,
    background 0.15s ease,
    transform 0.15s ease;
}

.icity-action:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.08);
}

.icity-action:active {
  transform: scale(0.94);
}

.icity-action.like.active {
  color: #d34d5f;
  opacity: 1;
}

html[data-runwithme-theme="dark"] .icity-action.like.active {
  color: #fcbec3;
}

.icity-post-likers {
  margin-top: 10px;
  font-size: 11px;
  opacity: 0.6;
  letter-spacing: 0.02em;
}

/* 头像在帖子里的点击（复用了 .icity-avatar） */


/* =========================================================================
   6. Post Images（Feed / Detail / Modal 里的帖子配图）
   ========================================================================= */

.icity-post-images {
  display: grid;
  gap: 4px;
  margin-top: 10px;
  margin-bottom: 10px;
  border-radius: 14px;
  overflow: hidden;
  background: rgba(142, 101, 111, 0.04);
}

.icity-post-images.count-1 {
  grid-template-columns: 1fr;
}

.icity-post-images.count-2 {
  grid-template-columns: 1fr 1fr;
}

.icity-post-image {
  width: 100%;
  display: block;
  object-fit: cover;
  cursor: zoom-in;
  user-select: none;
  -webkit-user-drag: none;
  background: rgba(142, 101, 111, 0.08);
  transition: transform 0.25s ease;
}

.icity-post-images.count-1 .icity-post-image {
  aspect-ratio: 16 / 10;
  max-height: 320px;
}

.icity-post-images.count-2 .icity-post-image {
  aspect-ratio: 1 / 1;
  max-height: 260px;
}

.icity-post-image:hover {
  transform: scale(1.015);
}

.icity-detail-post .icity-post-images {
  margin-top: 14px;
  border-radius: 16px;
}


/* =========================================================================
   7. Modal（New Post）
   ========================================================================= */

.icity-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: icityFadeIn 0.2s ease;
}

@keyframes icityFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.icity-modal {
  width: min(480px, 100%);
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg-elevated);
  padding: 20px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.28);
  animation: icitySlideIn 0.22s ease;
}

html[data-runwithme-theme="dark"] .icity-modal {
  background: #211c20;
  color: #fff2e9;
}

@keyframes icitySlideIn {
  from { transform: translateY(-8px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.icity-post-modal {
  max-height: 90vh;
  overflow-y: auto;
}

.icity-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.icity-modal-header h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.icity-modal-close {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 18px;
  cursor: pointer;
}

.icity-modal-avatar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.icity-modal-name {
  font-size: 14px;
  font-weight: 700;
}

.icity-modal-textarea {
  width: 100%;
  min-height: 120px;
  padding: 12px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 14px;
  line-height: 1.6;
  outline: none;
  resize: none;
  box-sizing: border-box;
  transition:
    border-color 0.15s ease,
    background 0.15s ease;
}

html[data-runwithme-theme="dark"] .icity-modal-textarea {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.icity-modal-textarea:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

.icity-modal-textarea::placeholder {
  color: rgba(142, 101, 111, 0.45);
}

.icity-modal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
}

.icity-modal-count {
  font-size: 11px;
  opacity: 0.5;
  font-variant-numeric: tabular-nums;
}

.icity-modal-post {
  padding: 10px 22px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.icity-modal-post:hover:not(:disabled) {
  transform: translateY(-1px);
}

.icity-modal-post:disabled {
  opacity: 0.4;
  cursor: default;
}

/* ---------- 图片预览 ---------- */

.icity-post-preview-grid {
  display: grid;
  gap: 6px;
  margin-top: 12px;
  border-radius: 14px;
  overflow: hidden;
}

.icity-post-preview-grid.count-1 {
  grid-template-columns: 1fr;
}

.icity-post-preview-grid.count-2 {
  grid-template-columns: 1fr 1fr;
}

.icity-post-preview-item {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(142, 101, 111, 0.06);
  aspect-ratio: 1 / 1;
}

.icity-post-preview-grid.count-1 .icity-post-preview-item {
  aspect-ratio: 16 / 10;
}

.icity-post-preview-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.icity-post-preview-remove {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  font-size: 15px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.icity-post-preview-remove:hover {
  background: rgba(0, 0, 0, 0.75);
  transform: scale(1.08);
}

/* ---------- Modal Footer 布局 ---------- */

.icity-post-modal-footer {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 12px;
}

.icity-post-modal-tools {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}

.icity-post-add-image {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border: 1px solid rgba(142, 101, 111, 0.15);
  border-radius: var(--rw-radius-pill);
  background: rgba(252, 190, 195, 0.28);
  color: var(--rw-text-muted);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.15s ease,
    transform 0.15s ease,
    opacity 0.15s ease;
}

html[data-runwithme-theme="dark"] .icity-post-add-image {
  background: rgba(252, 190, 195, 0.15);
  border-color: rgba(252, 190, 195, 0.2);
  color: #f3dfe4;
}

.icity-post-add-image:hover:not(:disabled) {
  background: rgba(252, 190, 195, 0.42);
  transform: translateY(-1px);
}

.icity-post-add-image:active:not(:disabled) {
  transform: scale(0.96);
}

.icity-post-add-image:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.icity-post-add-image > svg {
  flex-shrink: 0;
  display: block;
}

.icity-post-add-image > span {
  line-height: 1;
}


/* =========================================================================
   8. Post Detail
   ========================================================================= */

.icity-detail {
  position: absolute;
  inset: 0;
  z-index: 8000;
  display: flex;
  flex-direction: column;
  background: var(--rw-bg);
  color: var(--rw-text);
  animation: icitySlideRight 0.22s ease;
}

html[data-runwithme-theme="dark"] .icity-detail {
  background: #17131a;
  color: #fff2e9;
}

@keyframes icitySlideRight {
  from { transform: translateX(20px); opacity: 0; }
  to   { transform: translateX(0);    opacity: 1; }
}

.icity-detail-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 60px;
  padding: 0 14px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .icity-detail-header {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.icity-detail-back {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
}

.icity-detail-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.icity-detail-title {
  flex: 1;
  font-size: 16px;
  font-weight: 700;
  text-align: center;
}

.icity-detail-delete,
.icity-detail-placeholder {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icity-detail-delete {
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 15px;
  cursor: pointer;
  opacity: 0.7;
}

.icity-detail-delete:hover {
  background: rgba(224, 93, 93, 0.15);
  opacity: 1;
}

.icity-detail-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px 18px 20px;
}

.icity-detail-post {
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.08);
  margin-bottom: 16px;
}

html[data-runwithme-theme="dark"] .icity-detail-post {
  border-bottom-color: rgba(255, 255, 255, 0.06);
}

.icity-detail-post-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.icity-detail-post-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.icity-detail-post-meta strong {
  font-size: 15px;
  font-weight: 700;
}

.icity-detail-post-meta span {
  font-size: 11px;
  opacity: 0.55;
}

.icity-detail-post-text {
  font-size: 16px;
  line-height: 1.7;
  margin-bottom: 14px;
  word-break: break-word;
  white-space: pre-wrap;
}

.icity-detail-post-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.icity-detail-likers {
  margin-top: 10px;
  font-size: 11px;
  opacity: 0.6;
}


/* =========================================================================
   9. Comments（评论 + 回复气泡）
   ========================================================================= */

.icity-detail-comments {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.icity-detail-empty {
  padding: 40px 20px;
  text-align: center;
  font-size: 12px;
  opacity: 0.5;
}

/* ---------- 顶层评论 ---------- */

.icity-comment {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  position: relative;
}

.icity-comment-body {
  flex: 1;
  min-width: 0;
}

.icity-comment-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 3px;
}

.icity-comment-head strong {
  font-size: 13px;
  font-weight: 700;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .icity-comment-head strong {
  color: #fff2e9;
}

.icity-comment-head span {
  font-size: 10px;
  opacity: 0.5;
}

.icity-comment-text {
  font-size: 14px;
  line-height: 1.6;
  color: var(--rw-text);
  word-break: break-word;
  white-space: pre-wrap;
}

html[data-runwithme-theme="dark"] .icity-comment-text {
  color: rgba(255, 244, 239, 0.88);
}

/* ---------- 回复按钮 ---------- */

.icity-comment-reply-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;

  margin-top: 5px;
  margin-left: -4px;
  padding: 3px 8px;

  border: 0;
  border-radius: var(--rw-radius-pill);

  background: transparent;
  color: var(--rw-text-muted);

  font-size: 11px;
  font-weight: 600;

  cursor: pointer;
  opacity: 0.55;

  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.icity-comment-reply-btn::before {
  content: "↩";
  font-size: 12px;
  line-height: 1;
  transform: translateY(-1px);
}

.icity-comment-reply-btn:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.1);
}

html[data-runwithme-theme="dark"] .icity-comment-reply-btn {
  color: #d9bcc4;
}

html[data-runwithme-theme="dark"] .icity-comment-reply-btn:hover {
  background: rgba(255, 255, 255, 0.06);
}

/* ---------- 删除按钮 ---------- */

.icity-comment-delete {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 15px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  cursor: pointer;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.icity-comment:hover .icity-comment-delete {
  opacity: 0.5;
}

.icity-comment-delete:hover {
  opacity: 1 !important;
  background: rgba(224, 93, 93, 0.18);
}

@media (hover: none) and (pointer: coarse) {
  .icity-comment-delete {
    opacity: 0.4;
  }
}

/* ---------- 回复列表（带竖线评论树） ---------- */

.icity-comment-thread {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 14px;
}

.icity-comment-thread > .icity-comment {
  padding: 0;
}

.icity-comment-thread > .icity-comment .icity-comment-body {
  padding-bottom: 8px;
}

.icity-comment-replies {
  position: relative;

  display: flex;
  flex-direction: column;
  gap: 8px;

  margin-left: 44px;
  padding-left: 14px;
  padding-top: 6px;
  padding-bottom: 4px;
}

/* 左侧竖直连接线 */
.icity-comment-replies::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 0;
  bottom: 12px;
  width: 2px;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.18);
}

html[data-runwithme-theme="dark"] .icity-comment-replies::before {
  background: rgba(255, 255, 255, 0.08);
}

/* ---------- 单条回复 ---------- */

.icity-reply-row {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

/* 从竖线拐到气泡的分支小钩 */
.icity-reply-row::before {
  content: "";
  position: absolute;
  left: -10px;
  top: 16px;
  width: 10px;
  height: 12px;
  border-left: 2px solid rgba(142, 101, 111, 0.18);
  border-bottom: 2px solid rgba(142, 101, 111, 0.18);
  border-bottom-left-radius: 8px;
  pointer-events: none;
}

html[data-runwithme-theme="dark"] .icity-reply-row::before {
  border-left-color: rgba(255, 255, 255, 0.08);
  border-bottom-color: rgba(255, 255, 255, 0.08);
}

/* 小头像在回复里需要对齐气泡顶部 */
.icity-reply-row .icity-avatar-tiny {
  margin-top: 4px;
}

/* ---------- 回复气泡 ---------- */

.icity-reply-bubble {
  position: relative;
  flex: 1;
  min-width: 0;
  padding: 7px 26px 7px 12px;
  border-radius: 14px;
  border-top-left-radius: 4px;
  background: rgba(142, 101, 111, 0.08);
  color: inherit;
  word-break: break-word;
}

html[data-runwithme-theme="dark"] .icity-reply-bubble {
  background: rgba(255, 255, 255, 0.05);
}

/* 指向父评论的小三角 */
.icity-reply-bubble::before {
  content: "";
  position: absolute;
  left: -4px;
  top: 10px;
  width: 9px;
  height: 9px;
  background: inherit;
  transform: rotate(45deg);
  border-radius: 1px;
}

.icity-reply-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 2px;
}

.icity-reply-head strong {
  font-size: 12px;
  font-weight: 700;
  color: #5e4650;
}

html[data-runwithme-theme="dark"] .icity-reply-head strong {
  color: #fff2e9;
}

.icity-reply-head span {
  font-size: 9px;
  opacity: 0.5;
}

.icity-reply-text {
  font-size: 13px;
  line-height: 1.55;
  color: var(--rw-text);
  white-space: pre-wrap;
  word-break: break-word;
}

html[data-runwithme-theme="dark"] .icity-reply-text {
  color: rgba(255, 244, 239, 0.88);
}

/* 回复删除按钮 */
.icity-reply-delete {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 14px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  cursor: pointer;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.icity-reply-row:hover .icity-reply-delete {
  opacity: 0.5;
}

.icity-reply-delete:hover {
  opacity: 1 !important;
  background: rgba(224, 93, 93, 0.2);
}

@media (hover: none) and (pointer: coarse) {
  .icity-reply-delete {
    opacity: 0.4;
  }
}

/* ---------- 评论输入框 ---------- */

.icity-detail-composer {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  padding: 10px 14px
    calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(142, 101, 111, 0.08);
  background: rgba(255, 248, 243, 0.96);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

html[data-runwithme-theme="dark"] .icity-detail-composer {
  background: rgba(33, 28, 32, 0.96);
  border-top-color: rgba(255, 255, 255, 0.06);
}

.icity-detail-reply-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  border-radius: 10px;
  background: rgba(142, 101, 111, 0.08);
  font-size: 11px;
  opacity: 0.9;
}

html[data-runwithme-theme="dark"] .icity-detail-reply-bar {
  background: rgba(255, 255, 255, 0.06);
}

.icity-detail-reply-bar button {
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 14px;
  cursor: pointer;
  line-height: 1;
}

.icity-detail-composer-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}

.icity-detail-composer input {
  flex: 1;
  min-width: 0;
  padding: 11px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"] .icity-detail-composer input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.08);
}

.icity-detail-composer input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

.icity-detail-composer input::placeholder {
  color: rgba(142, 101, 111, 0.45);
}

.icity-detail-send {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: #8e656f;
  color: #fff2e9;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.icity-detail-send:hover:not(:disabled) {
  transform: scale(1.06);
}

.icity-detail-send:active:not(:disabled) {
  transform: scale(0.94);
}

.icity-detail-send:disabled {
  opacity: 0.4;
  cursor: default;
}


/* =========================================================================
   10. Profile 主页
   ========================================================================= */

.icity-profile {
  position: absolute;
  inset: 0;
  z-index: 8100;
  display: flex;
  flex-direction: column;
  background: var(--rw-bg);
  color: var(--rw-text);
  animation: icitySlideRight 0.22s ease;
}

html[data-runwithme-theme="dark"] .icity-profile {
  background: #17131a;
  color: #fff2e9;
}

/* ---------- 内嵌模式（Mine tab） ---------- */

.icity-profile.is-embedded {
  position: relative;
  inset: auto;
  z-index: 1;
  flex: 1 1 auto;
  min-height: 0;
  animation: none;
  background: transparent;
}

.icity-profile.is-embedded .icity-profile-scroll {
  padding-bottom: calc(120px + env(safe-area-inset-bottom));
}

/* ---------- Profile header ---------- */

.icity-profile-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  height: 60px;
  padding: 0 14px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .icity-profile-header {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.icity-profile-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

/* ---------- Cover（背景图） ---------- */

.icity-profile-cover {
  position: relative;
  height: 200px;
  display: block;
  padding: 0;
  background:
    radial-gradient(
      circle at 30% 30%,
      rgba(252, 190, 195, 0.8),
      transparent 60%
    ),
    radial-gradient(
      circle at 80% 70%,
      rgba(207, 222, 227, 0.9),
      transparent 60%
    ),
    linear-gradient(145deg, #fcbec3, #cfdee3);
  background-size: cover;
  background-position: center;
}

.icity-profile-cover-edit,
.icity-profile-cover-remove {
  position: absolute;
  z-index: 3;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.4);
  color: #fff;
  font-size: 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: background 0.15s ease;
}

.icity-profile-cover-edit {
  right: 12px;
  bottom: 12px;
}

.icity-profile-cover-remove {
  right: 12px;
  top: 12px;
  font-size: 18px;
  line-height: 1;
}

.icity-profile-cover-edit:hover,
.icity-profile-cover-remove:hover {
  background: rgba(0, 0, 0, 0.6);
}

/* ---------- Avatar（浮在背景底部边缘） ---------- */

.icity-profile-avatar-wrap {
  position: relative;
  margin-top: -60px;
  padding: 0 20px;
  display: flex;
  justify-content: center;
  pointer-events: none;
  z-index: 2;
}

.icity-profile-avatar {
  position: relative;
  width: 120px;
  height: 120px;
  border-radius: 50%;
  border: 4px solid #fff2e9;
  background: #fcbec3;
  color: var(--rw-text-muted);
  font-family: var(--rw-font-serif);
  font-size: 46px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  box-shadow:
    0 12px 30px rgba(80, 50, 60, 0.18),
    0 2px 6px rgba(80, 50, 60, 0.08);
  transition: transform 0.15s ease;
  pointer-events: auto;
  flex-shrink: 0;
}

html[data-runwithme-theme="dark"] .icity-profile-avatar {
  border-color: #17131a;
}

.icity-profile-avatar.icity-profile-avatar-custom {
  padding: 0;
}

.icity-profile-avatar:hover {
  transform: scale(1.03);
}

.icity-profile-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.icity-profile-avatar.icity-avatar-you {
  color: var(--rw-text-muted);
}

.icity-profile-avatar.icity-avatar-levi,
.icity-profile-avatar.icity-avatar-erwin {
  color: #fff2e9;
}

.icity-profile-avatar-edit {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgba(255, 255, 255, 0.9);
  pointer-events: none;
}

/* ---------- Meta（名字 / ID） ---------- */

.icity-profile-meta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 14px 20px 8px;
}

.icity-profile-meta-name {
  border: 0;
  background: transparent;
  color: inherit;
  font-family: var(--rw-font-serif);
  font-size: 26px;
  font-weight: 600;
  line-height: 1.15;
  cursor: pointer;
  padding: 2px 8px;
  border-radius: 8px;
  transition: background 0.15s ease;
}

.icity-profile-meta-name:hover {
  background: rgba(142, 101, 111, 0.08);
}

.icity-profile-meta-handle {
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 12px;
  opacity: 0.55;
  cursor: pointer;
  padding: 2px 8px;
  border-radius: 8px;
  transition: background 0.15s ease;
}

.icity-profile-meta-handle:hover {
  background: rgba(142, 101, 111, 0.08);
  opacity: 0.85;
}

.icity-profile-meta-input {
  width: min(260px, 80%);
  padding: 6px 12px;
  border: 1px solid rgba(142, 101, 111, 0.3);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.9);
  color: inherit;
  font-family: var(--rw-font-serif);
  font-size: 24px;
  font-weight: 600;
  text-align: center;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"] .icity-profile-meta-input {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
}

.icity-profile-meta-input-small {
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  padding: 5px 12px;
  width: min(200px, 70%);
}

/* 移除头像按钮 */
.icity-profile-avatar-remove-inline {
  margin-top: 4px;
  padding: 4px 12px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.08);
  color: inherit;
  font-size: 10px;
  font-weight: 600;
  opacity: 0.7;
  cursor: pointer;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.icity-profile-avatar-remove-inline:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.16);
}

html[data-runwithme-theme="dark"] .icity-profile-avatar-remove-inline {
  background: rgba(255, 255, 255, 0.06);
}

html[data-runwithme-theme="dark"]
  .icity-profile-avatar-remove-inline:hover {
  background: rgba(255, 255, 255, 0.12);
}

/* ---------- Stats ---------- */

.icity-profile-stats {
  display: flex;
  justify-content: center;
  gap: 36px;
  padding: 12px 20px 20px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .icity-profile-stats {
  border-bottom-color: rgba(255, 255, 255, 0.05);
}

.icity-profile-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.icity-profile-stat strong {
  font-size: 16px;
  font-weight: 700;
}

.icity-profile-stat span {
  font-size: 10px;
  opacity: 0.55;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---------- Profile 帖子列表 ---------- */

.icity-profile-list {
  padding: 14px 14px 24px;
}

.icity-profile-empty {
  padding: 40px 20px;
  text-align: center;
  font-size: 13px;
  opacity: 0.5;
}

.icity-post-time-inline {
  margin-left: auto;
  font-size: 10px;
  opacity: 0.5;
}


/* =========================================================================
   11. Dock（iOS 风格底栏 + 加号菜单）
   ========================================================================= */

.icity-dock {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
  padding:
    0 16px
    calc(14px + env(safe-area-inset-bottom));
  pointer-events: none;
}

.icity-dock-inner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 66px;
  padding: 0 10px;
  border-radius: 28px;

  background: rgba(255, 248, 243, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.8);

  box-shadow:
    0 10px 30px rgba(80, 50, 60, 0.1),
    0 2px 8px rgba(80, 50, 60, 0.06);

  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

html[data-runwithme-theme="dark"] .icity-dock-inner {
  background: rgba(33, 28, 32, 0.85);
  border-color: rgba(255, 255, 255, 0.06);
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.35),
    0 2px 8px rgba(0, 0, 0, 0.2);
}

/* ---------- 两侧 Tab ---------- */

.icity-dock-tab {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;

  padding: 8px 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;

  border-radius: 16px;
  opacity: 0.45;
  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease;
}

.icity-dock-tab > svg {
  display: block;
  flex-shrink: 0;
}

.icity-dock-tab > span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
}

.icity-dock-tab.active {
  opacity: 1;
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"] .icity-dock-tab.active {
  color: #fcbec3;
}

.icity-dock-tab:hover:not(.active) {
  opacity: 0.75;
}

.icity-dock-tab:active {
  background: rgba(142, 101, 111, 0.08);
}

/* ---------- 中间加号按钮 ---------- */

.icity-dock-post-slot {
  position: relative;
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 4px;
}

.icity-dock-post {
  width: 52px;
  height: 52px;
  border: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #8e656f;
  color: #fff2e9;
  cursor: pointer;
  box-shadow:
    0 10px 22px rgba(142, 101, 111, 0.35),
    inset 0 0 0 1px rgba(255, 255, 255, 0.15);
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.icity-dock-post:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 28px rgba(142, 101, 111, 0.45),
    inset 0 0 0 1px rgba(255, 255, 255, 0.2);
}

.icity-dock-post:active {
  transform: scale(0.94);
}

/* 菜单打开时旋转 45° 变成 × */
.icity-dock-post.active {
  transform: rotate(45deg);
}

.icity-dock-post.active:active {
  transform: rotate(45deg) scale(0.94);
}

/* ---------- 加号展开菜单 ---------- */

.icity-dock-menu {
  position: absolute;
  bottom: calc(100% + 14px);
  left: 50%;
  transform: translateX(-50%);

  display: flex;
  flex-direction: column;
  gap: 8px;

  padding: 8px;

  border-radius: 20px;
  background: rgba(255, 248, 243, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.8);

  box-shadow:
    0 14px 40px rgba(80, 50, 60, 0.18),
    0 2px 8px rgba(80, 50, 60, 0.08);

  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);

  animation: icityDockMenuIn 0.2s ease;
  z-index: 20;
}

html[data-runwithme-theme="dark"] .icity-dock-menu {
  background: rgba(33, 28, 32, 0.96);
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow:
    0 14px 40px rgba(0, 0, 0, 0.4),
    0 2px 8px rgba(0, 0, 0, 0.25);
}

.icity-dock-menu::after {
  content: "";
  position: absolute;
  bottom: -5px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 10px;
  height: 10px;
  background: inherit;
  border-right: 1px solid rgba(255, 255, 255, 0.8);
  border-bottom: 1px solid rgba(255, 255, 255, 0.8);
}

html[data-runwithme-theme="dark"] .icity-dock-menu::after {
  border-right-color: rgba(255, 255, 255, 0.08);
  border-bottom-color: rgba(255, 255, 255, 0.08);
}

@keyframes icityDockMenuIn {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(6px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}

.icity-dock-menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 8px;
  border: 0;
  border-radius: 14px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.icity-dock-menu-item:hover {
  background: rgba(142, 101, 111, 0.1);
}

.icity-dock-menu-item:active {
  transform: scale(0.96);
}

html[data-runwithme-theme="dark"] .icity-dock-menu-item:hover {
  background: rgba(255, 255, 255, 0.06);
}

.icity-dock-menu-icon {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(252, 190, 195, 0.35);
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"] .icity-dock-menu-icon {
  background: rgba(252, 190, 195, 0.18);
  color: #f3dfe4;
}

.icity-dock-menu-label {
  line-height: 1;
}


/* =========================================================================
   12. Image Lightbox
   ========================================================================= */

.icity-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  background: rgba(0, 0, 0, 0.96);
  color: #fff;
  animation: icityLightboxIn 0.2s ease;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

@keyframes icityLightboxIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.icity-lightbox-top {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding:
    12px 16px
    calc(12px + env(safe-area-inset-top));
  z-index: 3;
}

.icity-lightbox-close {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-size: 17px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: background 0.15s ease, transform 0.15s ease;
}

.icity-lightbox-close:hover {
  background: rgba(255, 255, 255, 0.24);
}

.icity-lightbox-close:active {
  transform: scale(0.94);
}

.icity-lightbox-counter {
  font-size: 12px;
  opacity: 0.85;
  letter-spacing: 0.05em;
  font-variant-numeric: tabular-nums;
  padding: 5px 12px;
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.icity-lightbox-placeholder {
  width: 40px;
  height: 40px;
}

.icity-lightbox-body {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  overflow: hidden;
  position: relative;
}

.icity-lightbox-image {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
  user-select: none;
  -webkit-user-drag: none;
  transition: transform 0.2s ease-out;
  will-change: transform;
  border-radius: 4px;
}

.icity-lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-size: 28px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
  z-index: 3;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.icity-lightbox-nav:hover {
  background: rgba(255, 255, 255, 0.22);
}

.icity-lightbox-nav.prev {
  left: 16px;
}

.icity-lightbox-nav.next {
  right: 16px;
}

@media (hover: none) and (pointer: coarse) {
  .icity-lightbox-nav {
    display: none;
  }
}

.icity-lightbox-dots {
  flex-shrink: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 6px;
  padding:
    12px 20px
    calc(16px + env(safe-area-inset-bottom));
  z-index: 3;
}

.icity-lightbox-dot {
  width: 6px;
  height: 6px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  cursor: pointer;
  padding: 0;
  transition:
    background 0.15s ease,
    width 0.15s ease;
}

.icity-lightbox-dot.active {
  background: #fff;
  width: 22px;
  border-radius: var(--rw-radius-pill);
}


/* =========================================================================
   13. 已废弃（保留以确保兼容，实际不显示）
   ========================================================================= */

.icity-fab {
  display: none !important;
}

.icity-tabbar {
  display: none !important;
}

.icity-profile-avatar-remove {
  display: none !important;
}

.icity-compose {
  /* 旧的 header 编辑按钮，已经被 iCity-my-avatar 替代 */
  display: none;
}

/* =========================================================================
   Calendar App v2
   ========================================================================= */

.calendar-app {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--rw-bg);
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"] .calendar-app {
  background: #17131a;
  color: #fff2e9;
}

/* ---------- Header ---------- */

.calendar-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px 8px;
}

.calendar-back {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
}

.calendar-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.calendar-header-center {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.calendar-header-month {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  opacity: 0.65;
  text-transform: uppercase;
}

.calendar-header-year {
  font-family: var(--rw-font-serif);
  font-size: 26px;
  font-weight: 600;
  line-height: 1;
}

.calendar-today-btn {
  flex-shrink: 0;
  padding: 7px 14px;
  border: 1px solid rgba(142, 101, 111, 0.16);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.6);
  color: var(--rw-text-muted);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, opacity 0.15s ease;
}

html[data-runwithme-theme="dark"] .calendar-today-btn {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  color: #f3dfe4;
}

.calendar-today-btn:hover:not(:disabled) {
  background: rgba(252, 190, 195, 0.32);
}

.calendar-today-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

/* ---------- 可滚动内容区 ---------- */

.calendar-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding-bottom: calc(96px + env(safe-area-inset-bottom));
}

/* ---------- 月份导航 ---------- */

.calendar-nav {
  display: flex;
  justify-content: space-between;
  padding: 0 22px;
  margin-bottom: 4px;
}

.calendar-nav-btn {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 24px;
  cursor: pointer;
  opacity: 0.7;
  display: flex;
  align-items: center;
  justify-content: center;
}

.calendar-nav-btn:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.08);
}

/* ---------- Weekday ---------- */

.calendar-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  padding: 0 8px;
  margin-bottom: 2px;
}

.calendar-weekday {
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(142, 101, 111, 0.5);
  padding: 4px 0;
}

html[data-runwithme-theme="dark"] .calendar-weekday {
  color: rgba(255, 244, 239, 0.4);
}

/* ---------- Grid ---------- */

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  padding: 4px 8px 12px;
}

.calendar-day {
  position: relative;
  aspect-ratio: 1 / 1;
  min-height: 40px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  font-size: 13px;
  font-weight: 500;
  transition: background 0.15s ease, color 0.15s ease;
}

.calendar-day:hover:not(.calendar-day-selected) {
  background: rgba(142, 101, 111, 0.08);
}

.calendar-day-other {
  opacity: 0.28;
  font-weight: 400;
}

.calendar-day-num {
  line-height: 1;
}

.calendar-day-today {
  color: var(--rw-text-muted);
  font-weight: 800;
}

html[data-runwithme-theme="dark"] .calendar-day-today {
  color: #fcbec3;
}

.calendar-day-period {
  background: rgba(252, 190, 195, 0.35);
  color: var(--rw-text-muted);
  font-weight: 700;
}

html[data-runwithme-theme="dark"] .calendar-day-period {
  background: rgba(252, 190, 195, 0.18);
  color: #f3dfe4;
}

.calendar-day-selected,
.calendar-day-selected.calendar-day-period {
  background: #8e656f;
  color: #fff2e9;
  font-weight: 700;
  box-shadow: 0 6px 16px rgba(142, 101, 111, 0.28);
}

.calendar-day-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #d34d5f;
  display: block;
}

html[data-runwithme-theme="dark"] .calendar-day-dot {
  background: #fcbec3;
}

.calendar-day-selected .calendar-day-dot {
  background: var(--rw-bg);
}

/* ---------- Day detail ---------- */

.calendar-detail {
  padding: 16px 20px 24px;
  border-top: 1px solid rgba(142, 101, 111, 0.08);
}

html[data-runwithme-theme="dark"] .calendar-detail {
  border-top-color: rgba(255, 255, 255, 0.05);
}

.calendar-detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.calendar-detail-date {
  font-family: var(--rw-font-serif);
  font-size: 20px;
  font-weight: 600;
}

.calendar-detail-empty {
  padding: 20px 12px;
  text-align: center;
  font-size: 12px;
  opacity: 0.5;
}

/* 经期卡片 */
.calendar-period-card {
  padding: 14px 16px;
  border-radius: 16px;
  background: rgba(252, 190, 195, 0.22);
  border: 1px solid rgba(252, 190, 195, 0.4);
  margin-bottom: 12px;
}

html[data-runwithme-theme="dark"] .calendar-period-card {
  background: rgba(252, 190, 195, 0.08);
  border-color: rgba(252, 190, 195, 0.15);
}

.calendar-period-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.calendar-period-icon {
  font-size: 16px;
  line-height: 1;
}

.calendar-period-title {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  font-weight: 700;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.calendar-period-day {
  font-size: 11px;
  font-weight: 600;
  opacity: 0.65;
}

.calendar-period-fields {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.calendar-period-field {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 13px;
  line-height: 1.5;
}

.calendar-period-label {
  flex-shrink: 0;
  width: 44px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  opacity: 0.55;
}

.calendar-period-value {
  flex: 1;
  min-width: 0;
  word-break: break-word;
}

.calendar-add-period-btn {
  width: 100%;
  padding: 12px;
  border: 1px dashed rgba(142, 101, 111, 0.3);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.5);
  color: var(--rw-text-muted);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

html[data-runwithme-theme="dark"] .calendar-add-period-btn {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.12);
  color: #f3dfe4;
}

.calendar-add-period-btn:hover {
  background: rgba(252, 190, 195, 0.25);
  border-color: rgba(252, 190, 195, 0.6);
}

.calendar-anniv-hint {
  margin-top: 12px;
  padding: 8px 12px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.06);
  font-size: 11px;
  text-align: center;
  opacity: 0.7;
}

/* ---------- Anniversary Page ---------- */

.calendar-anniv-empty {
  padding: 80px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.calendar-anniv-empty-icon {
  font-size: 40px;
  opacity: 0.35;
  margin-bottom: 6px;
}

.calendar-anniv-empty-title {
  font-size: 15px;
  font-weight: 700;
}

.calendar-anniv-empty-desc {
  font-size: 12px;
  opacity: 0.6;
  max-width: 220px;
  line-height: 1.6;
}

.calendar-anniv-list {
  list-style: none;
  margin: 0;
  padding: 4px 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.calendar-anniv-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 14px rgba(90, 60, 65, 0.05);
}

html[data-runwithme-theme="dark"] .calendar-anniv-item {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.calendar-anniv-heart {
  font-size: 18px;
  color: #d34d5f;
  line-height: 1;
  flex-shrink: 0;
}

html[data-runwithme-theme="dark"] .calendar-anniv-heart {
  color: #fcbec3;
}

.calendar-anniv-info {
  flex: 1;
  min-width: 0;
}

.calendar-anniv-title {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  word-break: break-word;
}

.calendar-anniv-meta {
  margin-top: 3px;
  font-size: 11px;
  opacity: 0.55;
}

.calendar-anniv-days {
  margin-top: 4px;
  font-size: 11px;
  font-weight: 700;
  color: var(--rw-text-muted);
  opacity: 0.8;
}

html[data-runwithme-theme="dark"] .calendar-anniv-days {
  color: #fcbec3;
  opacity: 0.85;
}

.calendar-anniv-days.is-today {
  color: #d34d5f;
  opacity: 1;
}

.calendar-anniv-days.is-past {
  opacity: 0.45;
}

.calendar-anniv-action {
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 13px;
  cursor: pointer;
  opacity: 0.55;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.15s ease, background 0.15s ease;
}

.calendar-anniv-action:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.1);
}

.calendar-anniv-action.danger:hover {
  background: rgba(224, 93, 93, 0.18);
}

/* ---------- Dock ---------- */

.calendar-dock {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
  padding: 0 16px
    calc(14px + env(safe-area-inset-bottom));
  pointer-events: none;
}

.calendar-dock-inner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 62px;
  padding: 0 8px;
  border-radius: 26px;
  background: rgba(255, 248, 243, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.8);
  box-shadow:
    0 10px 30px rgba(80, 50, 60, 0.1),
    0 2px 8px rgba(80, 50, 60, 0.06);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

html[data-runwithme-theme="dark"] .calendar-dock-inner {
  background: rgba(33, 28, 32, 0.85);
  border-color: rgba(255, 255, 255, 0.06);
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.35),
    0 2px 8px rgba(0, 0, 0, 0.2);
}

.calendar-dock-tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 8px 0;
  border: 0;
  border-radius: 16px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  opacity: 0.45;
  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease;
}

.calendar-dock-tab > svg {
  display: block;
}

.calendar-dock-tab > span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
}

.calendar-dock-tab.active {
  opacity: 1;
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"]
  .calendar-dock-tab.active {
  color: #fcbec3;
}

.calendar-dock-tab:hover:not(.active) {
  opacity: 0.75;
}

.calendar-dock-tab:active {
  background: rgba(142, 101, 111, 0.08);
}

/* ---------- Modal ---------- */

.calendar-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9500;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: calendarFadeIn 0.18s ease;
}

@keyframes calendarFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.calendar-modal {
  width: min(420px, 100%);
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg-elevated);
  padding: 22px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.28);
  animation: calendarSlideIn 0.2s ease;
}

html[data-runwithme-theme="dark"] .calendar-modal {
  background: #211c20;
  color: #fff2e9;
}

@keyframes calendarSlideIn {
  from { transform: translateY(-8px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.calendar-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.calendar-modal-header h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.calendar-modal-close {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 18px;
  cursor: pointer;
}

.calendar-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.calendar-field > span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.6;
}

.calendar-field input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
  transition: border-color 0.15s ease;
}

html[data-runwithme-theme="dark"] .calendar-field input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.calendar-field input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

.calendar-field input::placeholder {
  color: rgba(142, 101, 111, 0.4);
}

/* 分段控件（每年/每月、量选择） */
.calendar-segment {
  display: flex;
  gap: 4px;
  padding: 4px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.08);
}

.calendar-segment button {
  flex: 1;
  padding: 8px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.calendar-segment button.active {
  background: #fcbec3;
  color: var(--rw-text-muted);
  font-weight: 700;
}

html[data-runwithme-theme="dark"]
  .calendar-segment button.active {
  background: rgba(252, 190, 195, 0.3);
  color: #f3dfe4;
}

.calendar-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}

.calendar-btn {
  padding: 10px 20px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.calendar-btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.calendar-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.calendar-btn.ghost {
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
}

html[data-runwithme-theme="dark"] .calendar-btn.ghost {
  background: rgba(255, 255, 255, 0.06);
}
/* =========================================================================
   Calendar v3 · 系统备注 + 行程 + 卡池
   ========================================================================= */

/* Header 图标按钮 */
.calendar-icon-btn {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.calendar-icon-btn:hover {
  background: rgba(142, 101, 111, 0.2);
}

/* nav 中间 Today 微调 */
.calendar-nav {
  align-items: center;
  gap: 8px;
}

.calendar-nav .calendar-today-btn {
  padding: 6px 16px;
}

/* ---------- 系统备注卡片 ---------- */

.calendar-note-card {
  padding: 12px 14px;
  border-radius: 16px;
  margin-bottom: 12px;
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.28),
    rgba(207, 222, 227, 0.28)
  );
  border: 1px solid rgba(255, 255, 255, 0.6);
}

html[data-runwithme-theme="dark"] .calendar-note-card {
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.12),
    rgba(207, 222, 227, 0.08)
  );
  border-color: rgba(255, 255, 255, 0.06);
}

.calendar-note-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.calendar-note-avatar {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--rw-font-serif);
  font-size: 13px;
  font-weight: 700;
  color: #fff2e9;
  background: linear-gradient(135deg, #a37b84, #8e656f);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4);
}

.calendar-note-body {
  flex: 1;
  min-width: 0;
}

.calendar-note-name {
  font-size: 11px;
  font-weight: 700;
  opacity: 0.65;
  letter-spacing: 0.05em;
  margin-bottom: 3px;
}

.calendar-note-text {
  font-size: 13px;
  line-height: 1.55;
  color: var(--rw-text);
  word-break: break-word;
  white-space: pre-wrap;
}

html[data-runwithme-theme="dark"] .calendar-note-text {
  color: rgba(255, 244, 239, 0.9);
}

/* ---------- 行程区块 ---------- */

.calendar-schedule-block {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.7);
}

html[data-runwithme-theme="dark"] .calendar-schedule-block {
  background: rgba(48, 42, 47, 0.5);
  border-color: rgba(255, 255, 255, 0.06);
}

.calendar-schedule-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.calendar-schedule-label {
  font-size: 10px;
  font-weight: 700;
