/* =========================================================================
   Questionnaire App
   ========================================================================= */

.q-app {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--rw-bg);
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"] .q-app {
  background: #17131a;
  color: #fff2e9;
}

/* Header */
.q-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 14px 8px;
}

.q-back {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
}

.q-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.q-header-center {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.q-header-title {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 600;
  line-height: 1;
}

.q-header-sub {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.5;
  margin-top: 3px;
}

.q-icon-btn,
.q-add-btn {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.q-icon-btn:hover {
  background: rgba(142, 101, 111, 0.2);
}

.q-add-btn {
  background: #8e656f;
  color: #fff2e9;
}

.q-add-btn:hover {
  background: #7a545e;
}

/* Filter */
.q-filter {
  flex-shrink: 0;
  display: flex;
  gap: 6px;
  padding: 4px 14px 10px;
  overflow-x: auto;
  scrollbar-width: none;
}

.q-filter::-webkit-scrollbar {
  display: none;
}

.q-filter-btn {
  flex-shrink: 0;
  padding: 6px 14px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.08);
  color: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease;
}

.q-filter-btn.active {
  background: #8e656f;
  color: #fff2e9;
}

/* Scroll area */
.q-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 4px 14px 40px;
}

.q-empty {
  padding: 80px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  opacity: 0.7;
}

.q-empty-icon {
  font-size: 40px;
  opacity: 0.35;
}

.q-empty-title {
  font-size: 15px;
  font-weight: 700;
}

.q-empty-desc {
  font-size: 12px;
  opacity: 0.6;
  max-width: 240px;
  line-height: 1.6;
}

/* Post card */
.q-post {
  padding: 14px 16px;
  margin-bottom: 12px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow: 0 6px 20px rgba(90, 60, 65, 0.05);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

html[data-runwithme-theme="dark"] .q-post {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.q-post[data-mode="user-asked"] {
  border-left: 3px solid #8e656f;
}

.q-post[data-mode="character-asked"] {
  border-left: 3px solid #9b7f86;
}

.q-post[data-mode="daily"] {
  border-left: 3px solid #cfdee3;
}

.q-post-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.q-post-mode-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.1);
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"] .q-post-mode-tag {
  background: rgba(255, 255, 255, 0.06);
  color: #f3dfe4;
}

.q-post-time {
  flex: 1;
  font-size: 10px;
  opacity: 0.5;
}

.q-post-delete {
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 15px;
  line-height: 1;
  opacity: 0.35;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.q-post-delete:hover {
  opacity: 1;
  background: rgba(224, 93, 93, 0.18);
}

.q-post-asker {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 12px;
  font-weight: 700;
  opacity: 0.75;
}

.q-post-question {
  font-size: 15px;
  line-height: 1.6;
  font-weight: 500;
  margin-bottom: 12px;
  word-break: break-word;
  white-space: pre-wrap;
}

/* Avatars */
.q-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--rw-font-serif);
  font-size: 13px;
  font-weight: 700;
  color: #fff2e9;
  flex-shrink: 0;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4),
    0 2px 6px rgba(0, 0, 0, 0.06);
}

.q-avatar-small {
  width: 26px;
  height: 26px;
  font-size: 11px;
}

.q-avatar-you {
  background: linear-gradient(135deg, #ffd4d8, #fcbec3);
  color: var(--rw-text-muted);
}

.q-avatar-levi {
  background: linear-gradient(135deg, #a37b84, #8e656f);
}

.q-avatar-erwin {
  background: linear-gradient(135deg, #ad8f95, #9b7f86);
}

/* Answers */
.q-post-answers {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 10px;
}

.q-answer {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.06);
  position: relative;
}

html[data-runwithme-theme="dark"] .q-answer {
  background: rgba(255, 255, 255, 0.04);
}

.q-answer-body {
  flex: 1;
  min-width: 0;
}

.q-answer-head strong {
  font-size: 11px;
  font-weight: 700;
  opacity: 0.7;
}

.q-answer-text {
  font-size: 13px;
  line-height: 1.55;
  margin-top: 2px;
  word-break: break-word;
  white-space: pre-wrap;
}

.q-answer-delete {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 14px;
  line-height: 1;
  opacity: 0.3;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.q-answer:hover .q-answer-delete {
  opacity: 0.7;
}

.q-answer-delete:hover {
  opacity: 1 !important;
  background: rgba(224, 93, 93, 0.18);
}

/* Pending */
.q-answer-pending {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}

.q-answer-pending-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  opacity: 0.55;
  font-style: italic;
}

.q-answer-pending-row .q-avatar {
  opacity: 0.7;
}

/* Reply input */
.q-post-reply {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.q-post-reply input {
  flex: 1;
  min-width: 0;
  padding: 9px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.75);
  color: inherit;
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"]
  .q-post-reply input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.08);
}

.q-post-reply input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

.q-post-reply-send {
  flex-shrink: 0;
  padding: 8px 16px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.q-post-reply-send:disabled {
  opacity: 0.4;
  cursor: default;
}

.q-post-hint {
  margin-top: 8px;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.45;
  text-align: right;
}

.q-post-hint-small {
  font-size: 9px;
  letter-spacing: 0.05em;
}

/* =========================================================================
   Modal（提问 & 卡池）
   ========================================================================= */

.q-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9500;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: qFadeIn 0.18s ease;
}

@keyframes qFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.q-modal {
  width: min(480px, 100%);
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg-elevated);
  padding: 22px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.28);
  animation: qSlideIn 0.2s ease;
}

html[data-runwithme-theme="dark"] .q-modal {
  background: #211c20;
  color: #fff2e9;
}

@keyframes qSlideIn {
  from { transform: translateY(-8px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.q-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
