  color: inherit;
  font-size: 18px;
  cursor: pointer;
}

.q-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}

.q-btn {
  padding: 10px 20px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.q-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.q-btn.ghost {
  background: rgba(142, 101, 111, 0.1);
