/* =========================================================================
   全部 Dock 统一放大 + 悬浮效果（终版覆盖）
   - .dock           主屏
   - .icity-dock     iCity
   - .calendar-dock  Calendar
   - .checkin-dock   Check-in
   ========================================================================= */

/* =========================================================================
   1. 主屏 dock
   ========================================================================= */

.dock {
  position: absolute !important;
  left: 50% !important;
  right: auto !important;
  bottom: calc(20px + env(safe-area-inset-bottom)) !important;
  transform: translateX(-50%) !important;

  width: min(92%, 420px) !important;
  height: auto !important;
  min-height: 84px;

  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  gap: clamp(14px, 4vw, 26px) !important;

  padding: 14px 22px !important;
  border-radius: 30px !important;

  background: rgba(255, 255, 255, 0.38) !important;
  border: 1px solid rgba(255, 255, 255, 0.55) !important;

  box-shadow:
    0 18px 40px rgba(80, 50, 60, 0.18),
    0 4px 12px rgba(80, 50, 60, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.65) !important;

  backdrop-filter: blur(28px) saturate(1.8) !important;
  -webkit-backdrop-filter: blur(28px) saturate(1.8) !important;
}

html[data-runwithme-theme="dark"] .dock {
  background: rgba(45, 40, 44, 0.55) !important;
  border-color: rgba(255, 255, 255, 0.1) !important;
  box-shadow:
    0 18px 40px rgba(0, 0, 0, 0.45),
    0 4px 12px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
}

.dock-icon {
  width: 58px !important;
  height: 58px !important;
  flex-shrink: 0;

  border: none !important;
  border-radius: 18px !important;

  background: rgba(255, 255, 255, 0.55) !important;
  color: var(--dark) !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  cursor: pointer;

  box-shadow:
    0 4px 10px rgba(80, 50, 60, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.75);

  transition:
    transform 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

html[data-runwithme-theme="dark"] .dock-icon {
  background: rgba(255, 255, 255, 0.08) !important;
  color: #fff2e9 !important;
  box-shadow:
    0 4px 10px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dock-icon:hover {
  transform: translateY(-3px) scale(1.05);
  background: rgba(255, 255, 255, 0.78) !important;
}

html[data-runwithme-theme="dark"] .dock-icon:hover {
  background: rgba(255, 255, 255, 0.16) !important;
}

.dock-icon:active {
  transform: scale(0.94);
}

.dock-icon > svg {
  width: 26px !important;
  height: 26px !important;
  display: block;
}

.dock-icon > span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-size: 26px !important;
  line-height: 1;
}

.dock-icon:not(:has(> svg)):not(:has(> img)):not(:has(> span)) {
  font-size: 26px !important;
}

.dock-icon > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: inherit;
}

