/* =========================================================================
   Chat · 语音气泡 v2
   ========================================================================= */

.chat-voice-v2 {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 160px;
  max-width: 240px;
}

.chat-voice-bubble {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--chat-border);
  border-radius: 18px;
  background: var(--chat-bubble-other);
  color: var(--chat-text);
  cursor: pointer;
  font: inherit;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
  box-shadow: 0 2px 7px rgba(80, 50, 60, 0.045);
}

.message-you .chat-voice-bubble {
  background: var(--chat-bubble-you);
  color: var(--rw-text);
  border-color: rgba(255, 255, 255, 0.18);
}

.chat-voice-bubble:active {
  transform: scale(0.98);
}

.chat-voice-bubble:disabled {
  opacity: 0.6;
  cursor: default;
}

.chat-voice-play {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: -1px;
}

.message-you .chat-voice-play {
  background: rgba(255, 255, 255, 0.55);
}

.chat-voice-wave {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  height: 20px;
  min-width: 0;
}

.chat-voice-bar {
  width: 2px;
  border-radius: 2px;
  background: currentColor;
  transition: opacity 0.2s ease;
  flex-shrink: 0;
}

.chat-voice-time {
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 600;
  opacity: 0.7;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.chat-voice-transcribe {
  align-self: flex-start;
  padding: 4px 10px;
  border: 0;
  border-radius: 10px;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0.7;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.chat-voice-transcribe:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.2);
}

.message-you .chat-voice-transcribe {
  align-self: flex-end;
}

.chat-voice-text {
  padding: 8px 12px;
  border-radius: 12px;
