/* =========================================================================
   Chat · 数据管理区块
   ========================================================================= */

.chat-settings-storage {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  border-radius: 14px;
  background: rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .chat-settings-storage {
  background: rgba(255, 255, 255, 0.04);
}

.chat-settings-storage-info strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
}

.chat-settings-storage-info small {
  display: block;
  margin-top: 3px;
