/* =========================================================================
   Focus Overlay · 全屏专注模式
   ========================================================================= */

.focus-overlay {
  position: fixed;
  inset: 0;
  z-index: 8500;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  cursor: pointer;
  animation: focusOverlayIn 0.3s ease;
  touch-action: none;
}

@keyframes focusOverlayIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.focus-wallpaper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
  user-select: none;
}

.focus-wallpaper-empty {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 30% 25%,
      rgba(252, 190, 195, 0.35),
      transparent 45%
    ),
    radial-gradient(
      circle at 75% 75%,
      rgba(207, 222, 227, 0.4),
      transparent 45%
    ),
    linear-gradient(160deg, #2a2226 0%, #181418 100%);
}

.focus-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0.25) 0%,
    rgba(0, 0, 0, 0.05) 35%,
    rgba(0, 0, 0, 0.05) 65%,
    rgba(0, 0, 0, 0.4) 100%
  );
  pointer-events: none;
}

/* ---------- 顶部提示 ---------- */

.focus-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: calc(env(safe-area-inset-top) + 20px) 20px 0;
  display: flex;
  justify-content: center;
  z-index: 2;
}

.focus-top-hint {
  padding: 6px 14px;
  border-radius: var(--rw-radius-pill);
  background: rgba(0, 0, 0, 0.28);
  color: rgba(255, 255, 255, 0.75);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  animation: focusHintFade 6s ease forwards;
}

@keyframes focusHintFade {
  0%,
  70% {
    opacity: 1;
  }
  100% {
    opacity: 0.2;
  }
}

/* ---------- 中央 ---------- */

.focus-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  z-index: 2;
  padding: 80px 20px;
  pointer-events: none;
}

.focus-time {
  font-family: var(--rw-font-serif);
  font-size: 96px;
  font-weight: 300;
  line-height: 1;
  letter-spacing: -0.03em;
  color: #ffffff;
  font-variant-numeric: tabular-nums;
  text-shadow:
    0 4px 20px rgba(0, 0, 0, 0.45),
    0 1px 2px rgba(0, 0, 0, 0.3);
}

.focus-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.7);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.focus-progress-line {
  width: min(240px, 60%);
  height: 2px;
  margin-top: 20px;
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.18);
  overflow: hidden;
}

.focus-progress-fill {
  height: 100%;
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.75);
  transition: width 0.4s linear;
}

/* ---------- 底部播放/暂停 ---------- */

.focus-controls {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(60px + env(safe-area-inset-bottom));
  display: flex;
  justify-content: center;
  z-index: 3;
}

.focus-btn {
  width: 72px;
  height: 72px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
  font-size: 24px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow:
    0 8px 28px rgba(0, 0, 0, 0.3),
    inset 0 0 0 1px rgba(255, 255, 255, 0.18);
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.focus-btn:hover {
  background: rgba(255, 255, 255, 0.28);
  transform: scale(1.05);
}

.focus-btn:active {
  transform: scale(0.94);
}

/* ---------- 长按进度条 ---------- */

.focus-longpress-bar {
  position: absolute;
  left: 50%;
  bottom: calc(20px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  width: min(220px, 70%);
  height: 3px;
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.15);
  overflow: hidden;
  z-index: 4;
}

.focus-longpress-fill {
  height: 100%;
  border-radius: var(--rw-radius-pill);
  background: #fcbec3;
  transition: width 0.06s linear;
}

/* ---------- PomodoroPanel 里手动进入按钮 ---------- */

.checkin-pomo-enter-focus {
  margin-top: 14px;
  padding: 10px 20px;
  border: 1px solid rgba(142, 101, 111, 0.22);
  border-radius: var(--rw-radius-pill);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.checkin-pomo-enter-focus:hover {
  background: rgba(252, 190, 195, 0.2);
  transform: translateY(-1px);
}

/* ---------- PomodoroPanel 里的壁纸区块 ---------- */

.checkin-focus-wallpaper-section {
  margin-top: 6px;
  padding: 14px;
  border-radius: 14px;
  background: rgba(142, 101, 111, 0.06);
  border: 1px solid rgba(142, 101, 111, 0.08);
}

html[data-runwithme-theme="dark"]
  .checkin-focus-wallpaper-section {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.06);
}

.checkin-focus-wallpaper-label {
  margin-bottom: 10px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.6;
}

.checkin-focus-wallpaper-preview {
  width: 100%;
  height: 140px;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(142, 101, 111, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(142, 101, 111, 0.5);
  font-size: 12px;
  margin-bottom: 10px;
}

html[data-runwithme-theme="dark"]
  .checkin-focus-wallpaper-preview {
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 244, 239, 0.4);
}

.checkin-focus-wallpaper-preview img,
.checkin-focus-wallpaper-preview video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.checkin-focus-wallpaper-actions {
  display: flex;
  gap: 8px;
}

.checkin-focus-wallpaper-actions .checkin-btn {
  flex: 1;
  padding: 9px 14px;
  font-size: 12px;
}

.checkin-focus-wallpaper-actions .checkin-btn.danger {
  flex: 0 0 auto;
  background: rgba(224, 93, 93, 0.14);
  color: #e05d5d;
}

.checkin-focus-wallpaper-hint {
  margin-top: 8px;
  font-size: 10px;
  line-height: 1.5;
  opacity: 0.55;
}
/* =========================================================================
   Focus Overlay · 白噪音按钮 + PomodoroPanel 白噪音区块
   ========================================================================= */

/* ---------- 全屏专注层底部按钮区：喇叭 + 播放并排 ---------- */

.focus-controls {
  gap: 20px;
  align-items: center;
}

.focus-noise-btn {
  width: 54px;
  height: 54px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
  color: #ffffff;
  font-size: 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow:
    0 6px 20px rgba(0, 0, 0, 0.25),
    inset 0 0 0 1px rgba(255, 255, 255, 0.14);
  transition:
    transform 0.15s ease,
    background 0.15s ease,
    opacity 0.15s ease;
  opacity: 0.75;
}

.focus-noise-btn:hover {
  opacity: 1;
  background: rgba(255, 255, 255, 0.24);
  transform: scale(1.05);
}

.focus-noise-btn:active {
  transform: scale(0.94);
}

.focus-noise-btn.is-on {
  opacity: 1;
  background: rgba(252, 190, 195, 0.32);
  box-shadow:
    0 6px 20px rgba(0, 0, 0, 0.25),
    inset 0 0 0 1px rgba(252, 190, 195, 0.4);
}

/* ---------- PomodoroPanel 白噪音预览 ---------- */

.checkin-focus-noise-preview {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.5);
  margin-bottom: 10px;
  font-size: 12px;
  min-width: 0;
}

html[data-runwithme-theme="dark"]
  .checkin-focus-noise-preview {
  background: rgba(255, 255, 255, 0.05);
}

.checkin-focus-noise-icon {
  font-size: 18px;
  flex-shrink: 0;
}

.checkin-focus-noise-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--rw-text-muted);
  font-weight: 600;
}

html[data-runwithme-theme="dark"]
  .checkin-focus-noise-name {
  color: #f3dfe4;
}

.checkin-focus-noise-empty {
  font-size: 12px;
  opacity: 0.5;
}
/* =========================================================================
   Focus Overlay · 完成按钮 + 阻止卡
   ========================================================================= */

/* 让底部三个按钮均匀 */
.focus-controls {
  gap: 18px;
  align-items: center;
}

/* 完成按钮 */
.focus-finish-btn {
  width: 54px;
  height: 54px;
  border: 0;
  border-radius: 50%;
  background: rgba(126, 209, 126, 0.28);
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow:
    0 6px 20px rgba(0, 0, 0, 0.25),
    inset 0 0 0 1px rgba(126, 209, 126, 0.45);
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.focus-finish-btn:hover {
  background: rgba(126, 209, 126, 0.45);
  transform: scale(1.05);
}

.focus-finish-btn:active {
  transform: scale(0.94);
}

/* ---------- 阻止卡 ---------- */

.focus-block-backdrop {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  animation: focusBlockIn 0.22s ease;
}

@keyframes focusBlockIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.focus-block-card {
  width: min(320px, 100%);
  padding: 26px 22px 20px;
  border-radius: var(--rw-radius-xl);
  background: rgba(255, 248, 245, 0.98);
  color: var(--rw-text);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  box-shadow:
    0 25px 60px rgba(0, 0, 0, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.6);
  animation: focusBlockCardIn 0.24s ease;
}

@keyframes focusBlockCardIn {
  from { transform: scale(0.94); opacity: 0; }
  to   { transform: scale(1);    opacity: 1; }
}

.focus-block-avatar {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 700;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4);
}

.focus-block-avatar-levi {
  background: linear-gradient(135deg, #a37b84, #8e656f);
}

.focus-block-avatar-erwin {
  background: linear-gradient(135deg, #ad8f95, #9b7f86);
}

.focus-block-name {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
  margin-top: -2px;
}

.focus-block-text {
  font-family: var(--rw-font-serif);
  font-size: 20px;
  font-weight: 500;
  line-height: 1.4;
  text-align: center;
  color: #5e4650;
  padding: 0 4px;
  margin: 4px 0 12px;
}

.focus-block-actions {
  display: flex;
  gap: 8px;
  width: 100%;
}

.focus-block-stay,
.focus-block-leave {
  flex: 1;
  padding: 11px 14px;
  border: 0;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.focus-block-stay {
  background: #8e656f;
  color: #fff2e9;
  box-shadow: 0 6px 14px rgba(142, 101, 111, 0.24);
}

.focus-block-stay:hover {
  transform: translateY(-1px);
}

.focus-block-stay:active {
  transform: scale(0.96);
}

.focus-block-leave {
  background: rgba(142, 101, 111, 0.1);
  color: var(--rw-text-muted);
}

.focus-block-leave:hover {
  background: rgba(142, 101, 111, 0.18);
}

.focus-block-leave:active {
  transform: scale(0.96);
}
/* =========================================================================
   Focus Overlay · 语音气泡随机位置 + 完成弹窗
   ========================================================================= */

/* ---------- 覆盖旧 .focus-bubble 的定位 ---------- */

.focus-bubble {
  position: absolute;
  /* 移除旧的 right / bottom，改由 inline style 控制 left/top */
  right: auto;
  bottom: auto;
  z-index: 8;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  max-width: min(280px, 82%);
  animation: focusBubbleIn 0.35s cubic-bezier(
    0.34,
    1.56,
    0.64,
    1
  );
}

/* ---------- 完成弹窗 ---------- */

.focus-completion-card {
  padding-bottom: 20px;
}

.focus-completion-subtitle {
  margin: 4px 0 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--rw-text-muted);
  opacity: 0.65;
  text-align: center;
}

.focus-completion-actions {
  display: flex;
  gap: 8px;
  width: 100%;
}

.focus-completion-primary,
.focus-completion-secondary {
  flex: 1;
  padding: 12px 14px;
  border: 0;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.focus-completion-primary {
  background: #8e656f;
  color: #fff2e9;
