}

.focus-completion-secondary {
  background: rgba(252, 190, 195, 0.4);
  color: var(--rw-text-muted);
}

.focus-completion-secondary:hover {
  background: rgba(252, 190, 195, 0.6);
}

.focus-completion-secondary:active {
  transform: scale(0.96);
}

