/* =========================================================================
   Focus Bubble · Liquid Glass
   覆盖之前所有 .focus-bubble 相关规则
   ========================================================================= */

.focus-bubble {
  position: absolute;
  right: auto;
  bottom: auto;
  z-index: 8;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  max-width: min(300px, 82%);
  animation: focusBubbleIn 0.45s cubic-bezier(
    0.34,
    1.56,
    0.64,
    1
  );
}

/* ---------- 液态玻璃主体 ---------- */

.focus-bubble-body {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px 12px 12px;
  border: 0;
  border-radius: var(--rw-radius-xl);
  color: var(--rw-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  max-width: 100%;

  /* 多层渐变模拟液态玻璃的折射 */
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.62) 0%,
    rgba(255, 255, 255, 0.32) 45%,
    rgba(255, 255, 255, 0.45) 100%
  );

  /* 外阴影扩散 + 顶部内高光 + 底部内暗边 + 描边 */
  box-shadow:
    0 14px 36px rgba(20, 10, 15, 0.28),
    0 2px 8px rgba(20, 10, 15, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba(0, 0, 0, 0.06),
    inset 0 0 0 1px rgba(255, 255, 255, 0.48);

  backdrop-filter: blur(28px) saturate(1.9);
  -webkit-backdrop-filter: blur(28px) saturate(1.9);

  transition:
    transform 0.22s cubic-bezier(0.34, 1.3, 0.64, 1),
    box-shadow 0.22s ease;
}

/* 顶部高光弧 */
.focus-bubble-body::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    ellipse at 22% -25%,
    rgba(255, 255, 255, 0.85),
    transparent 55%
  );
  pointer-events: none;
}

/* 底部 + 右侧的彩色折射（品牌色微透） */
.focus-bubble-body::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(
      circle at 88% 110%,
      rgba(252, 190, 195, 0.4),
      transparent 55%
    ),
    radial-gradient(
      circle at -10% -10%,
      rgba(207, 222, 227, 0.35),
      transparent 50%
    );
  pointer-events: none;
  mix-blend-mode: soft-light;
}

.focus-bubble-body:hover {
  transform: translateY(-2px);
  box-shadow:
    0 20px 44px rgba(20, 10, 15, 0.34),
    0 4px 12px rgba(20, 10, 15, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.08),
    inset 0 0 0 1px rgba(255, 255, 255, 0.6);
}

.focus-bubble-body:active {
  transform: scale(0.97);
  transition-duration: 0.1s;
}

/* ---------- 头像 ---------- */

.focus-bubble-avatar {
  position: relative;
  z-index: 1;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.02em;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.55),
    inset 0 -1px 0 rgba(0, 0, 0, 0.12),
    0 3px 10px rgba(80, 50, 60, 0.18);
}

.focus-bubble-avatar-levi {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.focus-bubble-avatar-erwin {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

/* ---------- 文字区 ---------- */

.focus-bubble-content {
  position: relative;
  z-index: 1;
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.focus-bubble-name {
  font-family: var(--rw-font-serif);
  font-size: 11px;
  font-style: italic;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(94, 70, 80, 0.62);
  padding-left: 1px;
}

.focus-bubble-text {
  font-family: var(--rw-font-serif);
  font-size: 17px;
  font-weight: 500;
  line-height: 1.32;
  letter-spacing: 0.002em;
  color: #46323a;
  word-break: break-word;
  white-space: pre-wrap;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.5);
}

/* ---------- 播放键（融合进液态玻璃） ---------- */

.focus-bubble-play {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--rw-text-muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;

  background: linear-gradient(
    140deg,
    rgba(255, 255, 255, 0.78),
    rgba(255, 255, 255, 0.38)
  );

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.06),
    inset 0 0 0 1px rgba(255, 255, 255, 0.55),
    0 3px 8px rgba(80, 50, 60, 0.12);

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);

  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.focus-bubble-body:hover .focus-bubble-play {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.08),
    inset 0 0 0 1px rgba(255, 255, 255, 0.7),
    0 5px 12px rgba(80, 50, 60, 0.18);
}

/* ---------- 关闭按钮（同样玻璃化） ---------- */

.focus-bubble-close {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  margin-top: 4px;
  border: 0;
  border-radius: 50%;
  color: rgba(255, 255, 255, 0.92);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;

  background: linear-gradient(
    140deg,
    rgba(255, 255, 255, 0.28),
    rgba(255, 255, 255, 0.12)
  );

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.22),
    0 2px 6px rgba(0, 0, 0, 0.14);

  backdrop-filter: blur(16px) saturate(1.6);
  -webkit-backdrop-filter: blur(16px) saturate(1.6);

  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.focus-bubble-close:hover {
  background: linear-gradient(
    140deg,
    rgba(255, 255, 255, 0.42),
    rgba(255, 255, 255, 0.2)
  );
  transform: scale(1.06);
}

.focus-bubble-close:active {
  transform: scale(0.92);
}
/* =========================================================================
   App Window Slot · 常驻 App 容器
   每个打开过的 App 都在 DOM 里，切换只切 display
   ========================================================================= */

.app-window-slot {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

/* 确保里面的 .app-screen 撑满 */
.app-window-slot > .app-screen {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}
/* =========================================================================
   Study App
   ========================================================================= */

.study-app {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--rw-bg);
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"] .study-app {
  background: #17131a;
  color: #fff2e9;
}

/* ---------- Header ---------- */

.study-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px 6px;
}

.study-back {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 30px;
  cursor: pointer;
}

.study-back:hover {
  background: rgba(142, 101, 111, 0.08);
}

.study-header-center {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.study-header-title {
  font-family: var(--rw-font-serif);
  font-size: 24px;
  font-weight: 600;
  line-height: 1;
}

.study-header-sub {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: lowercase;
  opacity: 0.55;
  margin-top: 3px;
}

.study-header-placeholder {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
}

/* ---------- Scroll ---------- */

.study-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 12px 16px
    calc(110px + env(safe-area-inset-bottom));
}

/* ---------- Empty ---------- */

.study-empty {
  padding: 80px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  opacity: 0.7;
}

.study-empty-icon {
  font-size: 42px;
  opacity: 0.4;
  margin-bottom: 6px;
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"]
  .study-empty-icon {
  color: #fcbec3;
}

.study-empty-title {
  font-size: 15px;
  font-weight: 700;
}

.study-empty-desc {
  font-size: 12px;
  opacity: 0.65;
  max-width: 240px;
  line-height: 1.6;
}

/* ---------- Dock ---------- */

.study-dock {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
  padding: 0 16px
    calc(14px + env(safe-area-inset-bottom));
  pointer-events: none;
}

.study-dock-inner {
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 62px;
  padding: 0 8px;
  border-radius: 26px;
  background: rgba(255, 248, 243, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.8);
  box-shadow:
    0 10px 30px rgba(80, 50, 60, 0.1),
    0 2px 8px rgba(80, 50, 60, 0.06);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

html[data-runwithme-theme="dark"]
  .study-dock-inner {
  background: rgba(33, 28, 32, 0.85);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-dock-tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 8px 0;
  border: 0;
  border-radius: 16px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  opacity: 0.45;
  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease;
}

.study-dock-icon {
  font-size: 20px;
  line-height: 1;
}

.study-dock-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.study-dock-tab.active {
  opacity: 1;
  color: var(--rw-text-muted);
}

html[data-runwithme-theme="dark"]
  .study-dock-tab.active {
  color: #fcbec3;
}

.study-dock-tab:hover:not(.active) {
  opacity: 0.75;
}

.study-dock-tab:active {
  background: rgba(142, 101, 111, 0.08);
}
/* =========================================================================
   Study · Library / BookDetail / Modals
   ========================================================================= */

/* ---------- 通用按钮 ---------- */

.study-add-btn {
  flex-shrink: 0;
  padding: 8px 14px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.study-add-btn:hover {
  transform: translateY(-1px);
}

.study-add-btn:active {
  transform: scale(0.96);
}

/* ---------- Library 顶部 ---------- */

.study-library-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 4px 12px;
}

.study-library-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0.55;
}

/* ---------- 词书列表 ---------- */

.study-book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.study-book-item {
  display: flex;
  align-items: stretch;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 14px rgba(90, 60, 65, 0.05);
  overflow: hidden;
}

html[data-runwithme-theme="dark"]
  .study-book-item {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-book-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 12px 14px 14px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease;
}

.study-book-main:hover {
  background: rgba(255, 255, 255, 0.4);
}

html[data-runwithme-theme="dark"]
  .study-book-main:hover {
  background: rgba(255, 255, 255, 0.04);
}

.study-book-cover {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(145deg, #fcbec3, #cfdee3);
  color: var(--rw-text-muted);
  font-family: var(--rw-font-serif);
  font-size: 20px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
    0 3px 10px rgba(80, 50, 60, 0.1);
}

.study-book-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.study-book-info strong {
  font-size: 14px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.study-book-meta {
  font-size: 11px;
  opacity: 0.6;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.study-book-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-right: 10px;
  flex-shrink: 0;
}

.study-book-action {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.55;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.study-book-action:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.1);
}

.study-book-action.danger:hover {
  background: rgba(224, 93, 93, 0.15);
}

/* ---------- 词书详情 Subheader ---------- */

.study-subheader {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px 6px;
}

.study-subheader-add {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: #8e656f;
  color: #fff2e9;
  font-size: 20px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 14px rgba(142, 101, 111, 0.24);
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.study-subheader-add:hover {
  transform: translateY(-1px);
}

.study-subheader-add:active {
  transform: scale(0.94);
}

/* ---------- 搜索框 ---------- */

.study-search-wrap {
  padding: 4px 4px 12px;
}

.study-search-input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"]
  .study-search-input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.study-search-input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

/* ---------- 单词列表 ---------- */

.study-word-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.study-word-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 12px 12px 12px 14px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 3px 10px rgba(90, 60, 65, 0.04);
}

html[data-runwithme-theme="dark"]
  .study-word-item {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-word-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.study-word-text {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  font-family: var(--rw-font-serif);
  font-size: 18px;
  font-weight: 600;
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"]
  .study-word-text {
  color: #fff2e9;
}

.study-word-mastery {
  padding: 2px 8px;
  border-radius: var(--rw-radius-pill);
  font-family: "Noto Sans SC", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.study-word-mastery-new {
  background: rgba(142, 101, 111, 0.12);
  color: var(--rw-text-muted);
}

.study-word-mastery-learning {
  background: rgba(207, 222, 227, 0.6);
  color: #536a72;
}

.study-word-mastery-mastered {
  background: rgba(126, 209, 126, 0.3);
  color: #2d6f2d;
}

html[data-runwithme-theme="dark"]
  .study-word-mastery-new {
  background: rgba(255, 255, 255, 0.08);
  color: #d9bcc4;
}

html[data-runwithme-theme="dark"]
  .study-word-mastery-learning {
  background: rgba(207, 222, 227, 0.16);
  color: #cfdee3;
}

html[data-runwithme-theme="dark"]
  .study-word-mastery-mastered {
  background: rgba(126, 209, 126, 0.18);
  color: #8fdc8f;
}

.study-word-meaning {
  font-size: 13px;
  line-height: 1.5;
  opacity: 0.85;
}

.study-word-example {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.55;
  font-style: italic;
}

.study-word-actions {
  display: flex;
  gap: 2px;
  flex-shrink: 0;
}

.study-word-action {
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.45;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.study-word-action:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.1);
}

.study-word-action.danger:hover {
  background: rgba(224, 93, 93, 0.15);
}

/* ---------- Modal ---------- */

.study-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9500;
  background: rgba(0, 0, 0, 0.42);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: studyFadeIn 0.18s ease;
}

@keyframes studyFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.study-modal {
  width: min(420px, 100%);
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--rw-radius-xl);
  background: var(--rw-bg-elevated);
  color: var(--rw-text);
  padding: 22px;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.28);
  animation: studyModalIn 0.2s ease;
}

html[data-runwithme-theme="dark"] .study-modal {
  background: #211c20;
  color: #fff2e9;
}

@keyframes studyModalIn {
  from { transform: translateY(-8px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.study-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.study-modal-header h2 {
  margin: 0;
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 500;
}

.study-modal-close {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 18px;
  cursor: pointer;
}

html[data-runwithme-theme="dark"]
  .study-modal-close {
  background: rgba(255, 255, 255, 0.06);
}

.study-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.study-field > span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.6;
}

.study-field input {
  width: 100%;
  padding: 11px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"]
  .study-field input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.study-field input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

.study-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

.study-btn {
  padding: 10px 20px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #8e656f;
  color: #fff2e9;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.study-btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.study-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.study-btn.ghost {
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
}

html[data-runwithme-theme="dark"]
  .study-btn.ghost {
  background: rgba(255, 255, 255, 0.06);
}
/* =========================================================================
   Study · Library 顶部操作 + CSV 导入
   ========================================================================= */

.study-library-top-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.study-import-btn {
  flex-shrink: 0;
  padding: 8px 14px;
  border: 1px solid rgba(142, 101, 111, 0.22);
  border-radius: var(--rw-radius-pill);
  background: transparent;
  color: var(--rw-text-muted);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.study-import-btn:hover {
  background: rgba(252, 190, 195, 0.2);
  transform: translateY(-1px);
}

.study-import-btn:active {
  transform: scale(0.96);
}

html[data-runwithme-theme="dark"] .study-import-btn {
  color: #f3dfe4;
  border-color: rgba(255, 255, 255, 0.15);
}

html[data-runwithme-theme="dark"]
  .study-import-btn:hover {
  background: rgba(252, 190, 195, 0.1);
}

/* ---------- Import Modal ---------- */

.study-import-modal {
  max-width: 480px;
}

.study-import-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.study-import-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.6;
}

.study-import-target {
  display: flex;
  gap: 12px;
}

.study-import-radio {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 10px;
