.study-voice-segment button {
  flex: 1;
  padding: 9px 12px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.study-voice-segment button.active {
  background: #fcbec3;
  color: var(--rw-text-muted);
  font-weight: 700;
}

html[data-runwithme-theme="dark"]
  .study-voice-segment button.active {
  background: rgba(252, 190, 195, 0.3);
  color: #f3dfe4;
}
/* =========================================================================
   Study Session · 3D 翻转卡片 + 判定按钮
   ========================================================================= */

/* 移除旧的 .study-flip-card 样式（用新版本覆盖） */

.study-flip-scene {
  width: 100%;
  max-width: 380px;
  aspect-ratio: 3 / 4;
  max-height: 100%;
  perspective: 1400px;
  display: flex;
  align-items: stretch;
  justify-content: center;
}

.study-flip-card {
  position: relative;
  width: 100%;
  height: 100%;
  border: 0;
  padding: 0;
  background: transparent;
  font: inherit;
  color: inherit;
  cursor: pointer;
  transform-style: preserve-3d;
  transition: transform 0.55s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.study-flip-card.is-flipped {
  transform: rotateY(180deg);
}

.study-flip-face {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 32px 26px;
  border-radius: 28px;
  border: 1px solid rgba(255, 255, 255, 0.85);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  box-sizing: border-box;
  text-align: center;
}

html[data-runwithme-theme="dark"] .study-flip-face {
  border-color: rgba(255, 255, 255, 0.08);
}

/* 正面 */
.study-flip-front {
  background: linear-gradient(
    160deg,
    rgba(255, 255, 255, 0.92),
    rgba(255, 242, 233, 0.88)
  );
  color: var(--rw-text);
  box-shadow:
    0 12px 40px rgba(90, 60, 65, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

html[data-runwithme-theme="dark"] .study-flip-front {
  background: linear-gradient(
    160deg,
    rgba(48, 42, 47, 0.9),
    rgba(33, 28, 32, 0.88)
  );
  color: #fff2e9;
}

/* 背面 */
.study-flip-back {
  background: linear-gradient(
    160deg,
    rgba(252, 190, 195, 0.28),
    rgba(207, 222, 227, 0.32)
  );
  color: var(--rw-text);
  transform: rotateY(180deg);
  box-shadow:
    0 12px 40px rgba(90, 60, 65, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

html[data-runwithme-theme="dark"] .study-flip-back {
  background: linear-gradient(
    160deg,
    rgba(142, 101, 111, 0.35),
    rgba(70, 80, 90, 0.35)
  );
  color: #fff2e9;
}

/* 正面内容 */
.study-flip-word {
  font-family: var(--rw-font-serif);
  font-size: 40px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.01em;
  word-break: break-word;
}

.study-flip-hint {
  font-size: 12px;
  opacity: 0.4;
  letter-spacing: 0.05em;
  margin-top: auto;
}

/* 播放按钮 */
.study-flip-play {
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(
    140deg,
    rgba(255, 255, 255, 0.85),
    rgba(255, 255, 255, 0.45)
  );
  color: var(--rw-text-muted);
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 0 0 1px rgba(255, 255, 255, 0.5),
    0 4px 12px rgba(142, 101, 111, 0.14);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.study-flip-play:hover {
  transform: scale(1.06);
}

.study-flip-play:active {
  transform: scale(0.94);
}

.study-flip-play.is-playing {
  background: linear-gradient(140deg, #8e656f, #a67b85);
  color: #fff2e9;
}

html[data-runwithme-theme="dark"] .study-flip-play {
  background: linear-gradient(
    140deg,
    rgba(255, 255, 255, 0.14),
    rgba(255, 255, 255, 0.05)
  );
  color: #f3dfe4;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    0 4px 12px rgba(0, 0, 0, 0.3);
}

html[data-runwithme-theme="dark"]
  .study-flip-play.is-playing {
  background: linear-gradient(140deg, #fcbec3, #b08a93);
  color: var(--rw-text);
}

/* 背面内容 */
.study-flip-meaning {
  font-size: 22px;
  line-height: 1.4;
  font-weight: 500;
  word-break: break-word;
  font-family: var(--rw-font-serif);
}

.study-flip-example {
  font-size: 14px;
  font-style: italic;
  line-height: 1.55;
  opacity: 0.65;
  padding: 0 8px;
}

/* ---------- 判定按钮 ---------- */

.study-session-btn-known,
.study-session-btn-unknown {
  color: #fff2e9;
  border-color: transparent !important;
}

.study-session-btn-known {
  background: #7ed17e !important;
  color: #143c14 !important;
  box-shadow: 0 8px 18px rgba(126, 209, 126, 0.28) !important;
}

.study-session-btn-known:hover:not(:disabled) {
  background: #90dd90 !important;
}

.study-session-btn-unknown {
  background: #e05d5d !important;
  color: #fff2e9 !important;
  box-shadow: 0 8px 18px rgba(224, 93, 93, 0.28) !important;
}

.study-session-btn-unknown:hover:not(:disabled) {
  background: #eb7070 !important;
}

html[data-runwithme-theme="dark"]
  .study-session-btn-known {
  background: #7ed17e !important;
  color: #143c14 !important;
}

html[data-runwithme-theme="dark"]
  .study-session-btn-unknown {
  background: #e05d5d !important;
  color: #fff2e9 !important;
}
/* =========================================================================
   Study · 模式切换 + 拼写模式 + 会话数量设置
   ========================================================================= */

/* ---------- 模式切换 ---------- */

.study-mode-segment {
  flex-shrink: 0;
  display: flex;
  gap: 4px;
  padding: 0 16px 10px;
}

.study-mode-segment button {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 12px;
  border: 0;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.06);
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0.6;
  transition:
    background 0.15s ease,
    opacity 0.15s ease,
    color 0.15s ease;
}

html[data-runwithme-theme="dark"]
  .study-mode-segment button {
  background: rgba(255, 255, 255, 0.04);
}

.study-mode-segment button.active {
  background: rgba(252, 190, 195, 0.35);
  color: var(--rw-text-muted);
  opacity: 1;
  font-weight: 700;
}

html[data-runwithme-theme="dark"]
  .study-mode-segment button.active {
  background: rgba(252, 190, 195, 0.15);
  color: #f3dfe4;
}

.study-mode-segment-icon {
  font-size: 14px;
  line-height: 1;
}

/* ---------- 拼写模式 ---------- */

.study-spell-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 30px;
  padding: 20px 24px;
  overflow-y: auto;
}

.study-spell-prompt {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  width: 100%;
  max-width: 380px;
  text-align: center;
}

.study-spell-prompt-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  opacity: 0.5;
}

.study-spell-meaning {
  font-family: var(--rw-font-serif);
  font-size: 30px;
  font-weight: 500;
  line-height: 1.3;
  color: var(--rw-text);
  word-break: break-word;
}

html[data-runwithme-theme="dark"]
  .study-spell-meaning {
  color: #fff2e9;
}

.study-spell-example {
  font-size: 14px;
  line-height: 1.5;
  font-style: italic;
  opacity: 0.6;
  word-break: break-word;
  padding: 0 8px;
}

.study-spell-answer {
  padding: 10px 18px;
  border-radius: 14px;
  background: rgba(224, 93, 93, 0.12);
  color: var(--rw-text-muted);
  font-size: 14px;
  line-height: 1.5;
  animation: studyFlipIn 0.25s ease;
}

html[data-runwithme-theme="dark"]
  .study-spell-answer {
  background: rgba(224, 93, 93, 0.15);
  color: #f3dfe4;
}

.study-spell-answer strong {
  margin-left: 6px;
  font-family: var(--rw-font-serif);
  font-size: 18px;
  font-weight: 700;
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"]
  .study-spell-answer strong {
  color: #fff2e9;
}

/* 输入框 */

.study-spell-input-wrap {
  position: relative;
  width: 100%;
  max-width: 380px;
  transition: transform 0.15s ease;
}

.study-spell-input {
  width: 100%;
  padding: 16px 50px 16px 20px;
  border: 1px solid rgba(142, 101, 111, 0.16);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.8);
  color: var(--rw-text);
  font: inherit;
  font-size: 20px;
  font-family: var(--rw-font-serif);
  font-weight: 500;
  letter-spacing: 0.01em;
  outline: none;
  box-sizing: border-box;
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}

html[data-runwithme-theme="dark"]
  .study-spell-input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  color: #fff2e9;
}

.study-spell-input::placeholder {
  color: rgba(142, 101, 111, 0.35);
  font-style: italic;
}

.study-spell-input:focus {
  border-color: rgba(142, 101, 111, 0.45);
  box-shadow: 0 0 0 4px rgba(252, 190, 195, 0.25);
}

.study-spell-input:disabled {
  opacity: 0.9;
  cursor: default;
}

.study-spell-input-wrap.study-spell-input-correct
  .study-spell-input {
  border-color: rgba(126, 209, 126, 0.7);
  background: rgba(126, 209, 126, 0.15);
}

html[data-runwithme-theme="dark"]
  .study-spell-input-wrap.study-spell-input-correct
  .study-spell-input {
  background: rgba(126, 209, 126, 0.12);
  color: #8fdc8f;
}

.study-spell-input-wrap.study-spell-input-wrong
  .study-spell-input {
  border-color: rgba(224, 93, 93, 0.6);
  background: rgba(224, 93, 93, 0.12);
  animation: studyShake 0.4s ease;
}

html[data-runwithme-theme="dark"]
  .study-spell-input-wrap.study-spell-input-wrong
  .study-spell-input {
  background: rgba(224, 93, 93, 0.15);
  color: #eb9090;
}

@keyframes studyShake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  75% { transform: translateX(6px); }
}

.study-spell-icon {
  position: absolute;
  right: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 22px;
  font-weight: 700;
  pointer-events: none;
}

.study-spell-icon-correct {
  color: #4d9a4d;
}

.study-spell-icon-wrong {
  color: #c94d4d;
}

/* 反馈 */

.study-spell-feedback {
  flex: 1;
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 14px 20px;
  animation: studyFlipIn 0.25s ease;
}

/* ---------- 每轮单词数设置 ---------- */

.study-session-size-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.study-session-size-step {
  flex-shrink: 0;
  min-width: 46px;
  padding: 10px 12px;
  border: 1px solid rgba(142, 101, 111, 0.16);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.6);
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

html[data-runwithme-theme="dark"]
  .study-session-size-step {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

.study-session-size-step:hover {
  background: rgba(252, 190, 195, 0.2);
}

.study-session-size-step:active {
  transform: scale(0.96);
}

.study-session-size-input {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 16px;
  font-weight: 700;
  text-align: center;
  outline: none;
  box-sizing: border-box;
  font-variant-numeric: tabular-nums;
}

html[data-runwithme-theme="dark"]
  .study-session-size-input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.study-session-size-input:focus {
  border-color: rgba(142, 101, 111, 0.4);
}

/* 去掉 number input 的上下箭头 */
.study-session-size-input::-webkit-outer-spin-button,
.study-session-size-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.study-session-size-input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}

.study-session-size-quick {
  display: flex;
  gap: 6px;
}

.study-session-size-quick button {
  flex: 1;
  padding: 8px 10px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.5);
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

html[data-runwithme-theme="dark"]
  .study-session-size-quick button {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.08);
}

.study-session-size-quick button.active {
  background: rgba(252, 190, 195, 0.4);
  border-color: rgba(252, 190, 195, 0.6);
  color: var(--rw-text-muted);
  font-weight: 700;
}

html[data-runwithme-theme="dark"]
  .study-session-size-quick button.active {
  background: rgba(252, 190, 195, 0.15);
  border-color: rgba(252, 190, 195, 0.3);
  color: #f3dfe4;
}
/* =========================================================================
   Study · 完成弹窗 + 拼写反馈补丁
   ========================================================================= */

/* ---------- 完成弹窗 ---------- */

.study-finish-modal {
  max-width: 380px;
  padding: 32px 26px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 6px;
}

.study-finish-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(140deg, #fcbec3, #cfdee3);
  color: var(--rw-text-muted);
  font-size: 30px;
  font-weight: 700;
  margin-bottom: 10px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 6px 18px rgba(142, 101, 111, 0.2);
}

html[data-runwithme-theme="dark"]
  .study-finish-icon {
  background: linear-gradient(140deg, #70525b, #4d5a62);
  color: #fff2e9;
}

.study-finish-title {
  font-family: var(--rw-font-serif);
  font-size: 24px;
  font-weight: 600;
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"]
  .study-finish-title {
  color: #fff2e9;
}

.study-finish-desc {
  font-size: 13px;
  line-height: 1.6;
  opacity: 0.7;
  margin: 6px 0 22px;
  max-width: 260px;
}

.study-finish-actions {
  display: flex;
  gap: 10px;
  width: 100%;
}

.study-finish-continue,
.study-finish-later {
  flex: 1;
  padding: 13px 16px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.study-finish-continue {
  background: #8e656f;
  color: #fff2e9;
  box-shadow: 0 8px 18px rgba(142, 101, 111, 0.24);
}

.study-finish-continue:hover {
  transform: translateY(-1px);
}

.study-finish-continue:active {
  transform: scale(0.96);
}

.study-finish-later {
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
}

html[data-runwithme-theme="dark"]
  .study-finish-later {
  background: rgba(255, 255, 255, 0.06);
}

.study-finish-later:hover {
  background: rgba(142, 101, 111, 0.18);
}

.study-finish-later:active {
  transform: scale(0.96);
}

/* ---------- 拼写反馈补丁 ---------- */

.study-spell-feedback-correct {
  color: #4d9a4d;
  font-size: 16px;
}

html[data-runwithme-theme="dark"]
  .study-spell-feedback-correct {
  color: #8fdc8f;
}
/* =========================================================================
   Study · 连连看
   ========================================================================= */

.study-match-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 8px 20px 16px;
  overflow-y: auto;
}

.study-match-grid {
  width: 100%;
  max-width: 380px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.study-match-card {
  position: relative;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.85);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.75);
  color: var(--rw-text);
  font: inherit;
  text-align: center;
  cursor: pointer;
  word-break: break-word;
  overflow: hidden;
  box-shadow:
    0 4px 14px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease,
    opacity 0.35s ease;
  -webkit-tap-highlight-color: transparent;
}

html[data-runwithme-theme="dark"]
  .study-match-card {
  background: rgba(48, 42, 47, 0.75);
  border-color: rgba(255, 255, 255, 0.08);
  color: #fff2e9;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.study-match-card:hover:not(:disabled) {
  transform: translateY(-2px);
  background: rgba(255, 255, 255, 0.95);
}

html[data-runwithme-theme="dark"]
  .study-match-card:hover:not(:disabled) {
  background: rgba(60, 53, 59, 0.85);
}

.study-match-card:active:not(:disabled) {
  transform: scale(0.97);
}

/* 单词卡 */
.study-match-card-text {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.005em;
  line-height: 1.15;
}

/* 释义卡 */
.study-match-card-meaning {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.35;
  opacity: 0.9;
}

/* 选中 */
.study-match-card.is-selected {
  background: rgba(252, 190, 195, 0.45);
  border-color: rgba(142, 101, 111, 0.4);
  box-shadow:
    0 8px 20px rgba(142, 101, 111, 0.18),
    inset 0 0 0 1px rgba(142, 101, 111, 0.16);
}

html[data-runwithme-theme="dark"]
  .study-match-card.is-selected {
  background: rgba(252, 190, 195, 0.22);
  border-color: rgba(252, 190, 195, 0.4);
}

/* 匹配失败抖动 */
.study-match-card.is-wrong {
  background: rgba(224, 93, 93, 0.2);
  border-color: rgba(224, 93, 93, 0.55);
  animation: studyMatchShake 0.4s ease;
}

html[data-runwithme-theme="dark"]
  .study-match-card.is-wrong {
  background: rgba(224, 93, 93, 0.18);
  border-color: rgba(224, 93, 93, 0.5);
}

@keyframes studyMatchShake {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-4px);
  }
  75% {
    transform: translateX(4px);
  }
}

/* 匹配成功淡出 */
.study-match-card.is-fading {
  opacity: 0;
  transform: scale(0.85);
}

/* 已匹配：占位保持，视觉上消失 */
.study-match-card.is-matched {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
}

/* 底部统计 */
.study-match-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.55;
  font-variant-numeric: tabular-nums;
}

.study-match-wrong-count {
  padding: 3px 8px;
  border-radius: var(--rw-radius-pill);
  background: rgba(224, 93, 93, 0.15);
  color: #c94d4d;
  opacity: 0.9;
  letter-spacing: 0.04em;
}

html[data-runwithme-theme="dark"]
  .study-match-wrong-count {
  background: rgba(224, 93, 93, 0.2);
  color: #eb9090;
}
/* =========================================================================
   Study · 翻转卡片清理 + 统计面板
   ========================================================================= */

/* 移除已删除的播放按钮残留（如果有） */
.study-flip-play {
  display: none !important;
}

/* 卡片切换的淡入动画 */
.study-flip-front,
.study-flip-back {
  animation: studyFlipIn 0.25s ease;
}

/* ---------- 统计 ---------- */

.study-stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-bottom: 22px;
}

.study-stat-card {
  padding: 18px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 14px rgba(90, 60, 65, 0.05);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

html[data-runwithme-theme="dark"] .study-stat-card {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-stat-value {
  font-family: var(--rw-font-serif);
  font-size: 32px;
  font-weight: 600;
  line-height: 1;
  color: var(--rw-text);
  font-variant-numeric: tabular-nums;
}

html[data-runwithme-theme="dark"] .study-stat-value {
  color: #fff2e9;
}

.study-stat-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.55;
}

/* ---------- Section ---------- */

.study-stats-section {
  margin-bottom: 22px;
}

.study-stats-section-label {
  padding: 0 4px 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  opacity: 0.55;
}

/* ---------- 今日 ---------- */

.study-stats-today {
  padding: 14px 16px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

html[data-runwithme-theme="dark"] .study-stats-today {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-stats-today-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
}

.study-stats-today-row span {
  opacity: 0.6;
}

.study-stats-today-row strong {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ---------- 7 天柱状 ---------- */

.study-stats-chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 6px;
  padding: 16px 14px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.7);
  height: 160px;
}

html[data-runwithme-theme="dark"] .study-stats-chart {
  background: rgba(48, 42, 47, 0.5);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-stats-bar-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  height: 100%;
}

.study-stats-bar-value {
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--rw-text-muted);
  min-height: 12px;
}

html[data-runwithme-theme="dark"]
  .study-stats-bar-value {
  color: #d9bcc4;
}

.study-stats-bar {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  border-radius: 6px;
  background: rgba(142, 101, 111, 0.08);
  overflow: hidden;
  min-height: 0;
}

html[data-runwithme-theme="dark"] .study-stats-bar {
  background: rgba(255, 255, 255, 0.04);
}

.study-stats-bar-fill {
  width: 100%;
  background: linear-gradient(180deg, #fcbec3, #8e656f);
  border-radius: 6px;
  transition: height 0.4s ease;
  min-height: 2px;
}

.study-stats-bar-label {
  font-size: 10px;
  font-weight: 700;
  opacity: 0.55;
}

/* ---------- 词书进度 ---------- */

.study-stats-book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.study-stats-book-item {
  padding: 14px 16px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.75);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

html[data-runwithme-theme="dark"]
  .study-stats-book-item {
  background: rgba(48, 42, 47, 0.55);
  border-color: rgba(255, 255, 255, 0.06);
}

.study-stats-book-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.study-stats-book-head strong {
  font-size: 13px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.study-stats-book-head span {
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  opacity: 0.6;
}

.study-stats-book-bar {
  height: 6px;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.1);
  overflow: hidden;
}

html[data-runwithme-theme="dark"]
  .study-stats-book-bar {
  background: rgba(255, 255, 255, 0.06);
}

.study-stats-book-bar-fill {
  height: 100%;
  border-radius: var(--rw-radius-pill);
  background: linear-gradient(90deg, #fcbec3, #8e656f);
  transition: width 0.4s ease;
}

.study-stats-book-meta {
  font-size: 10px;
  opacity: 0.55;
}
/* =========================================================================
   恢复卡片正面播放按钮
   ========================================================================= */

.study-flip-play {
  display: flex !important;
}
/* =========================================================================
   Study · 错题集入口
   ========================================================================= */

.study-mistakes-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 22px;
  padding: 16px 18px;
  border-radius: 20px;
  background: linear-gradient(
    135deg,
    rgba(224, 93, 93, 0.12),
    rgba(252, 190, 195, 0.18)
  );
  border: 1px solid rgba(224, 93, 93, 0.18);
  box-shadow: 0 4px 14px rgba(90, 60, 65, 0.05);
}

html[data-runwithme-theme="dark"]
  .study-mistakes-entry {
  background: linear-gradient(
    135deg,
    rgba(224, 93, 93, 0.15),
    rgba(252, 190, 195, 0.08)
  );
  border-color: rgba(224, 93, 93, 0.25);
}

.study-mistakes-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.study-mistakes-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #c94d4d;
  opacity: 0.8;
}

html[data-runwithme-theme="dark"]
  .study-mistakes-label {
  color: #eb9090;
}

.study-mistakes-title {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 600;
  color: var(--rw-text);
  line-height: 1.1;
}

html[data-runwithme-theme="dark"]
  .study-mistakes-title {
  color: #fff2e9;
}

.study-mistakes-count {
  font-size: 11px;
  font-weight: 600;
  opacity: 0.7;
}

.study-mistakes-btn {
  flex-shrink: 0;
  padding: 10px 18px;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: #e05d5d;
  color: #fff2e9;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 14px rgba(224, 93, 93, 0.24);
  transition:
    transform 0.15s ease,
    background 0.15s ease;
}

.study-mistakes-btn:hover {
  transform: translateY(-1px);
  background: #eb7070;
}

.study-mistakes-btn:active {
  transform: scale(0.96);
}
/* =========================================================================
   Study · 每日一句
   ========================================================================= */

.study-daily {
  position: relative;
  padding: 24px 22px 22px;
  border-radius: var(--rw-radius-xl);
  background: linear-gradient(
    160deg,
    rgba(252, 190, 195, 0.32),
    rgba(207, 222, 227, 0.28)
  );
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow:
    0 8px 26px rgba(90, 60, 65, 0.07),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 22px;
}

html[data-runwithme-theme="dark"] .study-daily {
  background: linear-gradient(
    160deg,
    rgba(252, 190, 195, 0.12),
    rgba(207, 222, 227, 0.08)
  );
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow:
    0 8px 26px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.study-daily-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.study-daily-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--rw-text-muted);
  opacity: 0.7;
}

html[data-runwithme-theme="dark"]
  .study-daily-label {
  color: #fcbec3;
}

.study-daily-collect {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--rw-text-muted);
  font-size: 18px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.55;
  transition:
    opacity 0.15s ease,
    background 0.15s ease,
    transform 0.15s ease;
}

.study-daily-collect:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.1);
  transform: scale(1.06);
}

.study-daily-collect:active {
  transform: scale(0.92);
}

.study-daily-collect.is-collected {
  opacity: 1;
  color: #d4a24a;
}

html[data-runwithme-theme="dark"]
  .study-daily-collect.is-collected {
  color: #ffd47a;
}

.study-daily-text {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: 0.005em;
  color: #46323a;
  word-break: break-word;
  white-space: pre-wrap;
}

html[data-runwithme-theme="dark"]
  .study-daily-text {
  color: #fff2e9;
}

.study-daily-source {
  font-size: 13px;
  font-style: italic;
  opacity: 0.6;
  text-align: right;
  font-family: var(--rw-font-serif);
}
/* =========================================================================
   Study · 鼓励气泡 + 卡池编辑
   ========================================================================= */

.study-cheer-bubble {
  position: absolute;
  left: 50%;
  bottom: calc(150px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px 10px 10px;
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 248, 245, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow:
    0 14px 34px rgba(80, 50, 60, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  max-width: min(340px, calc(100% - 40px));
  cursor: pointer;
  animation: studyCheerIn 0.4s cubic-bezier(
    0.34,
    1.56,
    0.64,
    1
  );
}

html[data-runwithme-theme="dark"]
  .study-cheer-bubble {
  background: rgba(45, 40, 44, 0.96);
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

@keyframes studyCheerIn {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(12px)
      scale(0.9);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}

.study-cheer-bubble:active {
  transform: translateX(-50%) scale(0.97);
}

.study-cheer-avatar {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 14px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.45),
    0 2px 8px rgba(80, 50, 60, 0.15);
}

.study-cheer-avatar-levi {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.study-cheer-avatar-erwin {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.study-cheer-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.study-cheer-name {
  font-family: var(--rw-font-serif);
  font-size: 10px;
  font-style: italic;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(94, 70, 80, 0.6);
}

html[data-runwithme-theme="dark"]
  .study-cheer-name {
  color: rgba(255, 244, 239, 0.5);
}

.study-cheer-text {
  font-family: var(--rw-font-serif);
  font-size: 15px;
  font-weight: 500;
  line-height: 1.35;
  color: #46323a;
  word-break: break-word;
}

html[data-runwithme-theme="dark"]
  .study-cheer-text {
  color: #fff2e9;
}

/* ---------- 设置里的"管理卡池"按钮 ---------- */

.study-settings-manage-btn {
  margin-top: 10px;
  align-self: flex-start;
  padding: 8px 14px;
  border: 1px solid rgba(142, 101, 111, 0.2);
  border-radius: var(--rw-radius-pill);
  background: transparent;
  color: var(--rw-text-muted);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.study-settings-manage-btn:hover {
  background: rgba(252, 190, 195, 0.2);
  transform: translateY(-1px);
}

html[data-runwithme-theme="dark"]
  .study-settings-manage-btn {
  color: #f3dfe4;
  border-color: rgba(255, 255, 255, 0.15);
}

