.study-cheer-pool-modal {
  max-width: 480px;
}

.study-cheer-pool-hint {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.6;
  margin-bottom: 14px;
}

.study-cheer-pool-add {
