  justify-content: center;
}

.study-cheer-pool-empty {
  padding: 24px 12px;
  text-align: center;
  font-size: 12px;
  opacity: 0.5;
}
/* =========================================================================
   Study · Footer 左右布局
   ========================================================================= */

.study-modal-footer-split {
  justify-content: space-between !important;
}
/* =========================================================================
   Call Overlay · 顶栏缩小键
   ========================================================================= */

.call-overlay-topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 2;
