  padding: 12px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  color: inherit;
  font: inherit;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
  margin-bottom: 12px;
}

html[data-runwithme-theme="dark"]
  .q-choice-question-input {
  background: rgba(255, 255, 255, 0.06);
