/* ---------- ✦ 菜单 ---------- */

.q-spawn-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9200;
  background: rgba(0, 0, 0, 0.32);
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  padding: calc(env(safe-area-inset-top) + 70px) 18px
    18px;
  animation: qSpawnFade 0.2s ease;
}

@keyframes qSpawnFade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.q-spawn-menu {
  width: min(280px, 88vw);
  padding: 12px;
  border-radius: 20px;
  background: rgba(255, 248, 245, 0.98);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow:
    0 20px 50px rgba(60, 40, 45, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  animation: qSpawnIn 0.22s cubic-bezier(
    0.34,
    1.3,
    0.64,
    1
  );
}

html[data-runwithme-theme="dark"] .q-spawn-menu {
  background: rgba(33, 28, 32, 0.98);
  border-color: rgba(255, 255, 255, 0.08);
}

@keyframes qSpawnIn {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.q-spawn-label {
  padding: 2px 6px 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0.55;
}

.q-spawn-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 12px;
  border: 0;
  border-radius: 14px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease;
}

.q-spawn-item:hover {
  background: rgba(252, 190, 195, 0.22);
}

.q-spawn-item:active {
  transform: scale(0.98);
}

.q-spawn-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(252, 190, 195, 0.4);
  color: var(--rw-text-muted);
  font-size: 18px;
}

html[data-runwithme-theme="dark"] .q-spawn-icon {
  background: rgba(252, 190, 195, 0.18);
  color: #f3dfe4;
}

.q-spawn-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.q-spawn-info strong {
  font-size: 13px;
  font-weight: 700;
}

.q-spawn-info span {
  font-size: 11px;
  opacity: 0.6;
}

/* ---------- 准备中占位卡片 ---------- */

.q-post-preparing {
  opacity: 0.85;
  border-left: 3px solid #cfdee3;
}

.q-preparing-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0 8px;
}

.q-preparing-text {
  font-size: 13px;
  font-style: italic;
  opacity: 0.65;
}

.q-preparing-dots {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-bottom: 4px;
}

.q-preparing-dots span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8e656f;
  opacity: 0.35;
  animation: qPreparingDot 1.2s ease-in-out infinite;
}

.q-preparing-dots span:nth-child(2) {
  animation-delay: 0.15s;
}

.q-preparing-dots span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes qPreparingDot {
  0%,
  60%,
  100% {
    transform: translateY(0);
    opacity: 0.35;
  }
  30% {
    transform: translateY(-3px);
    opacity: 1;
  }
}

/* ---------- 可点击的选项 ---------- */

.q-option-clickable {
  border: 0;
