  border: 1px dashed rgba(142, 101, 111, 0.32);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.5);
  color: var(--rw-text-muted);
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.watch-file-label:hover {
  background: rgba(252, 190, 195, 0.2);
  border-color: rgba(252, 190, 195, 0.6);
}

.watch-file-label:active {
  transform: scale(0.98);
}

html[data-runwithme-theme="dark"]
  .watch-file-label {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.15);
  color: #f3dfe4;
}

.watch-file-input {
  position: absolute;
  left: 0;
  top: 0;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
}
/* =========================================================================
   Watch App · L3 播放器（本地 video + B 站 iframe + 全屏旋转兜底）
   ========================================================================= */

.watch-play-wrap {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/* ---------- 播放器容器 ---------- */

.watch-player {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 16px;
  overflow: hidden;
  background: #000;
  box-shadow: 0 8px 22px rgba(30, 20, 25, 0.18);
}

.watch-video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  background: #000;
}

/* ---------- 全屏 ---------- */

.watch-player.is-fullscreen {
  position: fixed;
  inset: 0;
  z-index: 9500;
  width: 100vw;
  height: 100vh;
  aspect-ratio: auto;
  border-radius: 0;
  box-shadow: none;
}

.watch-player.is-fullscreen.is-rotated {
  inset: auto;
  top: 50%;
  left: 50%;
  width: 100vh;
  height: 100vw;
  transform: translate(-50%, -50%) rotate(90deg);
  transform-origin: center center;
}

/* ---------- 控制条 ---------- */

.watch-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  background: rgba(20, 15, 20, 0.88);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.watch-player.is-fullscreen .watch-controls {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 14px 16px
    calc(18px + env(safe-area-inset-bottom));
  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85),
    rgba(0, 0, 0, 0.4) 60%,
    transparent
  );
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.watch-player.is-fullscreen
  .watch-controls.is-hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateY(8px);
}

/* 进度条 */

.watch-progress {
  width: 100%;
  height: 4px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  border-radius: var(--rw-radius-pill);
  outline: none;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.22);
}

.watch-progress::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--rw-bg);
  border: 0;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  cursor: pointer;
}

.watch-progress::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border: 0;
  border-radius: 50%;
  background: var(--rw-bg);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  cursor: pointer;
}

/* 底部控制行 */

.watch-controls-row {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff2e9;
}

.watch-ctrl-btn {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.watch-ctrl-btn:hover {
  background: rgba(255, 255, 255, 0.14);
}

.watch-ctrl-btn:active {
  transform: scale(0.94);
}

.watch-time {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  opacity: 0.85;
  white-space: nowrap;
}

.watch-time-sep {
  opacity: 0.5;
}

/* 音量 */

.watch-volume {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.watch-volume-slider {
  width: 72px;
  height: 3px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  border-radius: var(--rw-radius-pill);
  outline: none;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.24);
}

.watch-volume-slider::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--rw-bg);
  border: 0;
}

.watch-volume-slider::-moz-range-thumb {
  width: 11px;
  height: 11px;
  border: 0;
  border-radius: 50%;
  background: var(--rw-bg);
}

/* 倍速 */

.watch-rate-wrap {
  position: relative;
}

.watch-rate-btn {
  width: auto;
  min-width: 46px;
  padding: 0 10px;
  border-radius: var(--rw-radius-pill);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.watch-rate-menu {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border-radius: 12px;
  background: rgba(30, 22, 28, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
  min-width: 68px;
  animation: watchRateIn 0.16s ease;
}

@keyframes watchRateIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.watch-rate-option {
  padding: 7px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #fff2e9;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  text-align: center;
  transition: background 0.12s ease;
}

.watch-rate-option:hover {
  background: rgba(255, 255, 255, 0.1);
}

.watch-rate-option.active {
  background: #fcbec3;
  color: var(--rw-text-muted);
  font-weight: 700;
}

/* ---------- B 站 iframe ---------- */

.watch-bili-stage {
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 16px;
  overflow: hidden;
  background: #000;
  box-shadow: 0 8px 22px rgba(30, 20, 25, 0.18);
}

.watch-bili-iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
/* =========================================================================
   Watch App · L4 邀请流程
   ========================================================================= */

/* ---------- 邀请区域 ---------- */

.watch-invite-zone {
  margin-top: 4px;
}

/* 邀请按钮 */

.watch-invite-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 20px;
  border: 1px solid rgba(142, 101, 111, 0.2);
  border-radius: 16px;
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.28),
    rgba(207, 222, 227, 0.24)
  );
  color: var(--rw-text-muted);
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  box-shadow:
    0 4px 14px rgba(90, 60, 65, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.7);
  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease,
    border-color 0.15s ease;
}

.watch-invite-trigger:hover {
  transform: translateY(-1px);
  border-color: rgba(142, 101, 111, 0.35);
  box-shadow:
    0 10px 24px rgba(90, 60, 65, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.watch-invite-trigger:active {
  transform: scale(0.98);
}

html[data-runwithme-theme="dark"]
  .watch-invite-trigger {
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.12),
    rgba(207, 222, 227, 0.08)
  );
  color: #f3dfe4;
  border-color: rgba(255, 255, 255, 0.1);
}

.watch-invite-trigger-icon {
  font-size: 18px;
  line-height: 1;
}

/* ---------- 邀请状态条 ---------- */

.watch-invite-status {
  padding: 16px 18px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.78);
  box-shadow: 0 6px 18px rgba(90, 60, 65, 0.06);
  display: flex;
  flex-direction: column;
  gap: 12px;
  animation: watchInviteStatusIn 0.3s ease;
}

html[data-runwithme-theme="dark"]
  .watch-invite-status {
  background: rgba(48, 42, 47, 0.6);
  border-color: rgba(255, 255, 255, 0.06);
}

@keyframes watchInviteStatusIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.watch-invite-status-title {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rw-text-muted);
  opacity: 0.75;
}

html[data-runwithme-theme="dark"]
  .watch-invite-status-title {
  color: #fcbec3;
}

.watch-invite-status-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.watch-invite-status-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.06);
  transition: background 0.25s ease;
}

html[data-runwithme-theme="dark"]
  .watch-invite-status-row {
  background: rgba(255, 255, 255, 0.04);
}

.watch-invite-status-row.is-accepted {
  background: rgba(126, 209, 126, 0.18);
}

html[data-runwithme-theme="dark"]
  .watch-invite-status-row.is-accepted {
  background: rgba(126, 209, 126, 0.14);
}

.watch-invite-status-row.is-rejected {
  opacity: 0.65;
}

.watch-invite-status-avatar {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 13px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 2px 6px rgba(80, 50, 60, 0.1);
}

.watch-invite-status-row .watch-invite-status-avatar {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

/* 用 partner 对应的颜色 */
.watch-invite-status-row.is-pending
  .watch-invite-status-avatar {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.watch-invite-status-row.is-accepted
  .watch-invite-status-avatar {
  background: linear-gradient(140deg, #90dd90, #4d9a4d);
  color: #143c14;
}

.watch-invite-status-row.is-rejected
  .watch-invite-status-avatar {
  background: rgba(142, 101, 111, 0.35);
  color: rgba(255, 242, 233, 0.75);
}

.watch-invite-status-name {
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
}

.watch-invite-status-text {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  opacity: 0.7;
}

.watch-invite-status-row.is-accepted
  .watch-invite-status-text {
  color: #2d6f2d;
  opacity: 1;
  font-weight: 600;
}

html[data-runwithme-theme="dark"]
  .watch-invite-status-row.is-accepted
  .watch-invite-status-text {
  color: #8fdc8f;
}

/* pending 三点动画 */

.watch-invite-status-dots {
  display: flex;
  align-items: center;
  gap: 3px;
  padding-bottom: 3px;
  flex-shrink: 0;
}

.watch-invite-status-dots span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8e656f;
  opacity: 0.35;
  animation: watchInviteDot 1.2s ease-in-out infinite;
}

.watch-invite-status-dots span:nth-child(2) {
  animation-delay: 0.15s;
}

.watch-invite-status-dots span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes watchInviteDot {
  0%,
  60%,
  100% {
    transform: translateY(0);
    opacity: 0.35;
  }
  30% {
    transform: translateY(-3px);
    opacity: 1;
  }
}

/* 状态条底部动作 */

.watch-invite-status-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.watch-invite-action-btn {
  padding: 8px 16px;
  border: 1px solid rgba(142, 101, 111, 0.18);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.55);
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease,
    border-color 0.15s ease;
}

.watch-invite-action-btn:hover {
  background: rgba(252, 190, 195, 0.28);
  border-color: rgba(252, 190, 195, 0.6);
  transform: translateY(-1px);
}

.watch-invite-action-btn:active {
  transform: scale(0.96);
}

.watch-invite-action-btn.primary {
  background: #8e656f;
  color: #fff2e9;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(142, 101, 111, 0.24);
}

.watch-invite-action-btn.primary:hover {
  background: #7a545e;
}

html[data-runwithme-theme="dark"]
  .watch-invite-action-btn {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

html[data-runwithme-theme="dark"]
  .watch-invite-action-btn.primary {
  background: #fcbec3;
  color: var(--rw-text);
  border-color: transparent;
}

.watch-invite-accepted-hint {
  flex: 1;
  font-size: 11px;
  font-style: italic;
  opacity: 0.55;
  letter-spacing: 0.04em;
  text-align: right;
}

/* ---------- 邀请 Sheet ---------- */

.watch-invite-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9400;
  background: rgba(0, 0, 0, 0.42);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  animation: watchImportFade 0.2s ease;
}

.watch-invite-sheet {
  width: min(560px, 100%);
  display: flex;
  flex-direction: column;
  border-top-left-radius: 24px;
  border-top-right-radius: 24px;
  background: var(--rw-bg-elevated);
  color: var(--rw-text);
  padding: 8px 20px
    calc(20px + env(safe-area-inset-bottom));
  box-shadow: 0 -20px 50px rgba(60, 40, 45, 0.22);
  animation: watchImportSheetIn 0.28s cubic-bezier(
    0.34,
    1.2,
    0.64,
    1
  );
}

html[data-runwithme-theme="dark"]
  .watch-invite-sheet {
  background: #211c20;
  color: #fff2e9;
}

.watch-invite-sheet-title {
  font-family: var(--rw-font-serif);
  font-size: 22px;
  font-weight: 600;
  text-align: center;
  margin-bottom: 4px;
}

.watch-invite-sheet-sub {
  font-size: 11px;
  text-align: center;
  opacity: 0.55;
  margin-bottom: 16px;
}

.watch-invite-options {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.watch-invite-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 18px 8px 14px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.55);
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease;
}

.watch-invite-option:hover {
  transform: translateY(-2px);
  border-color: rgba(252, 190, 195, 0.6);
  background: rgba(252, 190, 195, 0.2);
}

.watch-invite-option:active {
  transform: scale(0.97);
}

html[data-runwithme-theme="dark"]
  .watch-invite-option {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.08);
}

.watch-invite-option-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 18px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 3px 10px rgba(80, 50, 60, 0.12);
}

.watch-invite-option-levi .watch-invite-option-avatar {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.watch-invite-option-erwin .watch-invite-option-avatar {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.watch-invite-option-both .watch-invite-option-avatar {
  background: linear-gradient(
    140deg,
    #b08a93 0%,
    #b08a93 49%,
    #b89aa0 51%,
    #b89aa0 100%
  );
  font-size: 13px;
}

.watch-invite-option-name {
  font-size: 13px;
  font-weight: 700;
}

.watch-invite-option-desc {
  font-size: 10px;
  opacity: 0.55;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
/* =========================================================================
   Watch App · L5 一起看聊天
   ========================================================================= */

/* ---------- 聊天模式下的滚动容器与布局 ---------- */

.watch-scroll.is-chat {
  display: flex;
  flex-direction: column;
  padding: 0 0 env(safe-area-inset-bottom) 0;
  overflow: hidden;
}

.watch-play-wrap.is-chat {
  display: flex;
  flex-direction: column;
  height: 100%;
  gap: 0;
}

.watch-play-wrap.is-chat .watch-player,
.watch-play-wrap.is-chat .watch-bili-stage {
  flex-shrink: 0;
  border-radius: 0;
  box-shadow: none;
  aspect-ratio: 16 / 9;
