/* ---------- 聊天容器 ---------- */

.watch-chat {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--rw-bg-elevated);
}

html[data-runwithme-theme="dark"] .watch-chat {
  background: #1a1518;
}

/* ---------- 聊天顶栏 ---------- */

.watch-chat-topbar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid rgba(142, 101, 111, 0.08);
  background: rgba(255, 248, 243, 0.95);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
