/* ---------- 消息区 ---------- */

.watch-chat-messages {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 14px 14px 10px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.watch-chat-system {
  align-self: center;
  padding: 5px 12px;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.1);
  color: var(--rw-text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

html[data-runwithme-theme="dark"] .watch-chat-system {
  background: rgba(255, 255, 255, 0.06);
  color: #d9bcc4;
}

/* 消息行 */

.watch-chat-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  max-width: 82%;
  animation: watchChatIn 0.25s ease;
}

@keyframes watchChatIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.watch-chat-row.is-you {
  align-self: flex-end;
  flex-direction: row-reverse;
}

.watch-chat-row.is-other {
  align-self: flex-start;
}

/* 头像 */

.watch-chat-avatar {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 13px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 2px 6px rgba(80, 50, 60, 0.12);
}

.watch-chat-avatar-levi {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.watch-chat-avatar-erwin {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

/* 气泡 */

.watch-chat-bubble-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.watch-chat-row.is-you .watch-chat-bubble-wrap {
  align-items: flex-end;
}

.watch-chat-name {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--rw-text-muted);
  opacity: 0.7;
  padding-left: 4px;
}

html[data-runwithme-theme="dark"] .watch-chat-name {
  color: #d9bcc4;
}

.watch-chat-bubble {
  display: inline-block;
  max-width: 100%;
  padding: 9px 13px;
  border-radius: 16px;
  font-size: 13px;
  line-height: 1.55;
  word-break: break-word;
  white-space: pre-wrap;
  background: rgba(142, 101, 111, 0.1);
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"] .watch-chat-bubble {
  background: rgba(255, 255, 255, 0.06);
  color: #fff2e9;
}

.watch-chat-row.is-other .watch-chat-bubble {
  border-bottom-left-radius: 5px;
}

.watch-chat-row.is-you .watch-chat-bubble {
  background: #fcbec3;
  color: var(--rw-text);
  border-bottom-right-radius: 5px;
}

html[data-runwithme-theme="dark"]
  .watch-chat-row.is-you
  .watch-chat-bubble {
  background: #8e656f;
  color: #fff2e9;
}

.watch-chat-meta {
  font-size: 9px;
  opacity: 0.4;
  padding: 0 4px;
  font-variant-numeric: tabular-nums;
}

/* 打字指示 */

.watch-chat-typing {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 12px 14px;
  min-width: 54px;
}

.watch-chat-typing span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8e656f;
  opacity: 0.5;
  animation: watchChatTyping 1.2s ease-in-out infinite;
}

html[data-runwithme-theme="dark"] .watch-chat-typing span {
  background: #d9bcc4;
}

.watch-chat-typing span:nth-child(2) {
  animation-delay: 0.15s;
}

.watch-chat-typing span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes watchChatTyping {
  0%,
  60%,
  100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  30% {
    transform: translateY(-3px);
    opacity: 1;
  }
}

/* ---------- 输入框 ---------- */

.watch-chat-composer {
  flex-shrink: 0;
  display: flex;
  gap: 8px;
  padding: 10px 14px 14px;
  border-top: 1px solid rgba(142, 101, 111, 0.08);
  background: rgba(255, 248, 243, 0.98);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

html[data-runwithme-theme="dark"] .watch-chat-composer {
  background: rgba(33, 28, 32, 0.98);
  border-top-color: rgba(255, 255, 255, 0.06);
}

.watch-chat-input {
  flex: 1;
  min-width: 0;
  padding: 11px 16px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: var(--rw-radius-pill);
  background: rgba(255, 255, 255, 0.75);
  color: inherit;
  font: inherit;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
}

html[data-runwithme-theme="dark"] .watch-chat-input {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
}

.watch-chat-input:focus {
  border-color: rgba(142, 101, 111, 0.42);
}

.watch-chat-input::placeholder {
  color: rgba(142, 101, 111, 0.42);
}

html[data-runwithme-theme="dark"]
  .watch-chat-input::placeholder {
  color: rgba(255, 244, 239, 0.32);
}

.watch-chat-send {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: #8e656f;
  color: #fff2e9;
  font-size: 18px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 14px rgba(142, 101, 111, 0.24);
  transition:
    transform 0.15s ease,
    background 0.15s ease,
    opacity 0.15s ease;
}

.watch-chat-send:hover:not(:disabled) {
  background: #7a545e;
  transform: translateY(-1px);
}

.watch-chat-send:active:not(:disabled) {
  transform: scale(0.94);
}

.watch-chat-send:disabled {
  opacity: 0.35;
  cursor: default;
  box-shadow: none;
}

html[data-runwithme-theme="dark"] .watch-chat-send {
  background: #fcbec3;
  color: var(--rw-text);
}

html[data-runwithme-theme="dark"]
  .watch-chat-send:hover:not(:disabled) {
  background: #ffd4d8;
}
/* =========================================================================
   Watch App · L6 一起看设置
   ========================================================================= */

/* ---------- 聊天顶栏齿轮按钮 ---------- */

.watch-chat-settings-btn {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.1);
  color: inherit;
  font-size: 15px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.75;
  transition:
    opacity 0.15s ease,
    background 0.15s ease,
    transform 0.2s ease;
}

.watch-chat-settings-btn:hover {
  opacity: 1;
  background: rgba(142, 101, 111, 0.2);
  transform: rotate(30deg);
}

.watch-chat-settings-btn:active {
  transform: rotate(30deg) scale(0.92);
}

html[data-runwithme-theme="dark"]
  .watch-chat-settings-btn {
  background: rgba(255, 255, 255, 0.08);
}

/* ---------- 设置行 ---------- */

.watch-settings-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  margin-bottom: 14px;
  border-radius: 14px;
  background: rgba(142, 101, 111, 0.06);
}

html[data-runwithme-theme="dark"] .watch-settings-row {
  background: rgba(255, 255, 255, 0.04);
}

.watch-settings-row-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.watch-settings-row-info strong {
  font-size: 14px;
  font-weight: 700;
}

.watch-settings-row-info small {
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.6;
}

/* ---------- 开关 ---------- */

.watch-settings-switch {
  position: relative;
  width: 46px;
  height: 26px;
  flex-shrink: 0;
  padding: 0;
  border: 0;
  border-radius: var(--rw-radius-pill);
  background: rgba(142, 101, 111, 0.2);
  cursor: pointer;
  transition: background 0.2s ease;
}

.watch-settings-switch span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--rw-bg);
  box-shadow: 0 2px 6px rgba(80, 50, 60, 0.2);
  transition: transform 0.22s cubic-bezier(
    0.34,
    1.2,
    0.64,
    1
  );
}

.watch-settings-switch.on {
  background: #fcbec3;
}

.watch-settings-switch.on span {
  transform: translateX(20px);
}

html[data-runwithme-theme="dark"]
  .watch-settings-switch {
  background: rgba(255, 255, 255, 0.1);
}

html[data-runwithme-theme="dark"]
  .watch-settings-switch.on {
  background: #fcbec3;
}
/* =========================================================================
   Watch App · L6.5 卡池编辑器
