/* =========================================================================
   iOS 文件上传统一修复
   =========================================================================
   关键：不用 zIndex: -1（会让 iOS 拒绝弹出选择器）
   用法：<label class="X" style="position: relative"> 里面放 <input class="ios-file-input" />
   ========================================================================= */

.ios-file-input {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  cursor: pointer !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  /* 不要 z-index，不要 pointer-events: none */
}

/* 已有的上传按钮 label 加相对定位 */
.chat-settings-btn {
  position: relative;
  overflow: hidden;
}

.chat-settings-avatar-actions label {
  position: relative;
  overflow: hidden;
}

/* Music 封面按钮（改成 label 后） */
.music-v2-panel-item-cover-btn {
  position: relative;
  overflow: hidden;
}

/* Music 音频文件上传（新样式） */
.music-upload-file-label {
  position: relative;
  overflow: hidden;
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
}

.music-upload-file-value {
  flex: 1;
  min-width: 0;
  padding: 6px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.7);
  font-size: 12px;
  color: inherit;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

html[data-runwithme-theme="dark"] .music-upload-file-value {
  background: rgba(255, 255, 255, 0.06);
}
/* =========================================================================
   Chat 长按修复 · iOS
   ========================================================================= */

.chat-message-longpress-target {
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
}
/* Chat 图片上传 input（不要 zIndex: -1，iOS 会拒绝弹出选择器） */
.chat-image-input-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
  border: 0;
  padding: 0;
  margin: 0;
}
/* =========================================================================
   修复 · Chat 长按菜单被后续消息遮挡
   content-visibility: auto 会创建独立 stacking context，
   导致 menu 的 z-index 无法跨越兄弟行比较。
   给选中行强制可见 + 高 z-index。
   ========================================================================= */

.chat-page .chat-messages > .message-row.message-selected,
.chat-page .chat-messages > .chat-pat-row.message-selected {
  content-visibility: visible;
  position: relative;
  z-index: 200;
}
/* =========================================================================
   iOS 文件上传修复 v2 · 屏幕外隐藏
   -------------------------------------------------------------------------
   适用于"用 ref.click() 手动触发"的场景。
   不要铺满父容器（否则会拦截父容器内所有点击）。
   ========================================================================= */

.ios-file-input-detached {
  position: fixed !important;
  left: -9999px !important;
  top: 0 !important;
  width: 1px !important;
  height: 1px !important;
  opacity: 0 !important;
  overflow: hidden !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
}
