/* =========================================================================
   Photos · Liquid Glass System
   -------------------------------------------------------------------------
   A 方案的示范 App。所有交互元素用同一套玻璃语言。
   颜色不动，只换材质。
   ========================================================================= */

/* ---------- 0. 通用玻璃 token（本 App 专用） ---------- */

.photos-app,
.photo-viewer,
.photo-cat-backdrop,
.photo-picker-backdrop,
.photo-naming-backdrop {
  --lg-bg: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.58) 0%,
    rgba(255, 255, 255, 0.3) 48%,
    rgba(255, 255, 255, 0.46) 100%
  );
  --lg-bg-strong: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.78) 0%,
    rgba(255, 255, 255, 0.5) 48%,
    rgba(255, 255, 255, 0.66) 100%
  );
  --lg-border: rgba(255, 255, 255, 0.6);
  --lg-shadow:
    0 14px 34px rgba(90, 60, 65, 0.12),
    0 3px 10px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.05);
  --lg-blur: blur(28px) saturate(1.8);
}

html[data-runwithme-theme="dark"] .photos-app,
html[data-runwithme-theme="dark"] .photo-viewer,
html[data-runwithme-theme="dark"] .photo-cat-backdrop,
html[data-runwithme-theme="dark"] .photo-picker-backdrop,
html[data-runwithme-theme="dark"] .photo-naming-backdrop {
  --lg-bg: linear-gradient(
    135deg,
    rgba(70, 60, 68, 0.7) 0%,
    rgba(45, 40, 44, 0.55) 48%,
    rgba(60, 50, 58, 0.62) 100%
  );
  --lg-bg-strong: linear-gradient(
    135deg,
    rgba(80, 68, 78, 0.85) 0%,
    rgba(50, 44, 50, 0.72) 48%,
    rgba(65, 55, 64, 0.78) 100%
  );
  --lg-border: rgba(255, 255, 255, 0.14);
  --lg-shadow:
    0 14px 34px rgba(0, 0, 0, 0.45),
    0 3px 10px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.3);
}

/* ---------- 1. Header（升级已有的玻璃） ---------- */

.photos-app-header {
  background: var(--lg-bg);
  border-bottom: 1px solid var(--lg-border);
  backdrop-filter: var(--lg-blur);
  -webkit-backdrop-filter: var(--lg-blur);
  box-shadow:
    0 6px 24px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba(0, 0, 0, 0.03);
}

/* ---------- 2. 顶栏按钮（back / ☰ / ＋） ---------- */

.photos-app-back,
.photos-app-upload {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.68),
    rgba(255, 255, 255, 0.36)
  );
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow:
    0 4px 12px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px) saturate(1.6);
  -webkit-backdrop-filter: blur(20px) saturate(1.6);
  transition:
    transform 0.16s ease,
    background 0.16s ease,
    box-shadow 0.16s ease;
}

.photos-app-back:hover,
.photos-app-upload:hover:not(:disabled) {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.85),
    rgba(255, 255, 255, 0.55)
  );
  box-shadow:
    0 6px 18px rgba(90, 60, 65, 0.12),
