/* =========================================================================
   iOS26 拟态玻璃 · 全 App 顶栏底栏统一
   -------------------------------------------------------------------------
   只改材质（background / border / backdrop-filter / box-shadow），
   不改任何布局属性（padding / height / width / gap）。
   ========================================================================= */

:root {
  --ios-glass-bg: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(255, 255, 255, 0.46) 48%,
    rgba(255, 255, 255, 0.58) 100%
  );
  --ios-glass-border: rgba(255, 255, 255, 0.72);
  --ios-glass-shadow:
    0 6px 22px rgba(90, 60, 65, 0.07),
    0 2px 6px rgba(90, 60, 65, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.025);
  --ios-glass-blur: blur(26px) saturate(1.9);
}

html[data-runwithme-theme="dark"] {
  --ios-glass-bg: linear-gradient(
    135deg,
    rgba(70, 60, 68, 0.74) 0%,
    rgba(44, 38, 44, 0.6) 48%,
    rgba(60, 50, 58, 0.68) 100%
  );
  --ios-glass-border: rgba(255, 255, 255, 0.12);
  --ios-glass-shadow:
    0 6px 22px rgba(0, 0, 0, 0.42),
    0 2px 6px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    inset 0 -1px 0 rgba(0, 0, 0, 0.3);
}

