    inset 0 -1px 0 rgba(0, 0, 0, 0.045),
    inset 0 0 0 1px rgba(255, 255, 255, 0.45);
}

.chat-dark .message-bubble {
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.35),
