/* 通话气泡 / 语音气泡也同步 */
.chat-page .chat-call-bubble,
.chat-page .chat-voice-bubble {
  box-shadow:
    0 6px 18px rgba(90, 60, 65, 0.08),
    0 2px 6px rgba(90, 60, 65, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 0 0 1px rgba(255, 255, 255, 0.4);
}

.chat-dark .chat-call-bubble,
.chat-dark .chat-voice-bubble {
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.35),
    0 2px 6px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 0 0 1px rgba(255, 255, 255, 0.06);
}

/* =========================================================================
   2. 输入区（Chat composer）
   ========================================================================= */

.chat-page .chat-composer {
  background: var(--cg-bg);
  border-top: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur);
  -webkit-backdrop-filter: var(--cg-blur);
  box-shadow:
    0 -10px 30px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.chat-dark .chat-composer {
  box-shadow:
    0 -10px 30px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.chat-page .chat-input-container {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: blur(20px) saturate(1.7);
  -webkit-backdrop-filter: blur(20px) saturate(1.7);
  box-shadow:
    0 6px 18px rgba(90, 60, 65, 0.08),
    0 2px 6px rgba(90, 60, 65, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.04);
}

.chat-dark .chat-input-container {
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.35),
    0 2px 6px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* 发送键 —— 品牌色玻璃 */
.chat-page .composer-send {
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.95) 0%,
    rgba(240, 169, 175, 0.85) 100%
  );
  color: #8e656f;
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    0 8px 20px rgba(252, 190, 195, 0.4),
    0 2px 6px rgba(252, 190, 195, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(14px) saturate(1.6);
  -webkit-backdrop-filter: blur(14px) saturate(1.6);
}

.chat-dark .chat-page .composer-send,
.chat-page.chat-dark .composer-send {
  background: linear-gradient(
    135deg,
    rgba(142, 101, 111, 0.9) 0%,
    rgba(122, 84, 94, 0.8) 100%
  );
  color: #fff2e9;
  border-color: rgba(255, 255, 255, 0.18);
  box-shadow:
    0 8px 20px rgba(142, 101, 111, 0.45),
    0 2px 6px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

/* 加号 / 表情 / 卡片 —— 次要按钮玻璃 */
.chat-page .composer-plus,
.chat-page .composer-card,
.chat-page .composer-sticker {
  background: transparent;
  color: var(--rw-icon-muted, #8e656f);
  transition:
    background 0.15s ease,
    color 0.15s ease,
    transform 0.15s ease;
}

.chat-page .composer-plus:hover,
.chat-page .composer-card:hover,
.chat-page .composer-sticker:hover {
  background: rgba(255, 255, 255, 0.55);
  color: var(--rw-icon, #4f3940);
}

.chat-dark .chat-page .composer-plus:hover,
.chat-dark .chat-page .composer-card:hover,
.chat-dark .chat-page .composer-sticker:hover {
  background: rgba(255, 255, 255, 0.1);
}

/* =========================================================================
   3. 加号面板
   ========================================================================= */

.chat-page .chat-plus-menu {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur-strong);
  -webkit-backdrop-filter: var(--cg-blur-strong);
