   ========================================================================= */

.chat-page .chat-message-context .chat-message-actions {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur-strong);
  -webkit-backdrop-filter: var(--cg-blur-strong);
  box-shadow: var(--cg-shadow);
}

.chat-dark .chat-page .chat-message-context .chat-message-actions {
  background: var(--cg-bg-strong);
}

.chat-page .chat-message-actions button:hover {
  background: rgba(255, 255, 255, 0.55);
}

.chat-dark .chat-page .chat-message-actions button:hover {
  background: rgba(255, 255, 255, 0.08);
}

/* =========================================================================
   5. 通话选择器
   ========================================================================= */

.chat-page .chat-call-picker {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur-strong);
  -webkit-backdrop-filter: var(--cg-blur-strong);
  box-shadow: var(--cg-shadow);
}

.chat-page .chat-call-picker-cancel {
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
