  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    0 3px 8px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

/* =========================================================================
   7. 表情包面板
   ========================================================================= */

.chat-page .chat-sticker-panel {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur);
  -webkit-backdrop-filter: var(--cg-blur);
  box-shadow: var(--cg-shadow);
}

.chat-page .chat-sticker-item:active {
  background: rgba(255, 255, 255, 0.55);
}

/* =========================================================================
   8. Chat 设置面板
   ========================================================================= */

.chat-page .chat-settings-backdrop {
  background: rgba(30, 22, 28, 0.45);
  backdrop-filter: blur(10px) saturate(1.4);
  -webkit-backdrop-filter: blur(10px) saturate(1.4);
}

.chat-page .chat-settings-panel {
  background: var(--cg-bg-strong);
  border: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur-strong);
  -webkit-backdrop-filter: var(--cg-blur-strong);
  box-shadow:
    0 25px 70px rgba(60, 40, 45, 0.28),
    0 6px 18px rgba(60, 40, 45, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.chat-page .chat-settings-close {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.7) 0%,
    rgba(255, 255, 255, 0.45) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    0 3px 10px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

/* 主按钮 —— 品牌色玻璃 */
.chat-page .chat-settings-btn {
  background: linear-gradient(
    135deg,
    rgba(142, 101, 111, 0.94) 0%,
    rgba(122, 84, 94, 0.82) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.35);
  box-shadow:
    0 8px 20px rgba(142, 101, 111, 0.3),
    0 2px 6px rgba(142, 101, 111, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

/* 次按钮玻璃 */
.chat-page .chat-settings-btn.ghost {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.7) 0%,
    rgba(255, 255, 255, 0.45) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.6);
  color: #5e4650;
  box-shadow:
    0 4px 12px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.chat-dark .chat-page .chat-settings-btn.ghost {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.1) 0%,
    rgba(255, 255, 255, 0.04) 100%
  );
  border-color: rgba(255, 255, 255, 0.12);
  color: #d9bcc4;
}

/* 危险按钮 —— 红色玻璃 */
.chat-page .chat-settings-btn.small.danger {
  background: linear-gradient(
    135deg,
    rgba(224, 93, 93, 0.28) 0%,
    rgba(224, 93, 93, 0.18) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.35);
  color: #c94d4d;
  box-shadow:
    0 6px 16px rgba(224, 93, 93, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

/* 设置里的卡片 */
.chat-page .chat-settings-avatar-item,
.chat-page .chat-settings-storage,
.chat-page .chat-settings-notif,
.chat-page .chat-settings-sticker {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.6) 0%,
    rgba(255, 255, 255, 0.35) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow:
    0 4px 14px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
}

.chat-dark .chat-page .chat-settings-avatar-item,
.chat-dark .chat-page .chat-settings-storage,
.chat-dark .chat-page .chat-settings-notif,
.chat-dark .chat-page .chat-settings-sticker {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.08) 0%,
    rgba(255, 255, 255, 0.03) 100%
  );
  border-color: rgba(255, 255, 255, 0.08);
}

/* 输入框 */
.chat-page .chat-settings-name-row input,
.chat-page .chat-settings-num input,
.chat-page .chat-settings-pat-label textarea,
.chat-page .chat-settings-css-textarea,
.chat-page .chat-settings-sticker-btns button {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(255, 255, 255, 0.5) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    0 2px 6px rgba(90, 60, 65, 0.04);
}

.chat-dark .chat-page .chat-settings-name-row input,
.chat-dark .chat-page .chat-settings-num input,
.chat-dark .chat-page .chat-settings-pat-label textarea,
.chat-dark .chat-page .chat-settings-css-textarea,
.chat-dark .chat-page .chat-settings-sticker-btns button {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.08) 0%,
    rgba(255, 255, 255, 0.03) 100%
  );
  border-color: rgba(255, 255, 255, 0.1);
}

/* =========================================================================
   9. 多选操作条
   ========================================================================= */

.chat-page .chat-selection-bar {
  background: var(--cg-bg);
  border-top: 1px solid var(--cg-border);
  backdrop-filter: var(--cg-blur);
  -webkit-backdrop-filter: var(--cg-blur);
  box-shadow:
    0 -10px 30px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.chat-dark .chat-page .chat-selection-bar {
  box-shadow:
    0 -10px 30px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.chat-page .chat-selection-cancel {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.7) 0%,
    rgba(255, 255, 255, 0.45) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.6);
  color: #5e4650;
  box-shadow:
    0 6px 16px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.chat-dark .chat-page .chat-selection-cancel {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.1) 0%,
    rgba(255, 255, 255, 0.04) 100%
  );
  border-color: rgba(255, 255, 255, 0.12);
  color: #d9bcc4;
}

/* 删除按钮 —— 红色玻璃 */
.chat-page .chat-selection-delete {
  background: linear-gradient(
    135deg,
    rgba(224, 93, 93, 0.94) 0%,
    rgba(201, 77, 77, 0.82) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.35);
  color: #fff2e9;
  box-shadow:
    0 8px 20px rgba(224, 93, 93, 0.35),
    0 2px 6px rgba(224, 93, 93, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

/* =========================================================================
   10. 顶栏保留（已经是 iOS26 玻璃，不重写）
   ========================================================================= */

/* =========================================================================
   11. 与 lucide 图标的联动（图标颜色跟随）
   ========================================================================= */

.chat-page .telegram-back,
.chat-page .theme-button,
.chat-page .telegram-more,
.chat-page .composer-plus,
.chat-page .composer-card,
.chat-page .composer-sticker {
  color: var(--rw-icon-muted, #8e656f);
}

.chat-page .telegram-back:hover,
.chat-page .theme-button:hover,
.chat-page .telegram-more:hover {
  color: var(--rw-icon, #4f3940);
}

.chat-dark .chat-page .telegram-back,
.chat-dark .chat-page .theme-button,
.chat-dark .chat-page .telegram-more {
  color: #d9bcc4;
}

.chat-dark .chat-page .telegram-back:hover,
.chat-dark .chat-page .theme-button:hover,
.chat-dark .chat-page .telegram-more:hover {
  color: #fff2e9;
}
/* =========================================================================
   Chat · Lucide 图标 + 已送达标记 + 尾巴变量化
   ========================================================================= */

/* ---------- 顶栏按钮里的图标 ---------- */

.chat-page .telegram-back svg,
.chat-page .telegram-more svg,
.chat-page .theme-button svg {
  display: block;
  flex-shrink: 0;
}

/* ---------- composer 图标 ---------- */

.chat-page .composer-plus svg,
.chat-page .composer-card svg,
.chat-page .composer-sticker svg,
.chat-page .composer-send svg {
  display: block;
  flex-shrink: 0;
}

/* ---------- 加号面板图标 ---------- */

.chat-page .chat-plus-menu span svg {
  display: block;
  flex-shrink: 0;
  color: var(--rw-icon-muted, #8e656f);
}

.chat-dark .chat-page .chat-plus-menu span svg {
  color: #f3dfe4;
}

/* ---------- 语音播放键图标 ---------- */

.chat-page .chat-voice-play svg {
  display: block;
  flex-shrink: 0;
}

/* ---------- 通话气泡图标 ---------- */

.chat-page .chat-call-icon svg {
  display: block;
  flex-shrink: 0;
  color: var(--rw-icon-muted, #8e656f);
}

.chat-dark .chat-page .chat-call-icon svg {
  color: #d9bcc4;
}

/* ---------- 选择勾图标 ---------- */

.chat-page .chat-pick-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
}

.chat-page .chat-pick-indicator svg {
  display: block;
  flex-shrink: 0;
}

/* ---------- 引用预览关闭按钮 ---------- */

.chat-page .chat-quote-preview-close {
  display: flex;
  align-items: center;
  justify-content: center;
}

.chat-page .chat-quote-preview-close svg {
  display: block;
  flex-shrink: 0;
}

/* =========================================================================
   已送达 / 时间 标记
   ========================================================================= */

.chat-page .message-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 3px;
  min-height: 11px;
  padding: 0 4px;
}

.chat-page .message-you .message-meta {
  justify-content: flex-end;
}

.chat-page .message-time {
  font-size: 9px;
  color: var(--chat-muted);
  opacity: 0.52;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}

.chat-page .message-status {
  font-size: 9px;
  font-weight: 600;
  color: var(--chat-muted);
  opacity: 0.55;
  letter-spacing: 0.02em;
}

/* =========================================================================
   气泡尾巴 · 颜色变量化（跟随气泡）
   ========================================================================= */

.chat-page .message-bubble {
  --bubble-bg: var(--chat-bubble-other);
}

.chat-page .message-you .message-bubble {
  --bubble-bg: var(--chat-bubble-you);
}

.chat-page .message-other.message-group-end .message-bubble::after {
  background: var(--bubble-bg);
}

.chat-page .message-you.message-group-end .message-bubble::after {
  background: var(--bubble-bg);
}

/* 深色模式下同样跟随 */
.chat-dark .message-bubble {
  --bubble-bg: var(--chat-bubble-other);
}

.chat-dark .message-you .message-bubble {
  --bubble-bg: var(--chat-bubble-you);
}

/* =========================================================================
   composer-send 圆形按钮 + 图标居中
   ========================================================================= */

.chat-page .composer-send {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =========================================================================
   composer-plus 图标颜色跟随
   ========================================================================= */

.chat-page .composer-plus,
.chat-page .composer-sticker,
.chat-page .composer-card {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 表情面板激活态下图标颜色 */
.chat-page .composer-sticker.active {
  color: var(--rw-icon, #4f3940);
}

/* =========================================================================
   通话 / 语音 / 加号面板图标 hover 颜色
   ========================================================================= */

.chat-page .composer-plus:hover,
.chat-page .composer-sticker:hover,
.chat-page .composer-card:hover {
  color: var(--rw-icon, #4f3940);
}

.chat-dark .chat-page .composer-plus:hover,
.chat-dark .chat-page .composer-sticker:hover,
.chat-dark .chat-page .composer-card:hover {
  color: #fff2e9;
}

/* =========================================================================
   顶栏图标按钮的 hover / active 反馈（有 svg 时不要 font-size 撑大）
   ========================================================================= */

.chat-page .telegram-back,
.chat-page .telegram-more {
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
/* =========================================================================
