    inset 0 -1px 0 rgba(0, 0, 0, 0.04);
  --mg-shadow-soft:
    0 8px 22px rgba(90, 60, 65, 0.1),
    0 2px 6px rgba(90, 60, 65, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
