  -webkit-backdrop-filter: blur(16px) saturate(1.6);
}

.letter-fab:hover {
  transform: translateY(-2px) scale(1.04);
  box-shadow:
    0 18px 38px rgba(142, 101, 111, 0.5),
    0 6px 14px rgba(142, 101, 111, 0.28),
