html[data-runwithme-theme="dark"] .notes-list-empty-icon {
  color: #d9bcc4;
}
/* =========================================================================
   Letter · Tabs 视觉修复（覆盖上一轮）
   -------------------------------------------------------------------------
   思路：未选中也给一层极淡白玻璃，active 是"亮一档"而不是"从无到有"。
   ========================================================================= */

.letter-tabs {
  background: transparent !important;
  border-bottom: 1px solid rgba(142, 101, 111, 0.06) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
}

html[data-runwithme-theme="dark"] .letter-tabs {
  border-bottom-color: rgba(255, 255, 255, 0.05) !important;
}

/* 未选中 tab：极淡白玻璃 */
.letter-tab {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.34) 0%,
    rgba(255, 255, 255, 0.18) 100%
  ) !important;
  border: 1px solid rgba(255, 255, 255, 0.42) !important;
  box-shadow:
    0 2px 6px rgba(90, 60, 65, 0.03),
    inset 0 1px 0 rgba(255, 255, 255, 0.7) !important;
  backdrop-filter: blur(14px) saturate(1.5) !important;
  -webkit-backdrop-filter: blur(14px) saturate(1.5) !important;
  color: rgba(94, 70, 80, 0.72) !important;
}

.letter-tab:hover:not(.active) {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.5) 0%,
    rgba(255, 255, 255, 0.3) 100%
  ) !important;
  color: #5e4650 !important;
}

/* 选中 tab：白亮一档，柔和不抢戏 */
.letter-tab.active {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.85) 0%,
    rgba(255, 255, 255, 0.62) 100%
  ) !important;
  border-color: rgba(255, 255, 255, 0.85) !important;
  color: #5e4650 !important;
  box-shadow:
    0 4px 12px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 1) !important;
}

html[data-runwithme-theme="dark"] .letter-tab {
  background: linear-gradient(
    145deg,
    rgba(80, 68, 78, 0.4) 0%,
    rgba(50, 44, 50, 0.28) 100%
  ) !important;
  border-color: rgba(255, 255, 255, 0.08) !important;
  color: rgba(217, 188, 196, 0.7) !important;
}

html[data-runwithme-theme="dark"]
  .letter-tab:hover:not(.active) {
  background: linear-gradient(
    145deg,
    rgba(100, 86, 96, 0.55) 0%,
    rgba(60, 52, 60, 0.42) 100%
  ) !important;
  color: #fff2e9 !important;
}

html[data-runwithme-theme="dark"] .letter-tab.active {
  background: linear-gradient(
    145deg,
    rgba(252, 190, 195, 0.55) 0%,
    rgba(252, 190, 195, 0.35) 100%
  ) !important;
  border-color: rgba(255, 255, 255, 0.16) !important;
  color: #4f3940 !important;
}
