}

/* ---------- 纪念日列表项 ---------- */

.calendar-anniv-item {
  background: var(--cg-bg) !important;
  border: 1px solid var(--cg-border) !important;
  backdrop-filter: var(--cg-blur) !important;
  -webkit-backdrop-filter: var(--cg-blur) !important;
