}

.calendar-anniv-action.danger:hover {
  background: rgba(224, 93, 93, 0.15) !important;
  color: #c94d4d !important;
}

html[data-runwithme-theme="dark"]
  .calendar-anniv-action {
  color: #d9bcc4 !important;
}

/* ---------- Modal ---------- */

.calendar-modal-backdrop {
  background: rgba(30, 22, 28, 0.45) !important;
  backdrop-filter: blur(10px) saturate(1.4) !important;
  -webkit-backdrop-filter: blur(10px) saturate(1.4) !important;
}

.calendar-modal {
  background: var(--cg-bg-strong) !important;
