}

.calendar-btn.ghost {
  background: var(--cg-bg) !important;
  border: 1px solid var(--cg-border) !important;
  color: var(--rw-icon-muted, #8e656f) !important;
  box-shadow: var(--cg-shadow-soft) !important;
}

.calendar-btn.ghost:hover:not(:disabled) {
  background: var(--cg-bg-strong) !important;
  color: var(--rw-icon, #4f3940) !important;
}

html[data-runwithme-theme="dark"]
  .calendar-btn.ghost {
  color: #d9bcc4 !important;
}
/* =========================================================================
   Check-in · Liquid Glass
   ========================================================================= */

.checkin-app {
  --ckg-bg: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.62) 0%,
    rgba(255, 255, 255, 0.32) 48%,
    rgba(255, 255, 255, 0.48) 100%
  );
  --ckg-bg-strong: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.82) 0%,
    rgba(255, 255, 255, 0.55) 48%,
    rgba(255, 255, 255, 0.72) 100%
  );
  --ckg-border: rgba(255, 255, 255, 0.68);
  --ckg-shadow:
    0 14px 34px rgba(90, 60, 65, 0.12),
    0 3px 10px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.04);
  --ckg-shadow-soft:
    0 8px 22px rgba(90, 60, 65, 0.08),
    0 2px 6px rgba(90, 60, 65, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  --ckg-blur: blur(28px) saturate(1.8);
  --ckg-blur-strong: blur(34px) saturate(1.9);
}

html[data-runwithme-theme="dark"] .checkin-app {
  --ckg-bg: linear-gradient(
