    rgba(60, 50, 58, 0.66) 100%
  );
  --ckg-bg-strong: linear-gradient(
    135deg,
    rgba(84, 72, 82, 0.86) 0%,
    rgba(52, 46, 52, 0.72) 48%,
    rgba(68, 58, 66, 0.8) 100%
  );
  --ckg-border: rgba(255, 255, 255, 0.14);
  --ckg-shadow:
    0 14px 34px rgba(0, 0, 0, 0.45),
    0 3px 10px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.3);
  --ckg-shadow-soft:
    0 8px 22px rgba(0, 0, 0, 0.35),
    0 2px 6px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

/* ---------- 顶栏按钮 ---------- */

.checkin-back,
.checkin-icon-btn,
.checkin-add-btn {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.checkin-back {
  background: transparent !important;
  color: var(--rw-icon-muted, #8e656f);
}

.checkin-back:hover {
  background: rgba(142, 101, 111, 0.1) !important;
  color: var(--rw-icon, #4f3940);
}

.checkin-icon-btn {
  background: var(--ckg-bg) !important;
  border: 1px solid var(--ckg-border) !important;
  color: var(--rw-icon-muted, #8e656f) !important;
  box-shadow: var(--ckg-shadow-soft) !important;
  backdrop-filter: var(--ckg-blur) !important;
  -webkit-backdrop-filter: var(--ckg-blur) !important;
}

.checkin-icon-btn:hover {
  background: var(--ckg-bg-strong) !important;
  color: var(--rw-icon, #4f3940) !important;
  transform: translateY(-1px);
}

.checkin-add-btn {
  background: linear-gradient(
    135deg,
    rgba(142, 101, 111, 0.94) 0%,
    rgba(122, 84, 94, 0.82) 100%
  ) !important;
  border: 1px solid rgba(255, 255, 255, 0.35) !important;
  color: #fff2e9 !important;
  box-shadow:
    0 8px 20px rgba(142, 101, 111, 0.3),
    0 2px 6px rgba(142, 101, 111, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.2) !important;
}

.checkin-add-btn:hover {
  transform: translateY(-1px);
