/* =========================================================================
   Studio · Liquid Glass
   ========================================================================= */

.studio-home,
.studio-page {
  --stg-bg: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.62) 0%,
    rgba(255, 255, 255, 0.32) 48%,
    rgba(255, 255, 255, 0.48) 100%
  );
  --stg-bg-strong: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.82) 0%,
    rgba(255, 255, 255, 0.55) 48%,
    rgba(255, 255, 255, 0.72) 100%
  );
  --stg-border: rgba(255, 255, 255, 0.68);
  --stg-shadow:
    0 14px 34px rgba(90, 60, 65, 0.12),
    0 3px 10px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.04);
  --stg-shadow-soft:
    0 8px 22px rgba(90, 60, 65, 0.08),
    0 2px 6px rgba(90, 60, 65, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  --stg-blur: blur(28px) saturate(1.8);
}

html[data-runwithme-theme="dark"] .studio-home,
html[data-runwithme-theme="dark"] .studio-page {
  --stg-bg: linear-gradient(
    135deg,
    rgba(72, 62, 70, 0.72) 0%,
    rgba(44, 38, 44, 0.58) 48%,
    rgba(60, 50, 58, 0.66) 100%
  );
  --stg-bg-strong: linear-gradient(
    135deg,
    rgba(84, 72, 82, 0.86) 0%,
    rgba(52, 46, 52, 0.72) 48%,
    rgba(68, 58, 66, 0.8) 100%
  );
  --stg-border: rgba(255, 255, 255, 0.14);
}

/* ---------- Studio Home 导航卡 ---------- */

.studio-nav-card {
  background: var(--stg-bg) !important;
  border: 1px solid var(--stg-border) !important;
  backdrop-filter: var(--stg-blur) !important;
  -webkit-backdrop-filter: var(--stg-blur) !important;
  box-shadow: var(--stg-shadow-soft) !important;
  transition:
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease !important;
}

.studio-nav-card:hover {
  background: var(--stg-bg-strong) !important;
  box-shadow: var(--stg-shadow) !important;
}

.studio-nav-icon {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.studio-nav-arrow {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* ---------- 顶栏按钮 ---------- */

.studio-back-link {
