  align-items: center !important;
  gap: 6px !important;
  background: var(--stg-bg) !important;
  border: 1px solid var(--stg-border) !important;
  backdrop-filter: blur(16px) saturate(1.6) !important;
  -webkit-backdrop-filter: blur(16px) saturate(1.6) !important;
  box-shadow: var(--stg-shadow-soft) !important;
  transition:
    background 0.15s ease,
    transform 0.15s ease !important;
}

.studio-back-link:hover {
  background: var(--stg-bg-strong) !important;
  transform: translateY(-1px);
}

.studio-back-link svg {
