/* =========================================================================
   Chat · iMessage 扁平气泡（最终版）
   -------------------------------------------------------------------------
   干掉所有伪元素尾巴；用 iMessage 的"最后一条小圆角"方案。
   放在文件最末尾 —— 同 !important 下后写赢，覆盖 Macaron / Dark / Mono。
   ========================================================================= */

.chat-page .message-bubble,
.chat-page .message-you .message-bubble,
.chat-dark .message-bubble,
.chat-dark .message-you .message-bubble,
.chat-page.chat-dark .message-bubble,
.chat-page.chat-dark .message-you .message-bubble,
html[data-runwithme-style="mono"] .chat-page .message-bubble,
html[data-runwithme-style="mono"] .chat-page .message-you .message-bubble,
html[data-runwithme-style="mono"][data-runwithme-theme="dark"] .chat-page .message-bubble,
html[data-runwithme-style="mono"][data-runwithme-theme="dark"] .chat-page .message-you .message-bubble {
  border: none !important;
  box-shadow: none !important;
  border-radius: 20px !important;
  padding: 8px 12px !important;
}

/* 干掉所有尾巴伪元素 */
.chat-page .message-bubble::after,
.chat-page .message-other .message-bubble::after,
.chat-page .message-you .message-bubble::after,
.chat-page .message-other.message-group-end .message-bubble::after,
.chat-page .message-you.message-group-end .message-bubble::after,
.chat-page .message-bubble::before {
  display: none !important;
  content: none !important;
}

/* 最后一条消息：小圆角当尾巴 */
.chat-page .message-other.message-group-end .message-bubble {
  border-bottom-left-radius: 6px !important;
}
.chat-page .message-you.message-group-end .message-bubble {
  border-bottom-right-radius: 6px !important;
}

/* 语音 / 通话气泡同样扁平 */
.chat-page .chat-call-bubble,
.chat-page .chat-voice-bubble,
.chat-dark .chat-call-bubble,
.chat-dark .chat-voice-bubble {
  border: none !important;
  box-shadow: none !important;
}

.chat-page .chat-voice-play {
  box-shadow: none !important;
}

/* =========================================================================
   Home · Widget 多尺寸
   ========================================================================= */

.home-grid-item.size-1x1 {
  grid-column: span 1;
  grid-row: span 1;
  aspect-ratio: 1 / 1;
}

.home-grid-item.size-2x2,
.home-grid-item.is-large {
  grid-column: span 2;
  grid-row: span 2;
  aspect-ratio: 1 / 1;
}

.home-grid-item.size-4x2 {
  grid-column: span 4;
  grid-row: span 2;
  aspect-ratio: 2 / 1;
}

.home-grid-item.size-2x4 {
  grid-column: span 2;
  grid-row: span 4;
  aspect-ratio: 1 / 2;
}

.home-grid-item.size-4x4 {
  grid-column: span 4;
  grid-row: span 4;
  aspect-ratio: 1 / 1;
}

/* =========================================================================
   Home · Music Widget v2 · 播放器风格
   ========================================================================= */

.music-widget {
  container-type: size;
  container-name: music-widget;

  width: 100%;
  height: 100%;
  padding: 11px 12px 9px;
  border-radius: 22px;
  box-sizing: border-box;

  /* 液态玻璃 */
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.62) 0%,
    rgba(255, 255, 255, 0.28) 48%,
    rgba(255, 255, 255, 0.46) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(28px) saturate(1.8);
  -webkit-backdrop-filter: blur(28px) saturate(1.8);
  box-shadow:
    0 14px 34px rgba(90, 60, 65, 0.14),
    0 3px 10px rgba(90, 60, 65, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(0, 0, 0, 0.04);

  display: flex;
  flex-direction: column;
  gap: 3px;
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}

.music-widget:active {
  transform: scale(0.98);
}

html[data-runwithme-theme="dark"] .music-widget {
  background: linear-gradient(
    135deg,
    rgba(72, 62, 70, 0.78) 0%,
    rgba(44, 38, 44, 0.6) 48%,
    rgba(60, 50, 58, 0.72) 100%
  );
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.5),
    0 3px 10px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 0 rgba(0, 0, 0, 0.3);
}

/* ---------- 头像组 ---------- */

.music-widget-avatars {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3%;
  padding: 4px 0 2px;
}

.music-widget-avatar {
  width: clamp(30px, 28cqw, 52px);
  height: clamp(30px, 28cqw, 52px);
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;

  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: clamp(11px, 10cqw, 20px);
  font-weight: 700;
  letter-spacing: 0.01em;

  /* 立体阴影 + 白色描边 */
  box-shadow:
    0 6px 14px rgba(80, 50, 60, 0.22),
    0 2px 5px rgba(80, 50, 60, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.35),
    0 0 0 1.5px rgba(255, 255, 255, 0.85);
}

.music-widget-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.music-widget-avatar-you {
  background: linear-gradient(140deg, #ffd4d8, #fcbec3);
  color: #8e656f;
}

.music-widget-avatar-levi {
  background: linear-gradient(140deg, #a37b84, #8e656f);
}

.music-widget-avatar-erwin {
