/* =========================================================================
   Home · 信封 Widget
   ========================================================================= */

.letter-widget-v2 {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8%;
  box-sizing: border-box;
}

.letter-widget-v2-envelope {
  position: relative;
  width: 100%;
  height: 100%;
  max-width: 100%;
  border-radius: 6px;

  /* 信封主体：白色 + 渐变模拟纸张 */
  background: linear-gradient(
    160deg,
    #ffffff 0%,
    #f7f3ee 100%
  );
  border: 1px solid rgba(0, 0, 0, 0.06);

  /* 阴影塑形成信封 */
  box-shadow:
    0 8px 20px rgba(80, 50, 60, 0.18),
    0 2px 5px rgba(80, 50, 60, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -2px 6px rgba(0, 0, 0, 0.04);

  overflow: hidden;
}

/* 信封底部的折线（模拟封口） */
.letter-widget-v2-envelope::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  bottom: -1px;
  height: 55%;
  background: linear-gradient(
    160deg,
    #f9f5f0 0%,
    #eee9e2 100%
  );
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
  border-top: 1px solid rgba(0, 0, 0, 0.04);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  pointer-events: none;
}

/* 信封翻盖（顶部倒三角） */
.letter-widget-v2-flap {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 62%;
  background: linear-gradient(
    175deg,
    #ffffff 0%,
    #f3efe9 100%
  );
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba(80, 50, 60, 0.06);
  pointer-events: none;
}

/* 右下角：来信人 */
.letter-widget-v2-from {
  position: absolute;
  right: 8%;
  bottom: 8%;
  z-index: 2;

  display: inline-flex;
  align-items: center;
  gap: 4px;

  padding: 3px 9px;
  border-radius: 999px;

  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.85),
    rgba(255, 255, 255, 0.55)
  );
  border: 1px solid rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px) saturate(1.6);
  -webkit-backdrop-filter: blur(10px) saturate(1.6);
  box-shadow:
    0 3px 8px rgba(80, 50, 60, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 1);

  font-size: 10px;
  font-weight: 700;
  color: #4f3940;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.letter-widget-v2-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #d34d5f;
  box-shadow: 0 0 0 2px rgba(211, 77, 95, 0.18);
  animation: letterWidgetPulse 1.6s ease-in-out infinite;
}

@keyframes letterWidgetPulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(0.85);
    opacity: 0.6;
  }
}

.letter-widget-v2-idle {
  opacity: 0.55;
  font-weight: 600;
}

