/* =========================================================================
   iOS file input · 最终修复
   -------------------------------------------------------------------------
   1. 彻底干掉任何 pointer-events: none 的覆盖
   2. label 模式用 .ios-file-input（铺满父容器）
   3. ref 模式用 .ios-file-input-detached（屏幕右下角 1x1）
   ========================================================================= */

/* ---------- label 模式（推荐） ---------- */

.ios-file-input {
  position: absolute !important;
  /* ★ 关键：向外扩展命中区，兜底 zoom 引起的错位 */
  inset: -40px !important;
  width: auto !important;
  height: auto !important;
  opacity: 0 !important;
  cursor: pointer !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  transform: none !important;
  font-size: 16px !important; /* 阻止 iOS 自动缩放 input */
  line-height: 1 !important;
  -webkit-appearance: none;
  appearance: none;
  pointer-events: auto !important;
  z-index: 2 !important;
}

/* label 容器需要 relative + overflow hidden */
.home-add-widget-file-btn,
.music-upload-file-label,
.watch-file-label,
.studio-sticker-upload,
.hs-upload-thumb,
.photos-upload-btn {
  position: relative !important;
  overflow: visible !important;
}

/* ---------- ref 模式（兼容保留） ---------- */

.ios-file-input-detached {
  position: fixed !important;
  bottom: 0 !important;
  right: 0 !important;
  top: auto !important;
  left: auto !important;
  width: 1px !important;
  height: 1px !important;
  opacity: 0 !important;
  overflow: hidden !important;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  /* 不写 pointer-events: none ！ */
  pointer-events: auto !important;
}

/* ---------- 全站兜底：任何隐藏 file input 都不允许 pointer-events: none ---------- */

input[type="file"].ios-file-input,
input[type="file"].ios-file-input-detached,
input[type="file"].hs-hidden-input,
input[type="file"].chat-image-input-hidden {
  pointer-events: auto !important;
}
