html[data-runwithme-style="mono"] .calendar-app,
html[data-runwithme-style="mono"] .music-app-v2 {
  background: var(--rw-mono-app-bg) !important;
}

/* Letter：用柔和版（原来底偏纸感） */
html[data-runwithme-style="mono"] .letter-app {
  background: var(--rw-mono-app-bg-soft) !important;
}

/* Chat：只在没自定义背景时覆盖，不要盖掉用户的背景图 */
html[data-runwithme-style="mono"]
  .chat-page:not(.chat-has-custom-bg) {
  background: var(--rw-mono-app-bg-soft) !important;
}

/* Studio 三个页面 */
