  [class*="-btn"],
html[data-runwithme-style="mono"]
  [class*="-button"],
html[data-runwithme-style="mono"]
  [class*="-tab"],
html[data-runwithme-style="mono"]
  [class*="-tab"].active,
html[data-runwithme-style="mono"]
  [class*="-filter"],
html[data-runwithme-style="mono"]
  [class*="-pill"],
html[data-runwithme-style="mono"]
  [class*="-card"],
html[data-runwithme-style="mono"]
  [class*="-panel"]:not([class*="backdrop"]),
html[data-runwithme-style="mono"]
  [class*="-modal"]:not([class*="backdrop"]),
html[data-runwithme-style="mono"]
  [class*="-sheet"]:not([class*="backdrop"]),
html[data-runwithme-style="mono"]
  [class*="-header"],
html[data-runwithme-style="mono"]
  [class*="-composer"],
html[data-runwithme-style="mono"]
  [class*="-trigger"],
html[data-runwithme-style="mono"]
  [class*="-status"]:not([class*="-status-text"]):not([class*="-status-label"]):not([class*="-status-name"]),
html[data-runwithme-style="mono"]
