html[data-runwithme-style="mono"]
  [class*="-input"],
html[data-runwithme-style="mono"]
  [class*="-select"],
html[data-runwithme-style="mono"]
  [class*="dock"]:not([class*="dock-menu"]):not([class*="dock-tab"]):not([class*="dock-post-slot"]):not([class*="dock-icon"]),
html[data-runwithme-style="mono"]
