   ========================================================= */

/* 1. 让 opds-root 正确占满父容器（原来用 height: 100% 在 flex 环境里会算错） */
.read-picker-source-panel {
  min-height: 0;
}

.opds-root {
  flex: 1;
  min-height: 0;
}

/* 2. 条目禁止被压缩，超出交给滚动 */
.opds-content {
  flex: 1;
  min-height: 0;
}

.opds-content > * {
  flex-shrink: 0;
}

/* 3. 顺手优化：条目在移动端更紧凑 */
.opds-entry {
  flex-shrink: 0;
}

.opds-entry-summary {
  -webkit-line-clamp: 2;
}
/* =========================================================
   Step 7B · Read 横向分页
   ========================================================= */

.read-reader-pad {
  position: absolute;
  inset: 0;
  padding: 52px 22px 84px;
  padding-top: 52px;
  padding-bottom: 84px;
  box-sizing: border-box;
  display: flex;
}

.read-reader-scroll-h {
  flex: 1;
  height: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  position: relative;
}

.read-reader-scroll-h::-webkit-scrollbar {
  display: none;
}

.read-reader-pages {
  height: 100%;
  box-sizing: border-box;
  column-fill: auto;
  column-gap: 0;
  /* column-width 由 JS 设置 */
}

.read-reader-page-label {
  opacity: 0.6;
  font-size: 10px;
  margin-left: 2px;
}
/* =========================================================
   Step 7C · 高亮 / 笔记
   ========================================================= */

/* 默认 = user 粉色（无 data 属性时的兜底） */
.read-hl {
  background: rgba(252, 190, 195, 0.55);
  color: inherit;
  border-radius: 3px;
  padding: 0 1px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.read-hl:active {
  background: rgba(252, 190, 195, 0.95);
}

/* ---- 按 author 分色 ---- */

/* user = 粉 */
.read-hl[data-hl-author="user"] {
  background: rgba(252, 190, 195, 0.55);
}
.read-hl[data-hl-author="user"]:active {
  background: rgba(252, 190, 195, 0.95);
}

/* Levi = 绿 */
.read-hl[data-hl-author="levi"] {
  background: rgba(160, 215, 175, 0.55);
}
.read-hl[data-hl-author="levi"]:active {
  background: rgba(160, 215, 175, 0.95);
}

/* Erwin = 蓝 */
.read-hl[data-hl-author="erwin"] {
  background: rgba(160, 195, 230, 0.55);
}
.read-hl[data-hl-author="erwin"]:active {
  background: rgba(160, 195, 230, 0.95);
}

/* 有笔记的 → 加一层下划线，颜色沿用 author */
.read-hl-note {
  border-bottom: 1px dotted rgba(142, 101, 111, 0.5);
}

/* 夜间主题下高亮稍微提亮一点，防止看不清 */
.read-reader[data-bg="night"] .read-hl[data-hl-author="user"] {
  background: rgba(252, 190, 195, 0.4);
}
.read-reader[data-bg="night"] .read-hl[data-hl-author="levi"] {
  background: rgba(160, 215, 175, 0.4);
}
.read-reader[data-bg="night"] .read-hl[data-hl-author="erwin"] {
  background: rgba(160, 195, 230, 0.4);
}

/* -------- 浮动菜单 -------- */

.hl-menu {
  position: fixed;
  z-index: 200;
  display: flex;
  gap: 4px;
  padding: 6px;
  background: rgba(255, 252, 248, 0.98);
  backdrop-filter: blur(20px) saturate(1.5);
  -webkit-backdrop-filter: blur(20px) saturate(1.5);
  border: 1px solid rgba(255, 255, 255, 0.85);
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(142, 101, 111, 0.28);
