/* =========================================================
   Read · 一起读 / 随机划线
   ========================================================= */

/* ---------- 一起读状态栏 ---------- */

.read-together-bar {
  position: absolute;
  top: 52px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px 5px 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(20px) saturate(1.5);
  -webkit-backdrop-filter: blur(20px) saturate(1.5);
  border: 1px solid rgba(255, 255, 255, 0.75);
  box-shadow: 0 4px 14px rgba(142, 101, 111, 0.14);
  animation: read-together-in 0.28s ease-out;
}

@keyframes read-together-in {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

.read-together-avatars {
  display: flex;
  align-items: center;
}

.read-together-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 11px;
  font-weight: 700;
  border: 2px solid #fff;
  box-shadow: 0 2px 6px rgba(80, 50, 60, 0.15);
  margin-left: -8px;
}

.read-together-avatar:first-child {
  margin-left: 0;
}

.read-together-avatar.avatar-levi {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.read-together-avatar.avatar-erwin {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.read-together-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.read-together-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #8e656f;
}

.read-together-exit {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.12);
  color: #8e656f;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.read-together-exit:active {
  background: rgba(142, 101, 111, 0.24);
}

/* 顶栏"一起读"按钮激活态 */

.read-reader-icon-btn.is-together {
  color: #8e656f;
  background: rgba(252, 190, 195, 0.35);
}

/* ---------- 邀请弹窗 ---------- */

.read-invite-backdrop {
  position: absolute;
  inset: 0;
  z-index: 220;
  background: rgba(60, 40, 48, 0.4);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.read-invite-sheet {
  width: 100%;
  max-width: 440px;
  background: rgba(255, 252, 248, 0.98);
  border-radius: 22px 22px 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow: 0 -10px 40px rgba(142, 101, 111, 0.22);
  padding: 8px 20px 28px;
  animation: read-invite-in 0.24s ease-out;
}

@keyframes read-invite-in {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}

.read-invite-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0 12px;
}

.read-invite-header h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #664f54;
}

.read-invite-header button {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 50%;
  background: rgba(252, 190, 195, 0.4);
  color: #8e656f;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.read-invite-hint {
  margin: 0 0 16px;
  font-size: 12px;
  line-height: 1.6;
  color: #a58a90;
  text-align: center;
}

.read-invite-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 18px;
}

.read-invite-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px 8px 12px;
  border: 1px solid rgba(142, 101, 111, 0.14);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.7);
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    transform 0.15s ease;
  -webkit-tap-highlight-color: transparent;
}

.read-invite-option:active {
  transform: scale(0.97);
}

.read-invite-option.is-on {
  background: rgba(252, 190, 195, 0.22);
  border-color: rgba(252, 190, 195, 0.85);
}

.read-invite-option-avatar {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 20px;
  font-weight: 700;
  background: linear-gradient(140deg, #b08a93, #8e656f);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 3px 10px rgba(80, 50, 60, 0.12);
}

.read-invite-option-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.read-invite-option:nth-child(2) .read-invite-option-avatar {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.read-invite-option-name {
  font-size: 13px;
  font-weight: 700;
  color: #664f54;
}

.read-invite-option-status {
  font-size: 10px;
  color: #a58a90;
  letter-spacing: 0.04em;
}

.read-invite-option.is-on .read-invite-option-status {
  color: #b05360;
}

.read-invite-footer {
  display: flex;
  gap: 8px;
}

.read-invite-btn {
  flex: 1;
  padding: 12px 16px;
  border: none;
  border-radius: 12px;
  background: rgba(252, 190, 195, 0.75);
  color: #664f54;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.read-invite-btn:active {
  transform: scale(0.97);
}

.read-invite-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.read-invite-btn.ghost {
  background: rgba(207, 222, 227, 0.55);
  color: #8e656f;
}

/* ---------- 高亮颜色（按 author 分） ---------- */

/* 兜底：默认和 user 一样粉 */
.read-hl {
  background: rgba(252, 190, 195, 0.55);
  color: inherit;
  border-radius: 3px;
  padding: 0 1px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.read-hl[data-hl-author="user"] {
  background: rgba(252, 190, 195, 0.55);
}

/* Levi 绿 */
.read-hl[data-hl-author="levi"] {
  background: rgba(160, 215, 175, 0.55);
}

/* Erwin 蓝 */
.read-hl[data-hl-author="erwin"] {
  background: rgba(160, 195, 230, 0.55);
}

.read-hl:active {
  filter: brightness(0.94);
}

.read-hl-note {
  border-bottom: 1px dotted rgba(142, 101, 111, 0.5);
}

/* 夜间模式下稍微提亮 */
.read-reader[data-bg="night"] .read-hl[data-hl-author="user"] {
  background: rgba(252, 190, 195, 0.4);
}
.read-reader[data-bg="night"] .read-hl[data-hl-author="levi"] {
  background: rgba(160, 215, 175, 0.4);
}
.read-reader[data-bg="night"] .read-hl[data-hl-author="erwin"] {
  background: rgba(160, 195, 230, 0.4);
}

/* ---------- HighlightDetail 里的作者标签 ---------- */

.hl-detail-author {
  display: inline-block;
  margin-right: 6px;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  vertical-align: middle;
}

.hl-detail-author-levi {
  background: rgba(160, 215, 175, 0.5);
  color: #3c6e4a;
}

.hl-detail-author-erwin {
  background: rgba(160, 195, 230, 0.5);
  color: #355a80;
}

/* ---------- 一起读邀请/结束 toast ---------- */

.read-reader-toast {
  position: absolute;
  left: 50%;
  bottom: 96px;
  transform: translateX(-50%);
  z-index: 230;
  padding: 10px 18px;
  border-radius: 999px;
  background: rgba(255, 252, 248, 0.96);
  color: #664f54;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  box-shadow: 0 10px 30px rgba(142, 101, 111, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.9);
  animation: read-toast-in 0.28s ease-out;
  pointer-events: none;
  max-width: 84%;
  text-align: center;
}

@keyframes read-toast-in {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}
/* =========================================================
   Read · 邀请中状态 + 高亮 tab + 系统邀请
   ========================================================= */

/* ---------- 邀请中：每个被邀请者的状态条 ---------- */

.read-invite-statuses {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 18px;
}

.read-invite-status {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(142, 101, 111, 0.12);
}

.read-invite-status-avatar {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff2e9;
  font-family: var(--rw-font-serif);
  font-size: 15px;
  font-weight: 700;
  background: linear-gradient(140deg, #b08a93, #8e656f);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.read-invite-status:nth-child(2) .read-invite-status-avatar {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.read-invite-status-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.read-invite-status-name {
  flex: 1;
  font-size: 13px;
  font-weight: 700;
  color: #664f54;
}

.read-invite-status-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

.read-invite-status-state.state-pending {
  background: rgba(207, 222, 227, 0.55);
  color: #536a72;
}

.read-invite-status-state.state-accepted {
  background: rgba(160, 215, 175, 0.5);
  color: #2d6f2d;
}

.read-invite-status-state.state-rejected {
  background: rgba(142, 101, 111, 0.12);
  color: #8e656f;
  opacity: 0.8;
}

.read-invite-spin {
  animation: read-invite-spin-anim 1s linear infinite;
}

@keyframes read-invite-spin-anim {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* ---------- 高亮抽屉 tabs ---------- */

.hl-drawer-tabs {
  flex-shrink: 0;
  display: flex;
  gap: 4px;
  padding: 4px 12px 10px;
  overflow-x: auto;
  scrollbar-width: none;
}

.hl-drawer-tabs::-webkit-scrollbar {
  display: none;
}

.hl-drawer-tab {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.5);
  color: #8e656f;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.hl-drawer-tab:active {
  transform: scale(0.97);
}

.hl-drawer-tab.active {
  background: rgba(255, 255, 255, 0.95);
  border-color: rgba(255, 255, 255, 0.9);
  color: #4f3940;
}

.hl-drawer-tab-levi.active {
  background: rgba(160, 215, 175, 0.5);
  border-color: rgba(160, 215, 175, 0.85);
  color: #2d5a3a;
}

.hl-drawer-tab-erwin.active {
