/* ---------- 全屏浮层遮罩 ---------- */

.fridge-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(30, 22, 28, 0.42);
  backdrop-filter: blur(8px) saturate(1.4);
  -webkit-backdrop-filter: blur(8px) saturate(1.4);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fridge-modal-fade 0.22s ease;
}

@keyframes fridge-modal-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ---------- 冰箱贴选择器（modal） ---------- */

.fridge-door-picker {
  position: relative !important;
  inset: auto !important;
  width: min(460px, 100%);
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  padding: 18px 18px 16px;
  border-radius: 22px;

  background: rgba(255, 250, 245, 0.76) !important;
  border: 1px solid rgba(255, 255, 255, 0.72) !important;
  backdrop-filter: blur(36px) saturate(1.9);
  -webkit-backdrop-filter: blur(36px) saturate(1.9);
  box-shadow:
    0 25px 70px rgba(60, 40, 45, 0.3),
    0 6px 18px rgba(60, 40, 45, 0.12),
