  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.08);
  font-size: 11px;
  color: rgba(60, 45, 40, 0.75);
  flex-shrink: 0;
}

.notes-diary-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.notes-diary-avatar.is-user {
  background: rgba(0, 0, 0, 0.14);
  color: rgba(60, 45, 40, 0.85);
}

html[data-runwithme-theme="dark"] .notes-diary-avatar {
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 244, 239, 0.8);
}

html[data-runwithme-theme="dark"] .notes-diary-avatar.is-user {
  background: rgba(255, 255, 255, 0.18);
  color: rgba(255, 244, 239, 0.9);
}

.notes-diary-author-name {
  font-size: 13px;
  color: #3a2f2a;
  font-weight: 600;
}

html[data-runwithme-theme="dark"] .notes-diary-author-name {
  color: #fff2e9;
}

.notes-diary-time {
  margin-left: auto;
  font-size: 11px;
  color: rgba(60, 45, 40, 0.45);
}

html[data-runwithme-theme="dark"] .notes-diary-time {
  color: rgba(255, 244, 239, 0.45);
}

.notes-diary-mood-tag {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.08);
  color: rgba(60, 45, 40, 0.75);
}

html[data-runwithme-theme="dark"] .notes-diary-mood-tag {
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 244, 239, 0.8);
}

/* ---------- Diary 编辑器 ---------- */
.notes-diary-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.notes-diary-author-row {
  display: flex;
  align-items: center;
