}
.notes-pool-modal .notes-modal-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
/* =========================================================
   A3 · 划线评价系统
   ========================================================= */

/* ---------- 日记正文：只读视图 ---------- */

.notes-diary-view-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.notes-diary-edit-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.notes-diary-view {
  flex: 1;
  min-height: 240px;
  overflow-y: auto;
  padding: 4px 0;
  font-size: 15px;
