}

/* ---------- 高亮底 ---------- */

.diary-hl {
  border-radius: 3px;
  padding: 0 1px;
  cursor: pointer;
  transition: filter 0.15s ease;
  -webkit-tap-highlight-color: transparent;
}

.diary-hl-user {
  background: rgba(252, 190, 195, 0.55);
}
.diary-hl-levi {
  background: rgba(160, 215, 175, 0.55);
}
.diary-hl-erwin {
  background: rgba(160, 195, 230, 0.55);
}

.diary-hl:active {
  filter: brightness(0.94);
}

html[data-runwithme-theme="dark"] .diary-hl-user {
  background: rgba(252, 190, 195, 0.35);
}
html[data-runwithme-theme="dark"] .diary-hl-levi {
  background: rgba(160, 215, 175, 0.35);
}
html[data-runwithme-theme="dark"] .diary-hl-erwin {
  background: rgba(160, 195, 230, 0.35);
}

/* ---------- 评价尾巴 ---------- */

.diary-hl-tail {
  display: block;
  margin: 4px 0 8px 6px;
  padding-left: 8px;
  border-left: 2px solid currentColor;
  font-size: 12px;
  font-style: italic;
  line-height: 1.5;
  opacity: 0.75;
}

.diary-hl-tail-user {
  color: #8e656f;
  border-left-color: rgba(252, 190, 195, 0.85);
}
.diary-hl-tail-levi {
  color: #4d7a56;
  border-left-color: rgba(160, 215, 175, 0.85);
}
.diary-hl-tail-erwin {
  color: #4a6d94;
  border-left-color: rgba(160, 195, 230, 0.85);
}

html[data-runwithme-theme="dark"] .diary-hl-tail-user {
  color: #d9bcc4;
}
html[data-runwithme-theme="dark"] .diary-hl-tail-levi {
  color: #a8d8b4;
}
html[data-runwithme-theme="dark"] .diary-hl-tail-erwin {
  color: #b3cde0;
}

/* ---------- 浮动菜单 ---------- */

.diary-hl-menu-backdrop {
  position: fixed;
  inset: 0;
  z-index: 99;
  background: transparent;
}

.diary-hl-menu {
  position: fixed;
  transform: translate(-50%, -100%);
  margin-top: -8px;
  z-index: 100;
  display: flex;
  gap: 2px;
  padding: 6px;
  border-radius: 14px;
  background: rgba(255, 250, 245, 0.98);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow:
    0 14px 36px rgba(90, 60, 65, 0.24),
    0 3px 8px rgba(90, 60, 65, 0.1);
  backdrop-filter: blur(20px) saturate(1.6);
  -webkit-backdrop-filter: blur(20px) saturate(1.6);
  animation: diaryHlMenuIn 0.16s ease;
}

@keyframes diaryHlMenuIn {
  from {
    opacity: 0;
    transform: translate(-50%, calc(-100% + 4px))
      scale(0.94);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -100%) scale(1);
  }
}

.diary-hl-menu-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 8px 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #4f3940;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.15s ease;
}

.diary-hl-menu-btn:active {
  background: rgba(252, 190, 195, 0.4);
}

html[data-runwithme-theme="dark"] .diary-hl-menu {
  background: rgba(30, 26, 30, 0.98);
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.5),
    0 3px 8px rgba(0, 0, 0, 0.3);
}

html[data-runwithme-theme="dark"] .diary-hl-menu-btn {
  color: #fff2e9;
}

html[data-runwithme-theme="dark"]
  .diary-hl-menu-btn:active {
  background: rgba(255, 255, 255, 0.08);
}

/* ---------- 评价 Sheet ---------- */

.diary-hl-sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 150;
  background: rgba(30, 22, 28, 0.42);
  backdrop-filter: blur(8px) saturate(1.4);
  -webkit-backdrop-filter: blur(8px) saturate(1.4);
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.diary-hl-sheet {
  width: 100%;
  max-width: 520px;
  padding: 20px 20px calc(20px + env(safe-area-inset-bottom));
  border-radius: 22px 22px 0 0;
  background: rgba(255, 252, 248, 0.98);
  border-top: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow: 0 -12px 40px rgba(60, 40, 45, 0.24);
  backdrop-filter: blur(24px) saturate(1.6);
  -webkit-backdrop-filter: blur(24px) saturate(1.6);
  animation: diaryHlSheetIn 0.24s cubic-bezier(0.34, 1.2, 0.64, 1);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@keyframes diaryHlSheetIn {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}

.diary-hl-sheet h3 {
  margin: 0;
  font-family: var(--rw-font-serif);
  font-size: 20px;
  font-weight: 600;
  color: #4f3940;
}

.diary-hl-quote {
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(252, 190, 195, 0.22);
  color: #8e656f;
  font-size: 13px;
  line-height: 1.6;
  max-height: 100px;
  overflow-y: auto;
  word-break: break-word;
}

.diary-hl-input {
  width: 100%;
  min-height: 72px;
  padding: 12px 14px;
  border: 1px solid rgba(142, 101, 111, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.9);
  color: inherit;
  font: inherit;
  font-size: 14px;
  line-height: 1.5;
  resize: vertical;
  outline: none;
  box-sizing: border-box;
}

.diary-hl-input:focus {
  border-color: rgba(252, 190, 195, 0.9);
}

.diary-hl-input[readonly] {
  opacity: 0.7;
  cursor: default;
}

.diary-hl-sheet-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.diary-hl-btn {
  padding: 10px 18px;
  border: 0;
  border-radius: 12px;
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
