.diary-hl-btn.ghost {
  background: rgba(142, 101, 111, 0.1);
  color: #8e656f;
}

.diary-hl-btn.danger {
  background: rgba(224, 93, 93, 0.14);
  color: #c94d4d;
  margin-right: auto;
}

html[data-runwithme-theme="dark"] .diary-hl-sheet {
  background: rgba(30, 26, 30, 0.98);
  border-top-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 -12px 40px rgba(0, 0, 0, 0.5);
}

html[data-runwithme-theme="dark"] .diary-hl-sheet h3 {
  color: #fff2e9;
}

html[data-runwithme-theme="dark"] .diary-hl-quote {
  background: rgba(252, 190, 195, 0.12);
  color: #d9bcc4;
}

html[data-runwithme-theme="dark"] .diary-hl-input {
