html[data-runwithme-theme="dark"] .diary-hl-btn.primary {
  background: #fcbec3;
  color: #4f3940;
}

html[data-runwithme-theme="dark"] .diary-hl-btn.ghost {
  background: rgba(255, 255, 255, 0.08);
  color: #d9bcc4;
}

html[data-runwithme-theme="dark"] .diary-hl-btn.danger {
  background: rgba(224, 93, 93, 0.2);
  color: #eb9090;
}

/* ---------- 日记列表里的划线数 badge ---------- */

.notes-diary-hl-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(142, 101, 111, 0.12);
  color: #8e656f;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

html[data-runwithme-theme="dark"]
  .notes-diary-hl-badge {
  background: rgba(255, 255, 255, 0.1);
