.photo-text-card {
  position: relative;
  overflow: hidden;
}

.photo-text-card-main {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: hidden;
}

/* 底部一行：头像 + 角色 + 情绪 */

.photo-text-card-footer {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  padding-top: 10px;
  border-top: 1px solid rgba(142, 101, 111, 0.1);
  margin-top: 8px;
}

html[data-runwithme-theme="dark"] .photo-text-card-footer {
  border-top-color: rgba(255, 255, 255, 0.06);
}

.photo-text-card-footer-avatar {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;

  color: #fff2e9;
  font-size: 11px;
  font-weight: 700;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 1px 3px rgba(80, 50, 60, 0.12);
}

.photo-text-card-footer-avatar-levi {
  background: linear-gradient(140deg, #b08a93, #8e656f);
}

.photo-text-card-footer-avatar-erwin {
  background: linear-gradient(140deg, #b89aa0, #9b7f86);
}

.photo-text-card-footer-avatar.has-image {
  padding: 0;
  background: none;
  color: transparent;
}

.photo-text-card-footer-avatar.has-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  max-width: 100%;
  max-height: 100%;
}

.photo-text-card-footer-name {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.75;
}

.photo-text-card-footer-mood {
  margin-left: auto;
  font-size: 11px;
  font-style: italic;
  opacity: 0.55;
  white-space: nowrap;
}

/* ---------- 兜底：卡片内所有图片不得超过自身容器 ---------- */

.photo-text-card img {
  max-width: 100%;
  max-height: 100%;
}

/* ---------- 查看器：顶部卡片下方的元信息行 ---------- */

.photo-text-viewer-meta {
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #8e656f;
  opacity: 0.6;
  margin-top: -4px;
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-meta {
  color: #d9bcc4;
}

/* ---------- 卡片本体在查看器里：竖版、内容居中 ---------- */

.photo-text-viewer-cardwrap .photo-text-card {
  width: 100%;
  height: 100%;
}

.photo-text-viewer-cardwrap .photo-text-card-main {
  justify-content: center;
}

.photo-text-viewer-cardwrap .photo-text-card-place {
  font-size: 28px;
}

.photo-text-viewer-cardwrap .photo-text-card-line {
  font-size: 15px;
}
/* =========================================================
   B1.8 · 文字卡片查看器按钮（浅/深色都可见）
   ========================================================= */

.photo-text-viewer-btn {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(142, 101, 111, 0.12);
  border-radius: 50%;

  background: rgba(142, 101, 111, 0.08);
  color: #8e656f;

  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    transform 0.15s ease;
}

.photo-text-viewer-btn:hover {
  background: rgba(142, 101, 111, 0.16);
}

.photo-text-viewer-btn:active {
  transform: scale(0.94);
}

.photo-text-viewer-btn-danger {
  color: #c94d4d;
}

.photo-text-viewer-btn-danger:hover {
  background: rgba(224, 93, 93, 0.15);
}

.photo-text-viewer-btn svg {
  display: block;
  flex-shrink: 0;
}

/* ---------- 深色模式 ---------- */

html[data-runwithme-theme="dark"] .photo-text-viewer-btn {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
  color: #d9bcc4;
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-btn:hover {
  background: rgba(255, 255, 255, 0.12);
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-btn-danger {
  color: #eb9090;
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-btn-danger:hover {
  background: rgba(224, 93, 93, 0.2);
}

/* ---------- 顺便把旧的多余规则压掉 ---------- */

.photo-text-viewer-header .photo-viewer-btn {
  /* 若你 CSS 里还有这条旧规则，让它不再影响视觉 */
  background: unset;
  color: unset;
  border: unset;
  box-shadow: unset;
  backdrop-filter: unset;
  -webkit-backdrop-filter: unset;
}
/* =========================================================
   Chat 字号缩放
   ========================================================= */

.chat-page {
  --chat-fs-scale: 1.15;
}

.chat-page[data-fs="sm"] {
  --chat-fs-scale: 0.9;
}

.chat-page[data-fs="md"] {
  --chat-fs-scale: 1;
}

.chat-page[data-fs="lg"] {
  --chat-fs-scale: 1.15;
}

.chat-page[data-fs="xl"] {
  --chat-fs-scale: 1.3;
}

/* 气泡正文 */
.chat-page .message-bubble {
  font-size: calc(12px * var(--chat-fs-scale)) !important;
}

/* 名字 */
.chat-page .message-name {
  font-size: calc(9px * var(--chat-fs-scale)) !important;
}

/* 时间 / 已送达 */
.chat-page .message-time,
.chat-page .message-status {
  font-size: calc(9px * var(--chat-fs-scale)) !important;
}

/* 输入框 */
.chat-page .chat-input {
  font-size: calc(13px * var(--chat-fs-scale)) !important;
}

/* 拍一拍 */
.chat-page .chat-pat-message {
  font-size: calc(11px * var(--chat-fs-scale)) !important;
}

/* 系统消息 */
.chat-page .chat-system-message {
  font-size: calc(8px * var(--chat-fs-scale)) !important;
}

/* 引用块 */
.chat-page .message-quote-text {
  font-size: calc(9px * var(--chat-fs-scale)) !important;
}

/* 语音转文字 */
.chat-page .chat-voice-text {
  font-size: calc(12px * var(--chat-fs-scale)) !important;
}

/* 设置面板里的分段控件 */
.chat-settings-font-segment {
  display: flex;
  gap: 4px;
  padding: 4px;
  border-radius: 12px;
  background: rgba(142, 101, 111, 0.08);
}

.chat-settings-font-segment button {
  flex: 1;
  padding: 8px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.chat-settings-font-segment button.active {
  background: #fcbec3;
  color: #8e656f;
  font-weight: 700;
}

html[data-runwithme-theme="dark"]
  .chat-settings-font-segment {
  background: rgba(255, 255, 255, 0.05);
}

html[data-runwithme-theme="dark"]
  .chat-settings-font-segment
  button.active {
  background: rgba(252, 190, 195, 0.3);
  color: #f3dfe4;
}
/* =========================================================
   B2 · 文字卡发到 Chat / iCity
   ========================================================= */

/* ---------- Chat 里的文字卡片气泡 ---------- */

.chat-textcard-message {
  display: inline-block;
  max-width: 240px;
  width: 200px;
}

.chat-textcard-message .photo-text-card {
  padding: 12px 14px 10px;
  border-radius: 16px;
}

.chat-textcard-message .photo-text-card-place {
  font-size: 16px;
}

.chat-textcard-message .photo-text-card-line {
  font-size: 11px;
}

.chat-textcard-message .photo-text-card-footer {
  padding-top: 6px;
  margin-top: 6px;
}

.chat-textcard-message
  .photo-text-card-footer-avatar {
  width: 18px;
  height: 18px;
  font-size: 9px;
}

.chat-textcard-message
  .photo-text-card-footer-name {
  font-size: 9px;
}

.chat-textcard-message
  .photo-text-card-footer-mood {
  font-size: 10px;
}

/* ---------- iCity 帖子里的文字卡片 ---------- */

.icity-textcard {
  margin: 4px 0 10px;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  max-width: 320px;
}

.icity-textcard .photo-text-card {
  width: 100%;
  aspect-ratio: 3 / 4;
}

/* ---------- Photos 卡片上的"已发到"小标 ---------- */

.photo-text-card-sent {
  position: absolute;
  top: 6px;
  right: 6px;
  display: flex;
  gap: 3px;
  z-index: 3;
}

.photo-text-card-sent span {
  padding: 2px 6px;
  border-radius: 6px;
  background: rgba(142, 101, 111, 0.85);
  color: #fff2e9;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* ---------- 查看器里的"发到"按钮 ---------- */

.photo-text-viewer-send {
  display: flex;
  gap: 8px;
  max-width: 420px;
  margin: 0 auto;
  width: 100%;
}

.photo-text-viewer-send-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 11px 14px;
  border: 1px solid rgba(142, 101, 111, 0.18);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.6);
  color: #4f3940;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease,
    opacity 0.15s ease;
  -webkit-tap-highlight-color: transparent;
}

.photo-text-viewer-send-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.photo-text-viewer-send-btn:hover:not(:disabled) {
  background: rgba(252, 190, 195, 0.3);
}

.photo-text-viewer-send-btn.is-sent,
.photo-text-viewer-send-btn:disabled {
  opacity: 0.55;
  cursor: default;
  background: rgba(142, 101, 111, 0.1);
}

.photo-text-viewer-send-btn svg {
  display: block;
  flex-shrink: 0;
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-send-btn {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
  color: #fff2e9;
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-send-btn:hover:not(:disabled) {
  background: rgba(252, 190, 195, 0.15);
}

html[data-runwithme-theme="dark"]
  .photo-text-viewer-send-btn.is-sent,
html[data-runwithme-theme="dark"]
  .photo-text-viewer-send-btn:disabled {
  background: rgba(255, 255, 255, 0.03);
  color: #d9bcc4;
}
/* =========================================================
   E1 · 世界事件系统
   ========================================================= */

/* iCity 的引用块（复用 chat 的 message-quote） */
.message-quote-source-tag {
  display: inline-block;
  margin-left: 4px;
  padding: 0 5px;
  border-radius: 4px;
  background: rgba(142, 101, 111, 0.12);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.6;
}
/* =========================================================
   Chat 滚动兜底
   ========================================================= */

.chat-page .chat-messages {
  overscroll-behavior-y: contain;
  scroll-behavior: auto;
}

.chat-page .chat-messages > * {
  scroll-margin-bottom: 8px;
}
/* =========================================================
   M2 · 播放模式按钮 + 播放全部
   ========================================================= */

.music-v2-playmode-btn {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.music-v2-playmode-btn:hover {
