/* =========================================================
   M2-b · 歌单封面
   ========================================================= */

/* 歌单列表里的小封面 */
.music-playlist-item-icon {
  overflow: hidden;
  padding: 0;
}

.music-playlist-item-cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* 歌单详情里的大封面 */
.music-playlist-detail-cover-wrap {
  position: relative;
  width: 100%;
  max-width: 240px;
  aspect-ratio: 1 / 1;
  margin: 8px auto 16px;
}

.music-playlist-detail-cover {
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  border-radius: 20px;
  overflow: hidden;
  background: linear-gradient(
    145deg,
    rgba(252, 190, 195, 0.5),
    rgba(207, 222, 227, 0.5)
  );
  cursor: pointer;
  box-shadow:
    0 12px 30px rgba(142, 101, 111, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
  transition: transform 0.15s ease;
}

.music-playlist-detail-cover:hover {
  transform: translateY(-2px);
}

.music-playlist-detail-cover:active {
  transform: scale(0.98);
}

.music-playlist-detail-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.music-playlist-detail-cover-empty {
