html[data-runwithme-theme="dark"]
  .music-playlist-detail-cover-empty {
  color: #d9bcc4;
}
/* =========================================================
   M3 · Music 主页重构
   ========================================================= */

/* ---------- 主页 header 标题 ---------- */

.music-v2-title-wrap {
  flex: 1;
  min-width: 0;
  text-align: center;
}

.music-v2-page-title {
  font-size: 16px;
