}

.music-v2-page-sub {
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
  margin-top: 2px;
}

/* ---------- 一起听头像区 ---------- */

.music-together-bar {
  display: flex;
  justify-content: center;
  padding: 10px 16px 12px;
}

.together-avatars-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.together-avatars-btn {
