  padding: 20px 4px 8px;
  font-size: 11px;
  opacity: 0.5;
  font-style: italic;
  line-height: 1.5;
}

/* ---------- 歌曲列表 ---------- */

.music-song-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.music-song-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.5);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 0.15s ease,
    transform 0.12s ease;
}

.music-song-item:hover {
  background: rgba(255, 255, 255, 0.75);
}

.music-song-item:active {
  transform: scale(0.99);
}

.music-song-item.is-current {
  background: linear-gradient(
    135deg,
    rgba(252, 190, 195, 0.4),
    rgba(252, 190, 195, 0.2)
  );
}

html[data-runwithme-theme="dark"] .music-song-item {
  background: rgba(255, 255, 255, 0.05);
}

html[data-runwithme-theme="dark"]
  .music-song-item:hover {
  background: rgba(255, 255, 255, 0.08);
}

html[data-runwithme-theme="dark"]
  .music-song-item.is-current {
  background: rgba(252, 190, 195, 0.18);
}

.music-song-index {
  flex: 0 0 22px;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  opacity: 0.5;
  font-variant-numeric: tabular-nums;
}

.music-song-item.is-current .music-song-index {
  color: #c94d5a;
  opacity: 1;
}

html[data-runwithme-theme="dark"]
  .music-song-item.is-current
  .music-song-index {
  color: #fcbec3;
}

.music-song-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.music-song-text strong {
  font-size: 13px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-song-text small {
  font-size: 11px;
  opacity: 0.6;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- 空状态 ---------- */

.music-empty {
  padding: 60px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}

.music-empty-icon {
  font-size: 36px;
  opacity: 0.4;
  color: #8e656f;
}

html[data-runwithme-theme="dark"] .music-empty-icon {
  color: #d9bcc4;
}

.music-empty-title {
  font-size: 14px;
  font-weight: 700;
}

.music-empty-desc {
  font-size: 12px;
  opacity: 0.55;
}

/* ---------- 歌单详情 Hero ---------- */

.music-playlist-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 20px 0 24px;
}

.music-playlist-hero-cover {
  width: 200px;
  height: 200px;
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(
    145deg,
    rgba(252, 190, 195, 0.5),
    rgba(207, 222, 227, 0.5)
  );
  color: #8e656f;
  box-shadow:
    0 12px 30px rgba(80, 50, 60, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.music-playlist-hero-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.music-playlist-hero-name {
  font-size: 20px;
  font-weight: 700;
  text-align: center;
}

.music-playlist-hero-sub {
  font-size: 11px;
  opacity: 0.55;
}

html[data-runwithme-theme="dark"]
  .music-playlist-hero-cover {
  color: #d9bcc4;
}

/* ---------- 迷你播放器 ---------- */

.music-mini-player {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 8px 8px 12px;
  border-radius: 20px;

  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.78) 0%,
    rgba(255, 255, 255, 0.55) 48%,
    rgba(255, 255, 255, 0.7) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(28px) saturate(1.8);
  -webkit-backdrop-filter: blur(28px) saturate(1.8);
  box-shadow:
    0 14px 34px rgba(90, 60, 65, 0.15),
    0 3px 10px rgba(90, 60, 65, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);

  z-index: 20;
}

html[data-runwithme-theme="dark"]
  .music-mini-player {
  background: linear-gradient(
    135deg,
    rgba(72, 62, 70, 0.78) 0%,
    rgba(44, 38, 44, 0.6) 48%,
    rgba(60, 50, 58, 0.72) 100%
  );
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.5),
    0 3px 10px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.music-mini-player-info {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.music-mini-player-cover {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(
    145deg,
    rgba(252, 190, 195, 0.6),
    rgba(207, 222, 227, 0.6)
  );
  color: #8e656f;
}

.music-mini-player-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.music-mini-player-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.music-mini-player-text strong {
  font-size: 13px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-mini-player-text small {
  font-size: 11px;
  opacity: 0.6;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-mini-player-btn {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background 0.15s ease,
    transform 0.12s ease;
}

.music-mini-player-btn:active {
  transform: scale(0.92);
}

.music-mini-player-btn:hover {
  background: rgba(142, 101, 111, 0.1);
}

html[data-runwithme-theme="dark"]
  .music-mini-player-btn:hover {
  background: rgba(255, 255, 255, 0.08);
}

.music-mini-player-dots {
  font-size: 18px;
  font-weight: 700;
}

/* ---------- 全屏播放器 ---------- */

.music-fullplayer {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 0 24px;
  z-index: 50;
  overflow: hidden;
  animation: musicFullIn 0.35s cubic-bezier(0.32, 1, 0.68, 1);
}

@keyframes musicFullIn {
  from {
    transform: translateY(100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.music-fullplayer-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  padding: calc(env(safe-area-inset-top) + 12px) 0 8px;
}

.music-fullplayer-collapse {
  width: 44px;
  height: 44px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.music-fullplayer-collapse:hover {
  background: rgba(142, 101, 111, 0.08);
}

.music-fullplayer-avatars {
  flex-shrink: 0;
  display: flex;
  justify-content: center;
  padding: 8px 0 12px;
}

.music-fullplayer-disc {
  width: min(260px, 60vw);
  height: min(260px, 60vw);
  margin: 8px auto;
  padding: 0;
  border: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;

  background:
    radial-gradient(
      circle at 50% 50%,
      #1a1518 0%,
      #1a1518 28%,
      #2a2226 30%,
      #1a1518 32%,
      #2a2226 34%,
      #1a1518 36%,
      #2a2226 38%,
      #1a1518 40%,
      #2a2226 42%,
      #1a1518 44%,
      #2a2226 46%,
      #1a1518 48%
    );
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
  cursor: pointer;
  position: relative;
  flex-shrink: 0;
}

.music-fullplayer-disc.is-playing {
  animation: musicFullSpin 18s linear infinite;
}

@keyframes musicFullSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.music-fullplayer-disc-cover {
  width: 60%;
  height: 60%;
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    #fcbec3,
    #cfdee3
  );
  display: flex;
  align-items: center;
  justify-content: center;
  color: #8e656f;
  overflow: hidden;
  box-shadow:
    inset 0 0 0 6px rgba(26, 21, 24, 0.9),
    inset 0 0 0 8px rgba(255, 255, 255, 0.05);
}

.music-fullplayer-disc-cover.has-image {
  padding: 0;
  background: none;
}

.music-fullplayer-disc-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
  display: block;
}

.music-fullplayer-info {
  flex-shrink: 0;
  text-align: center;
  margin-top: 12px;
}

.music-fullplayer-title {
  font-size: 20px;
  font-weight: 700;
  word-break: break-word;
  margin-bottom: 4px;
}

.music-fullplayer-artist {
  font-size: 13px;
  opacity: 0.6;
}

.music-fullplayer-empty {
  font-size: 14px;
  opacity: 0.5;
}

.music-fullplayer-error {
  margin-top: 8px;
  font-size: 11px;
  color: #c94d5a;
}

.music-fullplayer-progress {
  flex-shrink: 0;
  margin-top: 20px;
}

.music-fullplayer-progress-bar {
  width: 100%;
  height: 4px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  border-radius: 99px;
  outline: none;
  cursor: pointer;
  background: linear-gradient(
    to right,
    #8e656f 0%,
    #8e656f var(--music-progress, 0%),
    rgba(142, 101, 111, 0.15) var(--music-progress, 0%),
    rgba(142, 101, 111, 0.15) 100%
  );
}

.music-fullplayer-progress-bar::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #8e656f;
  border: 2px solid #fff2e9;
  box-shadow: 0 2px 6px rgba(80, 50, 60, 0.2);
}

html[data-runwithme-theme="dark"]
  .music-fullplayer-progress-bar {
  background: linear-gradient(
    to right,
    #fcbec3 0%,
    #fcbec3 var(--music-progress, 0%),
    rgba(255, 255, 255, 0.15) var(--music-progress, 0%),
    rgba(255, 255, 255, 0.15) 100%
  );
}

html[data-runwithme-theme="dark"]
  .music-fullplayer-progress-bar::-webkit-slider-thumb {
  background: #fcbec3;
  border-color: #1a1518;
}

.music-fullplayer-time-row {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  font-size: 10px;
  opacity: 0.55;
  font-variant-numeric: tabular-nums;
}

.music-fullplayer-controls {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  margin-top: auto;
  padding: 20px 0
    calc(30px + env(safe-area-inset-bottom));
}

.music-fullplayer-btn {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background 0.15s ease,
    transform 0.12s ease;
}

.music-fullplayer-btn:hover {
  background: rgba(142, 101, 111, 0.1);
}

.music-fullplayer-btn:active {
  transform: scale(0.92);
}

.music-fullplayer-play-btn {
  width: 68px;
  height: 68px;
  flex-shrink: 0;
  border: none;
  border-radius: 50%;
  background: #8e656f;
  color: #fff2e9;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 12px 30px rgba(142, 101, 111, 0.3);
  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.music-fullplayer-play-btn:hover {
  transform: scale(1.05);
}

.music-fullplayer-play-btn:active {
  transform: scale(0.95);
}

.music-fullplayer-dots {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 2px;
}

.music-fullplayer-chat-fab {
  position: absolute;
  right: 24px;
  bottom: calc(120px + env(safe-area-inset-bottom));
  width: 44px;
  height: 44px;
  border: none;
  border-radius: 50%;
  background: rgba(142, 101, 111, 0.15);
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.music-fullplayer-chat-fab:hover {
  background: rgba(142, 101, 111, 0.25);
}

html[data-runwithme-theme="dark"]
  .music-fullplayer-chat-fab {
  background: rgba(255, 255, 255, 0.08);
}
/* =========================================================
   Music · 清空聊天按钮
   ========================================================= */

.music-chat-clear-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.music-chat-clear-btn:hover:not(:disabled) {
  background: rgba(224, 93, 93, 0.15);
  color: #c94d4d;
}

html[data-runwithme-theme="dark"]
  .music-chat-clear-btn:hover:not(:disabled) {
  background: rgba(224, 93, 93, 0.2);
  color: #eb9090;
}
/* =========================================================
   Music · 系统消息
   ========================================================= */

.music-chat-system {
  align-self: center;
  max-width: 85%;
  padding: 5px 12px;
  margin: 6px 0;
  border-radius: 999px;
  background: rgba(142, 101, 111, 0.1);
  color: #8e656f;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-align: center;
  word-break: break-word;
}

html[data-runwithme-theme="dark"] .music-chat-system {
  background: rgba(255, 255, 255, 0.06);
  color: #d9bcc4;
}
/* =========================================================
   Watch · iCity 概率滑块
   ========================================================= */

.watch-settings-slider {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.watch-settings-slider input[type="range"] {
  width: 120px;
  accent-color: #8e656f;
  cursor: pointer;
}

.watch-settings-slider span {
  min-width: 36px;
  text-align: right;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  opacity: 0.75;
}
/* =====================================================
   Netease Panel (M4-b)
   ===================================================== */

.music-nt-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 8px 2px 4px;
}

.music-nt-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 0;
  color: rgba(0, 0, 0, 0.45);
}

.music-nt-spin {
  animation: music-nt-spin 1s linear infinite;
}

@keyframes music-nt-spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ---------- 二维码 ---------- */

.music-nt-qr-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(0, 0, 0, 0.06);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
}

.music-nt-qr {
  width: 200px;
  height: 200px;
  display: block;
  border-radius: 10px;
  background: #fff;
}

.music-nt-qr-placeholder {
  width: 200px;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  color: rgba(0, 0, 0, 0.35);
}

.music-nt-hint {
  margin: 0;
  text-align: center;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.55);
}

.music-nt-status {
  margin: 0;
  text-align: center;
  font-size: 12px;
  color: rgba(0, 0, 0, 0.4);
}

.music-nt-retry {
  align-self: center;
  padding: 8px 16px;
  border-radius: 999px;
  border: none;
  background: rgba(0, 0, 0, 0.08);
  color: rgba(0, 0, 0, 0.75);
  font-size: 13px;
  cursor: pointer;
}

.music-nt-retry:hover {
  background: rgba(0, 0, 0, 0.12);
}

/* ---------- 已登录：用户条 ---------- */

.music-nt-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba(0, 0, 0, 0.06);
}

.music-nt-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.music-nt-avatar-empty {
  background: rgba(0, 0, 0, 0.08);
}

.music-nt-user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.music-nt-user-info strong {
  font-size: 13px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.85);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-nt-user-info small {
  font-size: 11px;
  color: rgba(0, 0, 0, 0.4);
}

.music-nt-logout {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: rgba(0, 0, 0, 0.45);
  cursor: pointer;
  flex-shrink: 0;
}

.music-nt-logout:hover {
  background: rgba(0, 0, 0, 0.06);
  color: rgba(0, 0, 0, 0.75);
}

/* ---------- 搜索框 ---------- */

.music-nt-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 6px 6px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(0, 0, 0, 0.08);
}

.music-nt-search input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 14px;
  color: inherit;
  min-width: 0;
}

.music-nt-search button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.08);
  color: rgba(0, 0, 0, 0.75);
  cursor: pointer;
  flex-shrink: 0;
}

.music-nt-search button:disabled {
  opacity: 0.5;
  cursor: default;
}

/* ---------- 结果列表 ---------- */

.music-nt-results {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 320px;
  overflow-y: auto;
  padding-right: 2px;
}

.music-nt-empty {
  padding: 30px 0;
  text-align: center;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.4);
}

.music-nt-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 8px 8px 6px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.music-nt-row-cover {
  width: 42px;
  height: 42px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
  background: rgba(0, 0, 0, 0.06);
}

.music-nt-row-cover-empty {
  background: rgba(0, 0, 0, 0.06);
}

.music-nt-row-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.music-nt-row-info strong {
  font-size: 13px;
  font-weight: 600;
  color: rgba(0, 0, 0, 0.85);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-nt-row-info small {
  font-size: 11px;
  color: rgba(0, 0, 0, 0.45);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-nt-row-add {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 10px;
