/* ============================================================
   Read 3D 翻页（2026-09-22）
   ============================================================ */
.read-reader .read-reader-stage-wrap {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.read-reader .read-stage {
  position: relative;
  width: 100%;
  height: 100%;
  perspective: 2200px;
  perspective-origin: 50% 50%;
  transform-style: preserve-3d;
}

.read-reader .read-page {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: transparent;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  transform-style: preserve-3d;
}

.read-reader .read-page-under {
  z-index: 1;
}

.read-reader .read-page-flip {
  z-index: 2;
  transform-origin: left center;
  will-change: transform;
  box-shadow:
    -4px 0 24px rgba(0, 0, 0, 0.14),
    0 0 40px rgba(0, 0, 0, 0.06);
}

html[data-runwithme-theme="dark"] .read-reader .read-page-flip {
  box-shadow:
    -4px 0 24px rgba(0, 0, 0, 0.55),
    0 0 40px rgba(0, 0, 0, 0.35);
}

.read-reader .read-page-inner {
  width: 100%;
  height: 100%;
  overflow: hidden;
  padding: 0;
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}

.read-reader .read-page-inner .read-reader-body {
  white-space: pre-wrap;
  word-break: break-word;
}

/* ============================================================
   Read 3D 翻页 — 光影加强（2026-09-22）
   ============================================================ */

/* 翻转页上的受光渐变：折痕处（左侧）最暗，向右逐渐变亮 */
.read-reader .read-page-flip-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 0.52) 0%,
    rgba(0, 0, 0, 0.3) 18%,
    rgba(0, 0, 0, 0.12) 45%,
    rgba(0, 0, 0, 0.03) 72%,
    transparent 92%
  );
}

/* 折痕处的细高光线，模拟纸张边缘反光 */
.read-reader .read-page-flip-edge {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 1.5px;
  z-index: 11;
  pointer-events: none;
  background: linear-gradient(
    to right,
    rgba(255, 255, 255, 0.5),
    rgba(255, 255, 255, 0)
  );
}

/* 底层页上的翻转页投影：从左边缘向右递减 */
.read-reader .read-page-under-shadow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 0.55) 0%,
    rgba(0, 0, 0, 0.34) 3%,
    rgba(0, 0, 0, 0.16) 9%,
    rgba(0, 0, 0, 0.05) 18%,
    transparent 34%
  );
}

/* 深色主题下阴影加深 */
html[data-runwithme-theme="dark"] .read-reader .read-page-flip-shade {
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 0.7) 0%,
    rgba(0, 0, 0, 0.42) 18%,
    rgba(0, 0, 0, 0.18) 45%,
    rgba(0, 0, 0, 0.05) 72%,
    transparent 92%
  );
}

html[data-runwithme-theme="dark"] .read-reader .read-page-under-shadow {
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 0.72) 0%,
    rgba(0, 0, 0, 0.48) 3%,
    rgba(0, 0, 0, 0.22) 9%,
    rgba(0, 0, 0, 0.06) 18%,
    transparent 34%
  );
}

html[data-runwithme-theme="dark"] .read-reader .read-page-flip-edge {
  background: linear-gradient(
    to right,
    rgba(255, 255, 255, 0.28),
    rgba(255, 255, 255, 0)
  );
}

/* 让翻转页走 GPU 合成层，减少重绘 */
.read-reader .read-page-flip {
  transform: translateZ(0);
  will-change: transform;
}

/* ============================================================
   Read 3D 舞台高度兜底（2026-09-22）
   确保 stage-wrap 从父级拿到高度，分页器才能启动
   ============================================================ */
.read-reader .read-reader-pad {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.read-reader .read-reader-stage-wrap {
  flex: 1 1 0%;
  min-height: 0;
  position: relative;
  width: 100%;
  overflow: hidden;
}
.app-icon-violet {
  background: linear-gradient(135deg, #a78bfa, #7c3aed);
}
/* ============================================================
   Tarot（2026-09-24）
   ============================================================ */
.tarot-app {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(circle at 30% 20%, rgba(120, 90, 180, 0.18), transparent 55%),
    radial-gradient(circle at 70% 80%, rgba(60, 40, 120, 0.22), transparent 55%),
    linear-gradient(180deg, #0a0714 0%, #120a24 50%, #0a0714 100%);
  color: #e8e0f5;
  font-family: "Songti SC", "Noto Serif SC", Georgia, serif;
  overflow: hidden;
}

.tarot-topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  padding-top: max(10px, env(safe-area-inset-top, 0px));
  border-bottom: 1px solid rgba(200, 180, 240, 0.12);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  flex-shrink: 0;
  z-index: 2;
}

.tarot-title {
  flex: 1;
  text-align: center;
  font-size: 15px;
  letter-spacing: 2px;
  color: #d8ceff;
}

.tarot-topbar-right {
  display: flex;
  gap: 6px;
  min-width: 36px;
  justify-content: flex-end;
}

.tarot-icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(200, 180, 240, 0.18);
  background: transparent;
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}

.tarot-icon-btn:hover {
  background: rgba(200, 180, 240, 0.1);
}

.tarot-content {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 20px 16px 40px;
}

/* ---------- Home ---------- */
.tarot-home {
  position: relative;
  padding-top: 20px;
}

.tarot-home-glow {
  position: absolute;
  top: -80px;
  left: 50%;
  transform: translateX(-50%);
  width: 340px;
  height: 340px;
  background: radial-gradient(circle, rgba(180, 140, 255, 0.25) 0%, transparent 65%);
  pointer-events: none;
  z-index: 0;
  animation: tarot-glow 8s ease-in-out infinite;
}

@keyframes tarot-glow {
  0%, 100% { opacity: 0.5; transform: translateX(-50%) scale(1); }
  50% { opacity: 0.9; transform: translateX(-50%) scale(1.15); }
}

.tarot-home-head {
  position: relative;
  z-index: 1;
  text-align: center;
  padding: 30px 0 40px;
}

.tarot-home-moon {
  color: #cdb8ff;
  filter: drop-shadow(0 0 18px rgba(200, 180, 255, 0.55));
  animation: tarot-moon 6s ease-in-out infinite;
}

@keyframes tarot-moon {
  0%, 100% { transform: translateY(0); opacity: 0.85; }
  50% { transform: translateY(-4px); opacity: 1; }
}

.tarot-home-title {
  margin-top: 14px;
  font-size: 34px;
  font-weight: 300;
  letter-spacing: 8px;
  color: #ede4ff;
  text-shadow: 0 0 24px rgba(200, 180, 255, 0.4);
}

.tarot-home-sub {
  margin-top: 10px;
  font-size: 13px;
  letter-spacing: 4px;
  opacity: 0.55;
  font-style: italic;
}

.tarot-mode-grid {
  display: grid;
  gap: 12px;
  position: relative;
  z-index: 1;
}

.tarot-mode-card {
  text-align: left;
  padding: 18px 20px;
  border-radius: 14px;
  border: 1px solid rgba(200, 180, 240, 0.2);
