/* ---------- Shuffle ---------- */
.tarot-shuffle {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 70vh;
  gap: 32px;
}

.tarot-shuffle-deck {
  position: relative;
