  height: 200px;
}

.tarot-shuffle-card {
  position: absolute;
  inset: 0;
  border-radius: 10px;
  border: 1px solid rgba(200, 180, 240, 0.35);
  background:
    repeating-linear-gradient(45deg, rgba(200, 180, 240, 0.08) 0 6px, transparent 6px 12px),
    linear-gradient(135deg, #2a1b50, #150a2e);
  box-shadow: 0 4px 20px rgba(120, 80, 200, 0.25);
  transform: rotate(0deg);
  transition: transform 1.2s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.9s ease 0.6s;
  opacity: 1;
}

.tarot-shuffle-card.is-flying {
  transform: translate(
    calc(var(--dir) * (40px + var(--i) * 14px)),
    calc((var(--i) - 4) * 12px)
  ) rotate(calc(var(--dir) * (15deg + var(--i) * 6deg)));
  opacity: 0;
}

.tarot-shuffle-text {
  font-size: 13px;
  letter-spacing: 6px;
