}

.tarot-record-card {
  display: flex;
  gap: 14px;
  padding: 14px;
  border-radius: 12px;
  border: 1px solid rgba(200, 180, 240, 0.14);
  background: rgba(30, 22, 55, 0.4);
}

.tarot-record-card-vis {
  width: 70px;
  height: 112px;
  flex-shrink: 0;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid rgba(200, 180, 240, 0.3);
}

.tarot-record-card-info {
  flex: 1;
  min-width: 0;
}

.tarot-record-card-name {
  font-size: 14px;
  letter-spacing: 1px;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.tarot-record-card-text {
  font-size: 12.5px;
  line-height: 1.7;
  opacity: 0.8;
  white-space: pre-wrap;
}

.tarot-danger {
  width: 100%;
  height: 46px;
  border-radius: 10px;
  border: 1px solid rgba(220, 100, 130, 0.5);
  background: rgba(220, 100, 130, 0.12);
  color: #ff9dbb;
  font-family: inherit;
  font-size: 13px;
  letter-spacing: 2px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.tarot-danger:hover {
  background: rgba(220, 100, 130, 0.22);
}
/* ============================================================
   Tarot AI 解读（2026-09-24）
