.tarot-ai-btn {
  margin-top: 8px;
}

.tarot-ai-block {
  margin-top: 24px;
  padding: 18px 18px 14px;
  border-radius: 14px;
  border: 1px solid rgba(200, 180, 240, 0.22);
  background: linear-gradient(135deg, rgba(60, 45, 100, 0.4), rgba(30, 22, 55, 0.5));
  position: relative;
  overflow: hidden;
}

.tarot-ai-block::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 10% 0%, rgba(200, 180, 255, 0.1), transparent 55%);
  pointer-events: none;
}

.tarot-ai-block-head {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 3px;
  color: #cdb8ff;
  margin-bottom: 12px;
  position: relative;
}

.tarot-ai-block-text {
  font-size: 13.5px;
  line-height: 1.9;
  white-space: pre-wrap;
  color: #e8e0f5;
  position: relative;
}

.tarot-ai-reopen {
  margin-top: 14px;
  height: 34px;
  padding: 0 14px;
  border-radius: 8px;
  border: 1px solid rgba(200, 180, 240, 0.28);
  background: transparent;
  color: #cdb8ff;
  font-family: inherit;
  font-size: 12px;
  letter-spacing: 2px;
  cursor: pointer;
  position: relative;
}

.tarot-ai-reopen:hover {
  background: rgba(200, 180, 240, 0.1);
}

.tarot-history-ai-tag {
  font-size: 10.5px;
  letter-spacing: 2px;
  color: #cdb8ff;
  opacity: 0.75;
}

/* ---------- AI Reading Panel ---------- */
.tarot-wb-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.tarot-wb-sheet {
  width: 100%;
  max-width: 640px;
  max-height: 88vh;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(circle at 50% 0%, rgba(120, 90, 180, 0.15), transparent 60%),
    linear-gradient(180deg, #161029 0%, #0c0818 100%);
  color: #e8e0f5;
  font-family: "Songti SC", "Noto Serif SC", Georgia, serif;
  border-top-left-radius: 18px;
  border-top-right-radius: 18px;
  border: 1px solid rgba(200, 180, 240, 0.25);
  box-shadow: 0 -8px 40px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.tarot-wb-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(200, 180, 240, 0.12);
  flex-shrink: 0;
}

.tarot-wb-header h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: 3px;
  color: #d8ceff;
}

.tarot-wb-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 20px 18px;
  -webkit-overflow-scrolling: touch;
}

.tarot-wb-tip {
  font-size: 12px;
  line-height: 1.7;
  opacity: 0.55;
  margin-bottom: 12px;
}

.tarot-wb-footer {
  display: flex;
  gap: 8px;
  padding: 12px 16px;
  padding-bottom: max(12px, env(safe-area-inset-bottom, 12px));
  border-top: 1px solid rgba(200, 180, 240, 0.12);
  flex-shrink: 0;
}

.tarot-btn {
  height: 44px;
  padding: 0 18px;
  border-radius: 10px;
  border: 1px solid rgba(200, 180, 240, 0.28);
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: 13px;
  letter-spacing: 2px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.tarot-btn.primary {
  background: linear-gradient(135deg, rgba(140, 100, 220, 0.55), rgba(80, 50, 160, 0.65));
  border-color: rgba(200, 180, 240, 0.5);
  color: #fff;
  box-shadow: 0 0 20px rgba(140, 100, 220, 0.3);
}

.tarot-btn:hover {
  opacity: 0.9;
}

.tarot-reading-start {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  padding: 60px 20px;
  text-align: center;
}

.tarot-reading-start-icon {
  color: #cdb8ff;
  filter: drop-shadow(0 0 20px rgba(200, 180, 255, 0.5));
  animation: tarot-moon 6s ease-in-out infinite;
}

.tarot-reading-start-text {
  font-size: 14px;
  letter-spacing: 3px;
  opacity: 0.7;
}

.tarot-reading-wait {
  text-align: center;
  font-size: 13px;
  letter-spacing: 3px;
  opacity: 0.6;
  padding: 40px 0;
  animation: tarot-pulse 1.8s ease-in-out infinite;
}

.tarot-reading-err {
  text-align: center;
  font-size: 13px;
  color: #ff9dbb;
  padding: 30px 20px;
  line-height: 1.8;
}

.tarot-reading-ai {
  font-size: 14px;
  line-height: 2;
  white-space: pre-wrap;
  color: #e8e0f5;
}